  int count = -1, i;
  int req_error;
  OR_ALIGNED_BUF (OR_INT_SIZE) a_request;
  char *request;
  int reply_size;
  char *reply, *ptr;

  request = OR_ALIGNED_BUF_START (a_request);
  reply_size = OR_INT_SIZE + (OR_INT_SIZE * size);
  reply = (char *) malloc (reply_size);
  if (reply == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, (size_t) reply_size);
      return -1;
    }

  or_pack_int (request, size);

  req_error =
    net_client_request (NET_SERVER_TM_SERVER_2PC_RECOVERY_PREPARED, request,
			OR_ALIGNED_BUF_SIZE (a_request), reply, reply_size, NULL, 0, NULL, 0);
  if (!req_error)
    {
      ptr = or_unpack_int (reply, &count);
      for (i = 0; i < count && i < size; i++)
	{
	  ptr = or_unpack_int (ptr, &gtrids[i]);
	}
    }
  free_and_init (reply);

  return count;
#else /* CS_MODE */
  int count;

  THREAD_ENTRY *thread_p = enter_server ();

  count = xtran_server_2pc_recovery_prepared (thread_p, gtrids, size);

  exit_server (*thread_p);

  return count;
#endif /* !CS_MODE */
}

