    net_client_request2 (NET_SERVER_SES_GET_LAST_INSERT_ID, request, OR_ALIGNED_BUF_SIZE (a_request),
			 reply, OR_ALIGNED_BUF_SIZE (a_reply), NULL, 0, &data_reply, &data_size);
  if (req_error != NO_ERROR)
    {
      db_make_null (value);
      req_error = ER_FAILED;
      goto cleanup;
    }

