int
loaddb_update_stats (bool verbose)
{
#if defined(CS_MODE)
  int rc = ER_FAILED;
  char *data_reply = NULL;
  int data_reply_size = 0;
  OR_ALIGNED_BUF (OR_INT_SIZE * 2) a_reply;
  char *reply = OR_ALIGNED_BUF_START (a_reply);
  OID oid;
  int oids_count;
  MOP classop;

  /* get class oid */
  int req_error = net_client_request2 (NET_SERVER_LD_UPDATE_STATS, NULL, 0, reply,
				       OR_ALIGNED_BUF_SIZE (a_reply), NULL, 0, &data_reply,
				       &data_reply_size);
  if (req_error != NO_ERROR)
    {
      return req_error;
    }

  char *ptr = or_unpack_int (reply, &data_reply_size);

  ptr = or_unpack_int (ptr, &rc);
  if (rc != NO_ERROR || data_reply_size == 0)
    {
      rc = ER_FAILED;
      goto cleanup;
    }

  /* unpack number of returned OIDs */
  ptr = or_unpack_int (data_reply, &oids_count);

  for (int i = 0; i < oids_count; i++)
    {
      ptr = or_unpack_oid (ptr, &oid);
      classop = ws_mop (&oid, NULL);
      assert (classop != NULL);
      if (classop != NULL)
	{
	  if (verbose)
	    {
	      const char *class_name_p = db_get_class_name (classop);
	      if (class_name_p != NULL)
		{
		  fprintf (stdout,
			   msgcat_message (MSGCAT_CATALOG_UTILS, MSGCAT_UTIL_SET_LOADDB, LOADDB_MSG_CLASS_TITLE),
			   class_name_p);
		  fflush (stdout);
		}
	    }
	  stats_update_statistics (classop, STATS_WITH_SAMPLING);
	}
    }

cleanup:
  if (data_reply != NULL)
    {
      free_and_init (data_reply);
    }

  return rc;
#else /* CS_MODE */
  return NO_ERROR;
#endif /* !CS_MODE */
}

int
pl_call (const cubpl::pl_signature & sig, const std::vector < std::reference_wrapper < DB_VALUE >> &args,
	 std::vector < DB_VALUE > &out_args, DB_VALUE & result)
{
  int req_error = NO_ERROR;
#if defined(CS_MODE)
  char *data_reply = NULL;
  int data_reply_size = 0;

  packing_packer packer;
  cubmem::extensible_block eb;
  packer.set_buffer_and_pack_all (eb, sig, args);

  {
    OR_ALIGNED_BUF (OR_INT_SIZE * 3) a_reply;
    char *reply = OR_ALIGNED_BUF_START (a_reply);

    req_error = net_client_request_method_callback (NET_SERVER_PL_CALL, eb.get_ptr (),
						    (int) packer.get_current_size (), reply,
						    OR_ALIGNED_BUF_SIZE (a_reply), &data_reply, &data_reply_size);
    if (req_error != NO_ERROR)
      {
	goto error;
      }

    /* consumes dummy reply */
    int dummy;
    char *ptr = or_unpack_int (reply, &dummy);
    ptr = or_unpack_int (ptr, &dummy);
    ptr = or_unpack_int (ptr, &dummy);

    /* receive result values / error */
    if (data_reply != NULL)
      {
	packing_unpacker unpacker (data_reply, (size_t) data_reply_size);
	if (data_reply_size > 0)
	  {
	    unpacker.unpack_all (result, out_args);
	  }
      }
    else
      {
	db_make_null (&result);
      }
  }

error:
  if (req_error != NO_ERROR)
    {
      packing_unpacker unpacker (data_reply, (size_t) data_reply_size);
      int error_code;
      std::string error_msg;
      if (data_reply_size > 0)
	{
	  unpacker.unpack_all (error_code, error_msg);
	  cubmethod::handle_method_error (error_code, error_msg);
	  req_error = error_code;
	}
    }

  if (data_reply != NULL)
    {
      free_and_init (data_reply);
    }

  return req_error;
#else
  packing_packer packer;
  cubmem::extensible_block eb;
  THREAD_ENTRY *thread_p = enter_server ();

  {
    DB_VALUE ret_value;
    cubpl::executor executor ((cubpl::pl_signature &) sig);
    req_error = executor.fetch_args_peek (args);
    if (req_error == NO_ERROR)
      {
	req_error = executor.execute (ret_value);
      }

    if (req_error == NO_ERROR)
      {
	/* 3) pack */
	packer.set_buffer_and_pack_all (eb, ret_value, executor.get_out_args ());
      }
    else
      {
	std::string err_msg;
	if (executor.get_stack ())
	  {
	    err_msg = executor.get_stack ()->get_error_message ();
	  }

	if (err_msg.empty () && req_error != ER_SP_EXECUTE_ERROR)
	  {
	    err_msg.assign (er_msg ());
	  }

	if (req_error != ER_SM_INVALID_METHOD_ENV)	/* FIXME: error possibly occured in builtin method, It should be handled at CAS */
	  {
	    er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_SP_EXECUTE_ERROR, 1, err_msg.c_str ());
	    req_error = ER_SP_EXECUTE_ERROR;
	  }

	packer.set_buffer_and_pack_all (eb, er_errid (), err_msg);
      }

    db_value_clear (&ret_value);
  }

  exit_server (*thread_p);

  // unpack after exit_server (): ownership of the private allocated objects should be out of server mode
  packing_unpacker unpacker (eb.get_ptr (), (size_t) packer.get_current_size ());
  if (req_error == NO_ERROR)
    {
      db_make_null (&result);
      unpacker.unpack_all (result, out_args);
    }
  else
    {
      int error_code;
      std::string error_msg;
      unpacker.unpack_all (error_code, error_msg);
      cubmethod::handle_method_error (error_code, error_msg);
    }

  return req_error;
#endif
}

int
flashback_get_and_show_summary (dynamic_array * class_list, const char *user, time_t start_time, time_t end_time,
				FLASHBACK_SUMMARY_INFO_MAP * summary, OID ** oid_list, char **invalid_class,
				time_t * invalid_time)
{
#if defined(CS_MODE)
  int error_code = ER_FAILED;

  int request_size = 0;
  char *request = NULL, *ptr, *start_ptr;
  int num_class = 0;

  int num_summary = 0;

  char classname[SM_MAX_IDENTIFIER_LENGTH];

  OR_ALIGNED_BUF (OR_INT_SIZE + OR_INT_SIZE) a_reply;
  char *reply = OR_ALIGNED_BUF_START (a_reply);
  char *area;
  int area_size;

  num_class = da_size (class_list);

  /* request : num class | class name list | user | start_time | end_time */
  request_size = OR_INT_SIZE + or_packed_string_length (user, NULL) + OR_INT64_SIZE + OR_INT64_SIZE;

  for (int i = 0; i < num_class; i++)
    {
      if (da_get (class_list, i, classname) != NO_ERROR)
	{
	  /* TODO : er_set() */
	  return ER_FAILED;
	}
      request_size += or_packed_string_length (classname, NULL);
    }

  request = (char *) malloc (request_size + MAX_ALIGNMENT);
  if (request == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, (size_t) request_size);
      return ER_OUT_OF_VIRTUAL_MEMORY;
    }

  ptr = start_ptr = PTR_ALIGN (request, MAX_ALIGNMENT);

  ptr = or_pack_int (ptr, num_class);
  for (int i = 0; i < num_class; i++)
    {
      if (da_get (class_list, i, classname) != NO_ERROR)
	{
	  free_and_init (request);
	  return ER_FAILED;
	}
      ptr = or_pack_string (ptr, classname);
    }
  ptr = or_pack_string (ptr, user);
  ptr = or_pack_int64 (ptr, start_time);
  ptr = or_pack_int64 (ptr, end_time);

  request_size = ptr - start_ptr;

  error_code =
    net_client_request2 (NET_SERVER_FLASHBACK_GET_SUMMARY, start_ptr, request_size, reply,
			 OR_ALIGNED_BUF_SIZE (a_reply), NULL, 0, &area, &area_size);

  if (error_code == NO_ERROR)
    {
      ptr = or_unpack_int (reply, &area_size);
      ptr = or_unpack_int (ptr, &error_code);

      if (error_code == ER_FLASHBACK_INVALID_CLASS)
	{
	  *invalid_class = (char *) calloc (area_size + 1, sizeof (char));
	  if (*invalid_class == NULL)
	    {
	      error_code = ER_OUT_OF_VIRTUAL_MEMORY;
	      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, area_size);
	    }

	  memcpy (*invalid_class, area, area_size);
	}
      else if (error_code == ER_FLASHBACK_INVALID_TIME)
	{
	  or_unpack_int64 (area, invalid_time);
	}
      else if (error_code == NO_ERROR)
	{
	  ptr = area;
	  /* area : OID list | summary info list  */
	  for (int i = 0; i < num_class; i++)
	    {
	      ptr = or_unpack_oid (ptr, &(*oid_list)[i]);
	    }

	  /* get summary info */
	  error_code = flashback_unpack_and_print_summary (&ptr, summary, class_list, *oid_list);
	}

      free_and_init (area);
    }

  free_and_init (request);

  return error_code;
#endif // CS_MODE
  return ER_NOT_IN_STANDALONE;
}

int
flashback_get_loginfo (int trid, char *user, OID * classlist, int num_class, LOG_LSA * start_lsa, LOG_LSA * end_lsa,
		       int *num_item, bool forward, char **info_list, int *invalid_class_idx)
{
#if defined(CS_MODE)
  int error_code = ER_FAILED;
  int request_size = 0;
  char *request = NULL, *ptr, *start_ptr;

  OR_ALIGNED_BUF (OR_INT_SIZE + OR_INT_SIZE) a_reply;
  char *reply = OR_ALIGNED_BUF_START (a_reply);
  char *area;
  int area_size;

  /* request with : tranid, user, num class, classlist, start_lsa, end_lsa, num_item, forward/backward */

  request_size =
    OR_INT_SIZE + or_packed_string_length (user,
					   NULL) + OR_INT_SIZE + OR_OID_SIZE * num_class + OR_LOG_LSA_ALIGNED_SIZE * 2 +
    OR_INT_SIZE + OR_INT_SIZE;

  request = (char *) malloc (request_size + MAX_ALIGNMENT);
  if (request == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, (size_t) request_size);
      return ER_OUT_OF_VIRTUAL_MEMORY;
    }

  ptr = start_ptr = PTR_ALIGN (request, MAX_ALIGNMENT);

  ptr = or_pack_int (ptr, trid);
  ptr = or_pack_string (ptr, user);
  ptr = or_pack_int (ptr, num_class);
  for (int i = 0; i < num_class; i++)
    {
      ptr = or_pack_oid (ptr, &classlist[i]);
    }
  ptr = or_pack_log_lsa (ptr, start_lsa);
  ptr = or_pack_log_lsa (ptr, end_lsa);
  ptr = or_pack_int (ptr, *num_item);
  ptr = or_pack_int (ptr, (int) forward);

  request_size = ptr - start_ptr;

  error_code =
    net_client_request2 (NET_SERVER_FLASHBACK_GET_LOGINFO, start_ptr, request_size, reply,
			 OR_ALIGNED_BUF_SIZE (a_reply), NULL, 0, &area, &area_size);

  if (error_code == NO_ERROR)
    {
      ptr = or_unpack_int (reply, &area_size);
      ptr = or_unpack_int (ptr, &error_code);

      if (error_code == ER_FLASHBACK_SCHEMA_CHANGED)
	{
	  OID invalid_classoid;

	  or_unpack_oid (area, &invalid_classoid);

	  *invalid_class_idx = flashback_find_class_index (classlist, num_class, invalid_classoid);
	}
      else if (error_code == NO_ERROR)
	{
	  /* area : start lsa | end lsa | num item | item list */
	  ptr = or_unpack_log_lsa (area, start_lsa);
	  ptr = or_unpack_log_lsa (ptr, end_lsa);
	  ptr = or_unpack_int (ptr, num_item);

	  ptr = PTR_ALIGN (ptr, MAX_ALIGNMENT);

	  *info_list = (char *) malloc (area_size - (ptr - area));
	  if (*info_list == NULL)
	    {
	      error_code = ER_OUT_OF_VIRTUAL_MEMORY;
	      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, area_size - (ptr - area));
	    }

	  memcpy (*info_list, ptr, area_size - (ptr - area));
	}

      free_and_init (area);
    }

  free_and_init (request);

  return error_code;
#endif // CS_MODE
  return ER_NOT_IN_STANDALONE;
}

int
plcsql_transfer_file (const PLCSQL_COMPILE_REQUEST & compile_request, PLCSQL_COMPILE_RESPONSE & compile_response)
{
  int req_error = NO_ERROR;
#if defined(CS_MODE)
  packing_packer packer;
  cubmem::extensible_block eb;
  char *ptr = NULL;

  char *data_reply = NULL;
  int data_reply_size = 0;

  packer.set_buffer_and_pack_all (eb, compile_request);

  OR_ALIGNED_BUF (3 * OR_INT_SIZE) a_reply;
  char *reply = OR_ALIGNED_BUF_START (a_reply);
  req_error = net_client_request_method_callback (NET_SERVER_PLCSQL_TRANSFER_FILE, eb.get_ptr (),
						  (int) packer.get_current_size (),
						  reply, OR_ALIGNED_BUF_SIZE (a_reply), &data_reply, &data_reply_size);
  if (req_error != NO_ERROR)
    {
      goto error;
    }

  /* consumes dummy reply */
  int dummy;
  ptr = or_unpack_int (reply, &dummy);
  ptr = or_unpack_int (ptr, &dummy);
  ptr = or_unpack_int (ptr, &dummy);

  /* receive result values / error */
  if (data_reply != NULL)
    {
      packing_unpacker unpacker (data_reply, (size_t) data_reply_size);
      if (data_reply_size > 0)
	{
	  unpacker.unpack_all (compile_response);
	}
    }

error:
  if (req_error != NO_ERROR)
    {
      if (data_reply != NULL)
	{
	  packing_unpacker unpacker (data_reply, (size_t) data_reply_size);
	  if (data_reply_size > 0)
	    {
	      unpacker.unpack_all (compile_response);
	    }
	}

      if (compile_response.err_code == NO_ERROR)
	{
	  compile_response.err_code = (er_errid () != NO_ERROR) ? er_errid () : req_error;
	  compile_response.err_msg = er_msg ()? er_msg () : "unknown compile error";
	}
    }

  if (data_reply != NULL)
    {
      free_and_init (data_reply);
    }

  return req_error;
#else /* CS_MODE */
  int success = ER_FAILED;

  cubmem::extensible_block eb;
  THREAD_ENTRY *thread_p = enter_server ();

  {
    cubpl::compile_handler compile_handler;
    success = compile_handler.compile (compile_request, eb);
  }

  exit_server (*thread_p);

  // unpack after exit_server (): ownership of the private allocated objects should be out of server mode
  if (success == NO_ERROR)
    {
      packing_unpacker unpacker (eb.get_ptr (), eb.get_size ());
      if (eb.get_size () > 0)
	{
	  unpacker.unpack_all (compile_response);
	}
    }
  else
    {
      compile_response.err_code = (er_errid () != NO_ERROR) ? er_errid () : success;
      compile_response.err_msg = er_msg ()? er_msg () : "unknown compile error";
    }

  return success;
#endif /* !CS_MODE */
}

int
mmon_get_server_info (MMON_SERVER_INFO & server_info)
{
#if defined(CS_MODE)
  char *buffer, *ptr, *temp_str;
  int bufsize = 0;
  OR_ALIGNED_BUF (OR_INT_SIZE + OR_INT_SIZE) a_reply;
  char *reply = OR_ALIGNED_BUF_START (a_reply);
  int req_error, dummy;
  int error = NO_ERROR;

  req_error =
    net_client_request2 (NET_SERVER_MMON_GET_SERVER_INFO, NULL, 0, reply,
			 OR_ALIGNED_BUF_SIZE (a_reply), NULL, 0, &buffer, &bufsize);

  if (req_error)
    {
      assert (er_errid () != NO_ERROR);
      error = er_errid ();
    }
  else
    {
      ptr = reply;
      ptr = or_unpack_int (ptr, &dummy);
      ptr = or_unpack_int (ptr, &error);
    }

  if (error == NO_ERROR)
    {
      // unpack server name
      ptr = or_unpack_string_nocopy (buffer, &temp_str);
      memcpy (server_info.server_name, temp_str, strlen (temp_str) + 1);

      // unpack server total memory usage
      ptr = or_unpack_int64 (ptr, (int64_t *) & (server_info.total_mem_usage));

      // unpack metainfo total memory usage
      ptr = or_unpack_int64 (ptr, (int64_t *) & (server_info.total_metainfo_mem_usage));

      // unpack the number of stat
      ptr = or_unpack_int (ptr, (int *) &(server_info.num_stat));

      // unpack file name and its memory usage
      server_info.stat_info.resize (server_info.num_stat);

      // *INDENT-OFF*
      // unpack memory usage entry info
      for (auto &s_info : server_info.stat_info)
        {
          ptr = or_unpack_string_nocopy (ptr, &temp_str);
          s_info.first = temp_str;
          ptr = or_unpack_int64 (ptr, (int64_t *) &(s_info.second));
        }
      // *INDENT-ON*
    }
  free_and_init (buffer);

  return error;
#else /* CS_MODE */
  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_NOT_IN_STANDALONE, 1, "memmon");
  return ER_NOT_IN_STANDALONE;
#endif /* !CS_MODE */
}

