  err = xsession_end_session (thread_p, id, (bool) is_keep_session);

  ptr = or_pack_int (reply, err);
  css_send_data_to_client (thread_p->conn_entry, rid, reply, OR_ALIGNED_BUF_SIZE (a_reply));
}

