  {
    if (buffer != NULL)
      {
	free (buffer);
      }
  };
  css_send_reply_and_data_to_client (thread_p->conn_entry, rid, reply, OR_ALIGNED_BUF_SIZE (a_reply), data_reply, size,
				     std::move (deleter));

  pr_clear_value (&result);
  pr_clear_value (&name);
}

