      return "INTEGER";

    case DB_TYPE_BIGINT:
      return "BIGINT";

    case DB_TYPE_SMALLINT:
      return "SHORT";

    case DB_TYPE_NUMERIC:
      return "NUMERIC";

    case DB_TYPE_FLOAT:
      return "FLOAT";

    case DB_TYPE_DOUBLE:
      return "DOUBLE";

    case DB_TYPE_DATE:
      return "DATE";

    case DB_TYPE_TIME:
      return "TIME";

    case DB_TYPE_TIMESTAMP:
      return "TIMESTAMP";

    case DB_TYPE_TIMESTAMPTZ:
      return "TIMESTAMPTZ";

    case DB_TYPE_TIMESTAMPLTZ:
      return "TIMESTAMPLTZ";

    case DB_TYPE_DATETIME:
      return "DATETIME";

    case DB_TYPE_DATETIMETZ:
      return "DATETIMETZ";

    case DB_TYPE_DATETIMELTZ:
      return "DATETIMELTZ";

    case DB_TYPE_MONETARY:
      return "MONETARY";


    case DB_TYPE_VARCHAR:
      return "VARCHAR";

    case DB_TYPE_CHAR:
      return "CHAR";

    case DB_TYPE_OID:
    case DB_TYPE_OBJECT:
      return "OBJECT";

    case DB_TYPE_SET:
      return "SET";

    case DB_TYPE_MULTISET:
      return "MULTISET";

    case DB_TYPE_SEQUENCE:
      return "SEQUENCE";

    case DB_TYPE_BIT:
      return "BIT";

    case DB_TYPE_VARBIT:
      return "BIT VARYING";

    case DB_TYPE_BLOB:
      return "BLOB";

    case DB_TYPE_CLOB:
      return "CLOB";

    case DB_TYPE_ENUMERATION:
      return "ENUM";
    case DB_TYPE_JSON:
      return "JSON";
    default:
      return "UNKNOWN DATA_TYPE";
    }
}

static int
qexec_schema_get_type_desc (DB_TYPE id, TP_DOMAIN * domain, DB_VALUE * result)
{
  const char *name = NULL;
  int precision = -1;
  int scale = -1;
  DB_ENUM_ELEMENT *enum_elements = NULL;
  int enum_elements_count = 0;
  TP_DOMAIN *setdomain = NULL;
  const char *set_of_string = NULL;
  JSON_VALIDATOR *validator = NULL;

  assert (domain != NULL && result != NULL);

  db_make_null (result);

  switch (id)
    {
    case DB_TYPE_NUMERIC:
      scale = domain->scale;
      [[fallthrough]];

    case DB_TYPE_VARCHAR:
    case DB_TYPE_CHAR:
    case DB_TYPE_BIT:
    case DB_TYPE_VARBIT:
      precision = domain->precision;
      break;

    case DB_TYPE_SET:
      setdomain = domain->setdomain;
      if (setdomain == NULL)
	{
	  return NO_ERROR;
	}
      set_of_string = "SET OF ";
      break;
    case DB_TYPE_MULTISET:
      setdomain = domain->setdomain;
      if (setdomain == NULL)
	{
	  return NO_ERROR;
	}
      set_of_string = "MULTISET OF ";
      break;
    case DB_TYPE_SEQUENCE:
      setdomain = domain->setdomain;
      if (setdomain == NULL)
	{
	  return NO_ERROR;
	}
      set_of_string = "SEQUENCE OF ";
      break;

    case DB_TYPE_ENUMERATION:
      enum_elements = domain->enumeration.elements;
      enum_elements_count = domain->enumeration.count;
      break;
    case DB_TYPE_JSON:
      validator = domain->json_validator;
      break;
    default:
      break;
    }

  name = qexec_schema_get_type_name_from_id (id);

  if (enum_elements)
    {
      DB_VALUE enum_arg1, enum_arg2, enum_result, *penum_arg1, *penum_arg2, *penum_result, *penum_temp;
      DB_DATA_STATUS data_stat;
      DB_VALUE quote, quote_comma_space, enum_;
      DB_VALUE braket;
      int i;

      assert (enum_elements_count >= 0);

      penum_arg1 = &enum_arg1;
      penum_arg2 = &enum_arg2;
      penum_result = &enum_result;

      db_make_string (&quote, "\'");
      db_make_string (&quote_comma_space, "\', ");
      db_make_string (&braket, ")");
      db_make_string (&enum_, "ENUM(");

      pr_clone_value (&enum_, penum_result);
      for (i = 0; i < enum_elements_count; i++)
	{
	  penum_temp = penum_arg1;
	  penum_arg1 = penum_result;
	  penum_result = penum_temp;
	  if ((db_string_concatenate (penum_arg1, &quote, penum_result, &data_stat) != NO_ERROR)
	      || (data_stat != DATA_STATUS_OK))
	    {
	      pr_clear_value (penum_arg1);
	      goto exit_on_error;
	    }
	  pr_clear_value (penum_arg1);

	  penum_temp = penum_arg1;
	  penum_arg1 = penum_result;
	  penum_result = penum_temp;

	  db_make_string (penum_arg2, enum_elements[i].str_val.medium.buf);
	  if ((db_string_concatenate (penum_arg1, penum_arg2, penum_result, &data_stat) != NO_ERROR)
	      || (data_stat != DATA_STATUS_OK))
	    {
	      pr_clear_value (penum_arg1);
	      pr_clear_value (penum_arg2);
	      goto exit_on_error;
	    }
	  pr_clear_value (penum_arg1);

	  penum_temp = penum_arg1;
	  penum_arg1 = penum_result;
	  penum_result = penum_temp;
	  if (i < enum_elements_count - 1)
	    {
	      if ((db_string_concatenate (penum_arg1, &quote_comma_space, penum_result, &data_stat) != NO_ERROR)
		  || (data_stat != DATA_STATUS_OK))
		{
		  pr_clear_value (penum_arg1);
		  pr_clear_value (penum_arg2);
		  goto exit_on_error;
		}
	    }
	  else
	    {
	      if ((db_string_concatenate (penum_arg1, &quote, penum_result, &data_stat) != NO_ERROR)
		  || (data_stat != DATA_STATUS_OK))
		{
		  pr_clear_value (penum_arg1);
		  pr_clear_value (penum_arg2);
		  goto exit_on_error;
		}
	    }
	  pr_clear_value (penum_arg1);
	  pr_clear_value (penum_arg2);
	}

      penum_temp = penum_arg1;
      penum_arg1 = penum_result;
      penum_result = penum_temp;
      if ((db_string_concatenate (penum_arg1, &braket, penum_result, &data_stat) != NO_ERROR)
	  || (data_stat != DATA_STATUS_OK))
	{
	  goto exit_on_error;
	}
      pr_clear_value (penum_arg1);
      pr_clone_value (penum_result, result);
      pr_clear_value (penum_result);

      return NO_ERROR;
    }
  else if (setdomain != NULL)
    {
      /* process sequence */
      DB_VALUE set_arg1, set_arg2, set_result, *pset_arg1, *pset_arg2, *pset_result, *pset_temp;
      DB_DATA_STATUS data_stat;
      DB_VALUE comma;
      char **ordered_names = NULL, *min, *temp;
      int count_names = 0, i, j, idx_min;

      for (setdomain = domain->setdomain; setdomain; setdomain = setdomain->next)
	{
	  count_names++;
	}

      ordered_names = (char **) malloc (count_names * sizeof (char *));
      if (ordered_names == NULL)
	{
	  return ER_OUT_OF_VIRTUAL_MEMORY;
	}

      for (setdomain = domain->setdomain, i = 0; setdomain; setdomain = setdomain->next, i++)
	{
	  ordered_names[i] = (char *) qexec_schema_get_type_name_from_id (setdomain->type->id);
	}

      for (i = 0; i < count_names - 1; i++)
	{
	  idx_min = i;
	  min = ordered_names[i];
	  for (j = i + 1; j < count_names; j++)
	    {
	      if (strcmp (ordered_names[i], ordered_names[j]) > 0)
		{
		  min = ordered_names[j];
		  idx_min = j;
		}
	    }

	  if (idx_min != i)
	    {
	      temp = ordered_names[i];
	      ordered_names[i] = ordered_names[idx_min];
	      ordered_names[idx_min] = temp;
	    }
	}

      pset_arg1 = &set_arg1;
      pset_arg2 = &set_arg2;
      pset_result = &set_result;

      db_make_string (&comma, ",");
      db_make_string (pset_result, set_of_string);

      for (setdomain = domain->setdomain, i = 0; setdomain; setdomain = setdomain->next, i++)
	{
	  pset_temp = pset_arg1;
	  pset_arg1 = pset_result;
	  pset_result = pset_temp;
	  db_make_string (pset_arg2, ordered_names[i]);
	  if ((db_string_concatenate (pset_arg1, pset_arg2, pset_result, &data_stat) != NO_ERROR)
	      || (data_stat != DATA_STATUS_OK))
	    {
	      free_and_init (ordered_names);
	      pr_clear_value (pset_arg1);
	      pr_clear_value (pset_arg2);
	      goto exit_on_error;
	    }
	  pr_clear_value (pset_arg1);
	  pr_clear_value (pset_arg2);

	  if (setdomain->next != NULL)
	    {
	      pset_temp = pset_arg1;
	      pset_arg1 = pset_result;
	      pset_result = pset_temp;
	      if ((db_string_concatenate (pset_arg1, &comma, pset_result, &data_stat) != NO_ERROR)
		  || (data_stat != DATA_STATUS_OK))
		{
		  free_and_init (ordered_names);
		  pr_clear_value (pset_arg1);
		  goto exit_on_error;
		}
	      pr_clear_value (pset_arg1);
	    }
	}

      pr_clone_value (pset_result, result);
      pr_clear_value (pset_result);
      free_and_init (ordered_names);
      return NO_ERROR;
    }
  else if (precision >= 0)
    {
      DB_VALUE db_int_scale, db_str_scale;
      DB_VALUE db_int_precision, db_str_precision;
      DB_VALUE prec_scale_result, prec_scale_arg1, *pprec_scale_arg1, *pprec_scale_result, *pprec_scale_temp;
      DB_VALUE comma, bracket1, bracket2;
      DB_DATA_STATUS data_stat;

      /* if numeric with default precision (float numeric), return "numeric" only */
      if (id == DB_TYPE_NUMERIC && precision == DB_DEFAULT_NUMERIC_PRECISION)
	{
	  db_make_string (result, name);
	  return NO_ERROR;
	}

      /* otherwise, format as "name(precision, scale)" */
      db_make_int (&db_int_precision, precision);
      db_make_null (&db_str_precision);
      if (tp_value_cast (&db_int_precision, &db_str_precision, &tp_String_domain, false) != DOMAIN_COMPATIBLE)
	{
	  goto exit_on_error;
	}
      pprec_scale_arg1 = &prec_scale_arg1;
      pprec_scale_result = &prec_scale_result;
      db_make_string (&comma, ",");
      db_make_string (&bracket1, "(");
      db_make_string (&bracket2, ")");
      db_make_string (pprec_scale_arg1, name);

      if ((db_string_concatenate (pprec_scale_arg1, &bracket1, pprec_scale_result, &data_stat) != NO_ERROR)
	  || (data_stat != DATA_STATUS_OK))
	{
	  pr_clear_value (pprec_scale_arg1);
	  goto exit_on_error;
	}
      pr_clear_value (pprec_scale_arg1);

      pprec_scale_temp = pprec_scale_arg1;
      pprec_scale_arg1 = pprec_scale_result;
      pprec_scale_result = pprec_scale_temp;
      if ((db_string_concatenate (pprec_scale_arg1, &db_str_precision, pprec_scale_result, &data_stat) != NO_ERROR)
	  || (data_stat != DATA_STATUS_OK))
	{
	  pr_clear_value (pprec_scale_arg1);
	  goto exit_on_error;
	}
      pr_clear_value (&db_str_precision);
      pr_clear_value (pprec_scale_arg1);

      if (scale >= 0)
	{
	  db_make_int (&db_int_scale, scale);
	  db_make_null (&db_str_scale);
	  if (tp_value_cast (&db_int_scale, &db_str_scale, &tp_String_domain, false) != DOMAIN_COMPATIBLE)
	    {
	      pr_clear_value (pprec_scale_result);
	      goto exit_on_error;
	    }

	  pprec_scale_temp = pprec_scale_arg1;
	  pprec_scale_arg1 = pprec_scale_result;
	  pprec_scale_result = pprec_scale_temp;
	  if ((db_string_concatenate (pprec_scale_arg1, &comma, pprec_scale_result, &data_stat) != NO_ERROR)
	      || (data_stat != DATA_STATUS_OK))
	    {
	      pr_clear_value (pprec_scale_arg1);
	      goto exit_on_error;
	    }
	  pr_clear_value (pprec_scale_arg1);

	  pprec_scale_temp = pprec_scale_arg1;
	  pprec_scale_arg1 = pprec_scale_result;
	  pprec_scale_result = pprec_scale_temp;
	  if ((db_string_concatenate (pprec_scale_arg1, &db_str_scale, pprec_scale_result, &data_stat) != NO_ERROR)
	      || (data_stat != DATA_STATUS_OK))
	    {
	      pr_clear_value (pprec_scale_arg1);
	      goto exit_on_error;
	    }
	  pr_clear_value (&db_str_scale);
	  pr_clear_value (pprec_scale_arg1);
	}

      pprec_scale_temp = pprec_scale_arg1;
      pprec_scale_arg1 = pprec_scale_result;
      pprec_scale_result = pprec_scale_temp;
      if ((db_string_concatenate (pprec_scale_arg1, &bracket2, pprec_scale_result, &data_stat) != NO_ERROR)
	  || (data_stat != DATA_STATUS_OK))
	{
	  pr_clear_value (pprec_scale_arg1);
	  goto exit_on_error;
	}
      pr_clear_value (pprec_scale_arg1);

      pr_clone_value (pprec_scale_result, result);
      pr_clear_value (pprec_scale_result);

      return NO_ERROR;
    }
  else if (validator != NULL)
    {
      DB_DATA_STATUS data_stat;
      DB_VALUE bracket1, bracket2, schema;
      bool err = false;

      if (db_json_get_schema_raw_from_validator (validator) != NULL)
	{
	  db_make_string (result, name);
	  db_make_string (&schema, db_json_get_schema_raw_from_validator (validator));
	  db_make_string (&bracket1, "(\'");
	  db_make_string (&bracket2, "\')");

	  if (db_string_concatenate (result, &bracket1, result, &data_stat) != NO_ERROR
	      || (data_stat != DATA_STATUS_OK)
	      || db_string_concatenate (result, &schema, result, &data_stat) != NO_ERROR
	      || (data_stat != DATA_STATUS_OK)
	      || db_string_concatenate (result, &bracket2, result, &data_stat) != NO_ERROR
	      || (data_stat != DATA_STATUS_OK))
	    {
	      err = true;
	    }

	  pr_clear_value (&schema);

	  if (err)
	    {
	      pr_clear_value (result);
	      goto exit_on_error;
	    }
	}
      return NO_ERROR;
    }
  else
    {
      db_make_string (result, name);
      return NO_ERROR;
    }

exit_on_error:
  return ER_FAILED;
}

static int
qexec_execute_build_columns (THREAD_ENTRY * thread_p, XASL_NODE * xasl, XASL_STATE * xasl_state)
{
  QFILE_TUPLE_RECORD tplrec = { NULL, 0 };
  int idx_incache = -1;
  OR_CLASSREP *rep = NULL;
  OR_INDEX *index = NULL;
  char *attr_name = NULL, *default_value_string = NULL;
  const char *default_expr_type_string = NULL, *default_expr_format = NULL;
  char *attr_comment = NULL;
  OR_ATTRIBUTE *volatile attrepr = NULL;
  DB_VALUE **out_values = NULL;
  REGU_VARIABLE_LIST regu_var_p;
  HEAP_SCANCACHE scan;
  bool scancache_inited = false;
  RECDES class_record;
  OID *class_oid = NULL;
  volatile int idx_val;
  volatile int error = NO_ERROR;
  int i, j, k, idx_all_attr, size_values, found_index_type = -1;
  bool search_index_type = true;
  BTID *btid;
  int index_type_priorities[] = { 1, 0, 1, 0, 2, 0 };
  int index_type_max_priority = 2;
  DB_VALUE def_order, attr_class_type;
  OR_ATTRIBUTE *all_class_attr[3];
  int all_class_attr_lengths[3];
  bool full_columns = false;
  char *string = NULL;
  int alloced_string = 0;
  HL_HEAPID save_heapid = 0;

  if (xasl == NULL || xasl_state == NULL)
    {
      return ER_FAILED;
    }

  for (regu_var_p = xasl->outptr_list->valptrp, i = 0; regu_var_p; regu_var_p = regu_var_p->next, i++)
    {
      if (REGU_VARIABLE_IS_FLAGED (&regu_var_p->value, REGU_VARIABLE_CLEAR_AT_CLONE_DECACHE))
	{
	  save_heapid = db_change_private_heap (thread_p, 0);
	  break;
	}
    }

  if (qexec_start_mainblock_iterations (thread_p, xasl, xasl_state) != NO_ERROR)
    {
      GOTO_EXIT_ON_ERROR;
    }

  heap_scancache_quick_start_root_hfid (thread_p, &scan);
  scancache_inited = true;

  assert (xasl_state != NULL);
  class_oid = &(xasl->spec_list->s.cls_node.cls_oid);

  if (heap_get_class_record (thread_p, class_oid, &class_record, &scan, PEEK) != S_SUCCESS)
    {
      GOTO_EXIT_ON_ERROR;
    }

  rep = heap_classrepr_get (thread_p, class_oid, &class_record, NULL_REPRID, &idx_incache);
  if (rep == NULL)
    {
      GOTO_EXIT_ON_ERROR;
    }

  size_values = xasl->outptr_list->valptr_cnt;
  out_values = (DB_VALUE **) malloc (size_values * sizeof (DB_VALUE *));
  if (out_values == NULL)
    {
      GOTO_EXIT_ON_ERROR;
    }

  for (regu_var_p = xasl->outptr_list->valptrp, i = 0; regu_var_p; regu_var_p = regu_var_p->next, i++)
    {
      out_values[i] = &(regu_var_p->value.value.dbval);
      pr_clear_value (out_values[i]);
    }

  all_class_attr[0] = rep->attributes;
  all_class_attr_lengths[0] = rep->n_attributes;
  all_class_attr[1] = rep->class_attrs;
  all_class_attr_lengths[1] = rep->n_class_attrs;
  all_class_attr[2] = rep->shared_attrs;
  all_class_attr_lengths[2] = rep->n_shared_attrs;

  if (xasl->spec_list->s.cls_node.schema_type == FULL_COLUMNS_SCHEMA)
    {
      full_columns = true;
    }

  for (idx_all_attr = 0; idx_all_attr < 3; idx_all_attr++)
    {
      /* attribute class type */
      db_make_int (&attr_class_type, idx_all_attr);
      error = db_value_coerce (&attr_class_type, out_values[0], db_type_to_db_domain (DB_TYPE_VARCHAR));
      if (error != NO_ERROR)
	{
	  GOTO_EXIT_ON_ERROR;
	}

      for (i = 0, attrepr = all_class_attr[idx_all_attr]; i < all_class_attr_lengths[idx_all_attr]; i++, attrepr++)
	{
	  idx_val = 1;
	  /* attribute def order */
	  db_make_int (&def_order, attrepr->def_order);
	  error = db_value_coerce (&def_order, out_values[idx_val++], db_type_to_db_domain (DB_TYPE_VARCHAR));
	  if (error != NO_ERROR)
	    {
	      GOTO_EXIT_ON_ERROR;
	    }

	  /* attribute name */
	  string = NULL;
	  alloced_string = 0;

	  error = or_get_attrname (&class_record, attrepr->id, &string, &alloced_string);
	  if (error != NO_ERROR)
	    {
	      ASSERT_ERROR ();
	      GOTO_EXIT_ON_ERROR;
	    }

	  attr_name = string;
	  db_make_string (out_values[idx_val], attr_name);
	  if (string != NULL && alloced_string == 1)
	    {
	      out_values[idx_val]->need_clear = true;
	    }
	  idx_val++;

	  /* attribute type */
	  (void) qexec_schema_get_type_desc (attrepr->type, attrepr->domain, out_values[idx_val++]);

	  /* collation */
	  if (full_columns)
	    {
	      switch (attrepr->type)
		{
		case DB_TYPE_VARCHAR:
		case DB_TYPE_CHAR:
		case DB_TYPE_ENUMERATION:
		  db_make_string (out_values[idx_val], lang_get_collation_name (attrepr->domain->collation_id));
		  break;
		default:
		  db_make_null (out_values[idx_val]);
		}
	      idx_val++;
	    }

	  /* attribute can store NULL ? */
	  if (attrepr->is_notnull == 0)
	    {
	      db_make_string (out_values[idx_val], "YES");
	    }
	  else
	    {
	      db_make_string (out_values[idx_val], "NO");
	    }
	  idx_val++;

	  /* attribute has index or not */
	  found_index_type = -1;
	  search_index_type = true;
	  for (j = 0; j < attrepr->n_btids && search_index_type; j++)
	    {
	      btid = attrepr->btids + j;

	      for (k = 0; k < rep->n_indexes; k++)
		{
		  index = rep->indexes + k;
		  if (BTID_IS_EQUAL (btid, &index->btid))
		    {
		      if (found_index_type == -1
			  || index_type_priorities[index->type] > index_type_priorities[found_index_type])
			{
			  found_index_type = index->type;
			  if (index_type_priorities[found_index_type] == index_type_max_priority)
			    {
			      /* stop searching */
			      search_index_type = false;
			    }
			}
		      break;
		    }
		}
	    }

	  switch (found_index_type)
	    {
	    case BTREE_UNIQUE:
	    case BTREE_REVERSE_UNIQUE:
	      db_make_string (out_values[idx_val], "UNI");
	      break;

	    case BTREE_INDEX:
	    case BTREE_REVERSE_INDEX:
	    case BTREE_FOREIGN_KEY:
	      db_make_string (out_values[idx_val], "MUL");
	      break;

	    case BTREE_PRIMARY_KEY:
	      db_make_string (out_values[idx_val], "PRI");
	      break;

	    default:
	      db_make_string (out_values[idx_val], "");
	      break;
	    }
	  idx_val++;

	  /* default values */
	  alloced_string = 0;
	  if (attrepr->default_value.default_expr.default_expr_type != DB_DEFAULT_NONE)
	    {
	      const char *default_expr_op_string = NULL;

	      default_expr_type_string =
		db_default_expression_string (attrepr->default_value.default_expr.default_expr_type);
	      if (!default_expr_type_string)
		{
		  default_expr_type_string = "";
		}

	      if (attrepr->default_value.default_expr.default_expr_op == T_TO_CHAR)
		{
		  size_t len;

		  default_expr_op_string = qdump_operator_type_string (T_TO_CHAR);
		  default_expr_format = attrepr->default_value.default_expr.default_expr_format;

		  len = ((default_expr_op_string ? strlen (default_expr_op_string) : 0)
			 + 6 /* parenthesis, a comma, a blank and quotes */  + strlen (default_expr_type_string)
			 + (default_expr_format ? strlen (default_expr_format) : 0)) + 1;

		  default_value_string = (char *) db_private_alloc (thread_p, len);
		  if (default_value_string == NULL)
		    {
		      GOTO_EXIT_ON_ERROR;
		    }

		  if (default_expr_format)
		    {
		      snprintf (default_value_string, len, "%s(%s, \'%s\')", default_expr_op_string,
				default_expr_type_string, default_expr_format);
		    }
		  else
		    {
		      snprintf (default_value_string, len, "%s(%s)", default_expr_op_string, default_expr_type_string);
		    }

		  db_make_string (out_values[idx_val], default_value_string);
		  out_values[idx_val]->need_clear = true;
		}
	      else
		{
		  if (default_expr_type_string)
		    {
		      db_make_string (out_values[idx_val], default_expr_type_string);
		    }
		}
	      idx_val++;
	    }
	  else if (attrepr->current_default_value.value == NULL || attrepr->current_default_value.val_length <= 0)
	    {
	      db_make_null (out_values[idx_val]);
	      idx_val++;
	    }
	  else
	    {
	      error = qexec_get_attr_default (thread_p, attrepr, out_values[idx_val]);
	      if (error != NO_ERROR)
		{
		  GOTO_EXIT_ON_ERROR;
		}
	      if (!DB_IS_NULL (out_values[idx_val]))
		{
		  valcnv_convert_value_to_string (out_values[idx_val]);
		}
	      idx_val++;
	    }

	  if (!attrepr->is_autoincrement && !attrepr->is_invisible && attrepr->on_update_expr == DB_DEFAULT_NONE)
	    {
	      db_make_string (out_values[idx_val], "");
	    }
	  else
	    {
	      /* Extra: attribute is auto-increment, invisible, or has an ON UPDATE clause */
	      const char *is_auto_increment_string = "auto_increment";
	      const char *is_invisible_string = "invisible";
	      const char *on_update_string = "ON UPDATE ";
	      const char *default_expr_op_string = NULL;
	      size_t used = 0;
	      int written = 0;

	      size_t str_len = (attrepr->is_autoincrement ? strlen (is_auto_increment_string) : 0) + 1
		+ (attrepr->is_invisible ? strlen (is_invisible_string) : 0) + 1
		+ (attrepr->on_update_expr != DB_DEFAULT_NONE ? strlen (on_update_string) : 0) + 1;

	      if (attrepr->on_update_expr != DB_DEFAULT_NONE)
		{
		  default_expr_op_string = db_default_expression_string (attrepr->on_update_expr);
		  if (default_expr_op_string == NULL)
		    {
		      GOTO_EXIT_ON_ERROR;
		    }
		  str_len += strlen (default_expr_op_string);
		}
	      char *str_val = (char *) db_private_alloc (thread_p, str_len);
	      if (str_val == NULL)
		{
		  GOTO_EXIT_ON_ERROR;
		}

	      written = snprintf (str_val, str_len, "%s", (attrepr->is_autoincrement ? is_auto_increment_string : ""));
	      if (written < 0)
		{
		  GOTO_EXIT_ON_ERROR;
		}
	      used += written;
	      if (attrepr->is_invisible)
		{
		  written = snprintf (str_val + used, str_len - used, "%s%s", used ? " " : "", is_invisible_string);
		  if (written < 0)
		    {
		      GOTO_EXIT_ON_ERROR;
		    }
		  used += written;
		}

	      if (attrepr->on_update_expr != DB_DEFAULT_NONE)
		{
		  written =
		    snprintf (str_val + used, str_len - used, "%s%s%s", used ? " " : "", on_update_string,
			      default_expr_op_string);
		  if (written < 0)
		    {
		      GOTO_EXIT_ON_ERROR;
		    }
		  used += written;
		}

	      db_make_string (out_values[idx_val], str_val);
	      out_values[idx_val]->need_clear = true;
	    }
	  idx_val++;

	  /* attribute's comment */
	  if (full_columns)
	    {
	      int alloced_string = 0;
	      char *string = NULL;

	      error = or_get_attrcomment (&class_record, attrepr->id, &string, &alloced_string);
	      if (error != NO_ERROR)
		{
		  ASSERT_ERROR ();
		  return error;
		}

	      attr_comment = string;
	      db_make_string (out_values[idx_val], attr_comment);
	      if (string != NULL && alloced_string == 1)
		{
		  out_values[idx_val]->need_clear = true;
		}
	      idx_val++;
	    }

	  qexec_end_one_iteration (thread_p, xasl, xasl_state, &tplrec);

	  for (j = 1; j < size_values; j++)
	    {
	      pr_clear_value (out_values[j]);
	    }
	}
      pr_clear_value (out_values[0]);
    }

  free_and_init (out_values);

  heap_classrepr_free_and_init (rep, &idx_incache);
  if (heap_scancache_end (thread_p, &scan) != NO_ERROR)
    {
      GOTO_EXIT_ON_ERROR;
    }
  scancache_inited = false;

  if (qexec_end_mainblock_iterations (thread_p, xasl, xasl_state, &tplrec) != NO_ERROR)
    {
      GOTO_EXIT_ON_ERROR;
    }

  if (tplrec.tpl)
    {
      db_private_free_and_init (thread_p, tplrec.tpl);
    }

  if (save_heapid != 0)
    {
      (void) db_change_private_heap (thread_p, save_heapid);
      save_heapid = 0;
    }

  return NO_ERROR;

exit_on_error:

  if (out_values)
    {
      for (i = 0; i < size_values; i++)
	{
	  pr_clear_value (out_values[i]);
	}

      free_and_init (out_values);
    }

  if (rep)
    {
      heap_classrepr_free_and_init (rep, &idx_incache);
    }

  if (scancache_inited)
    {
      heap_scancache_end (thread_p, &scan);
    }

#if defined(SERVER_MODE)
  /* query execution error must be set up before qfile_close_list(). */
  if (er_errid () < 0)
    {
      qmgr_set_query_error (thread_p, xasl_state->query_id);
    }
#endif

  qfile_close_list (thread_p, xasl->list_id);

  if (tplrec.tpl)
    {
      db_private_free_and_init (thread_p, tplrec.tpl);
    }

  if (save_heapid != 0)
    {
      (void) db_change_private_heap (thread_p, save_heapid);
      save_heapid = 0;
    }

  xasl->status = XASL_FAILURE;

  qexec_failure_line (__LINE__, xasl_state);

  return (error == NO_ERROR && (error = er_errid ()) == NO_ERROR) ? ER_FAILED : error;
}

static int
qexec_create_internal_classes (THREAD_ENTRY * thread_p, UPDDEL_CLASS_INFO * query_classes, int count,
			       UPDDEL_CLASS_INFO_INTERNAL ** internal_classes)
{
  UPDDEL_CLASS_INFO_INTERNAL *class_ = NULL, *classes = NULL;
  UPDDEL_CLASS_INFO *query_class = NULL;
  size_t size;
  int i = 0, error = NO_ERROR;

  if (internal_classes == NULL)
    {
      assert (false);
      return ER_FAILED;
    }
  *internal_classes = NULL;

  size = count * sizeof (UPDDEL_CLASS_INFO_INTERNAL);
  classes = (UPDDEL_CLASS_INFO_INTERNAL *) db_private_alloc (thread_p, size);
  if (classes == NULL)
    {
      return ER_FAILED;
    }

  /* initialize internal structures */
  for (i = 0; i < count; i++)
    {
      query_class = query_classes + i;
      class_ = &(classes[i]);
      class_->oid = NULL;
      class_->class_hfid = NULL;
      class_->class_oid = NULL;
      class_->needs_pruning = DB_NOT_PARTITIONED_CLASS;
      class_->subclass_idx = -1;
      class_->scan_cache = NULL;
      OID_SET_NULL (&class_->prev_class_oid);
      class_->is_attr_info_inited = 0;

      class_->num_lob_attrs = 0;
      class_->lob_attr_ids = NULL;
      class_->crt_del_lob_info = NULL;
      class_->m_unique_stats.construct ();
      class_->extra_assign_reev_cnt = 0;
      class_->mvcc_extra_assign_reev = NULL;
      class_->mvcc_reev_assigns = NULL;

      partition_init_pruning_context (&class_->context);

      class_->m_inited_scancache = false;

      if (query_class->needs_pruning)
	{
	  /* set partition information here */
	  class_->needs_pruning = query_class->needs_pruning;
	  error =
	    partition_load_pruning_context (thread_p, &query_class->class_oid[0], class_->needs_pruning,
					    &class_->context);
	  if (error != NO_ERROR)
	    {
	      goto exit_on_error;
	    }
	}
    }

  *internal_classes = classes;

  return NO_ERROR;

exit_on_error:
  if (classes)
    {
      qexec_clear_internal_classes (thread_p, classes, i + 1);
      db_private_free (thread_p, classes);
    }

  return (error == NO_ERROR) ? NO_ERROR : er_errid ();

}

static int
qexec_create_mvcc_reev_assignments (THREAD_ENTRY * thread_p, XASL_NODE * aptr, bool should_delete,
				    UPDDEL_CLASS_INFO_INTERNAL * classes, int num_classes, int num_assignments,
				    UPDATE_ASSIGNMENT * assignments, UPDATE_MVCC_REEV_ASSIGNMENT ** mvcc_reev_assigns)
{
  int idx, new_assign_idx, count;
  UPDDEL_CLASS_INFO_INTERNAL *claz = NULL;
  UPDATE_ASSIGNMENT *assign = NULL;
  UPDATE_MVCC_REEV_ASSIGNMENT *new_assigns = NULL, *new_assign = NULL, *prev_new_assign = NULL;
  REGU_VARIABLE_LIST regu_var = NULL;
  OUTPTR_LIST *outptr_list = NULL;

  if (mvcc_reev_assigns == NULL || !num_assignments)
    {
      return NO_ERROR;
    }

  outptr_list = aptr->outptr_list;

  count = aptr->upd_del_class_cnt + aptr->mvcc_reev_extra_cls_cnt;
  /* skip OID - CLASS OID pairs and should_delete */
  for (idx = 0, regu_var = outptr_list->valptrp; idx < count; idx++, regu_var = regu_var->next->next)
    ;

  if (should_delete)
    {
      regu_var = regu_var->next;
    }

  new_assigns =
    (UPDATE_MVCC_REEV_ASSIGNMENT *) db_private_alloc (thread_p, sizeof (UPDATE_MVCC_REEV_ASSIGNMENT) * num_assignments);
  if (new_assigns == NULL)
    {
      return ER_FAILED;
    }

  for (idx = 0, new_assign_idx = 0; idx < num_assignments; idx++)
    {
      assign = &assignments[idx];
      claz = &classes[assign->cls_idx];

      new_assign = &new_assigns[new_assign_idx++];
      new_assign->constant = assign->constant;
      if (new_assign->constant == NULL)
	{
	  new_assign->regu_right = &regu_var->value;
	  regu_var = regu_var->next;
	}
      else
	{
	  new_assign->regu_right = NULL;
	}
      new_assign->next = NULL;
      if (claz->mvcc_reev_assigns == NULL)
	{
	  claz->mvcc_reev_assigns = new_assign;
	}
      else
	{
	  prev_new_assign = claz->mvcc_reev_assigns;
	  while (prev_new_assign->next != NULL)
	    {
	      prev_new_assign = prev_new_assign->next;
	    }
	  prev_new_assign->next = new_assign;
	}
    }

  *mvcc_reev_assigns = new_assigns;

  return NO_ERROR;
}

static void
qexec_clear_internal_classes (THREAD_ENTRY * thread_p, UPDDEL_CLASS_INFO_INTERNAL * classes, int count)
{
  int i;
  UPDDEL_CLASS_INFO_INTERNAL *cls_int = NULL;

  for (i = 0; i < count; i++)
    {
      cls_int = &classes[i];
      if (cls_int->m_inited_scancache)
	{
	  locator_end_force_scan_cache (thread_p, &cls_int->m_scancache);
	}
      cls_int->m_unique_stats.clear ();
      if (cls_int->is_attr_info_inited)
	{
	  heap_attrinfo_end (thread_p, &cls_int->attr_info);
	}
      if (cls_int->needs_pruning)
	{
	  partition_clear_pruning_context (&cls_int->context);
	}
      if (cls_int->mvcc_extra_assign_reev != NULL)
	{
	  db_private_free_and_init (thread_p, cls_int->mvcc_extra_assign_reev);
	}
      cls_int->m_unique_stats.destruct ();
    }
}

static int
qexec_upddel_mvcc_set_filters (THREAD_ENTRY * thread_p, XASL_NODE * aptr_list,
			       UPDDEL_MVCC_COND_REEVAL * mvcc_reev_class, OID * class_oid)
{
  ACCESS_SPEC_TYPE *curr_spec = NULL;

  while (aptr_list != NULL && curr_spec == NULL)
    {
      curr_spec = aptr_list->spec_list;
      while (curr_spec != NULL && !OID_EQ (&(curr_spec->s.cls_node.cls_oid), class_oid))
	{
	  curr_spec = curr_spec->next;
	}
      aptr_list = aptr_list->scan_ptr;
    }

  if (curr_spec == NULL)
    {
      return ER_FAILED;
    }

  mvcc_reev_class->init (curr_spec->s_id);
  mvcc_reev_class->cls_oid = *class_oid;

  return NO_ERROR;
}

static int
qexec_upddel_setup_current_class (THREAD_ENTRY * thread_p, UPDDEL_CLASS_INFO * query_class,
				  UPDDEL_CLASS_INFO_INTERNAL * internal_class, int op_type, OID * current_oid)
{
  int i = 0;
  int error = NO_ERROR;

  internal_class->class_oid = NULL;
  internal_class->class_hfid = NULL;

  /* Find class HFID */
  if (internal_class->needs_pruning)
    {
      /* test root class */
      if (OID_EQ (&query_class->class_oid[0], current_oid))
	{
	  internal_class->class_oid = &query_class->class_oid[0];
	  internal_class->class_hfid = &query_class->class_hfid[0];
	  internal_class->subclass_idx = 0;

	  internal_class->num_lob_attrs = 0;
	  internal_class->lob_attr_ids = NULL;
	}
      else
	{
	  /* look through the class partitions for the current_oid */
	  for (i = 0; i < internal_class->context.count; i++)
	    {
	      if (OID_EQ (&internal_class->context.partitions[i].class_oid, current_oid))
		{
		  internal_class->class_oid = &internal_class->context.partitions[i].class_oid;
		  internal_class->class_hfid = &internal_class->context.partitions[i].class_hfid;
		  internal_class->subclass_idx = 0;

		  internal_class->num_lob_attrs = 0;
		  internal_class->lob_attr_ids = NULL;
		  break;
		}
	    }
	}
    }
  else
    {
      /* look through subclasses */
      for (i = 0; i < query_class->num_subclasses; i++)
	{
	  if (OID_EQ (&query_class->class_oid[i], current_oid))
	    {
	      internal_class->class_oid = &query_class->class_oid[i];
	      internal_class->class_hfid = &query_class->class_hfid[i];
	      internal_class->subclass_idx = i;

	      if (query_class->num_lob_attrs && query_class->lob_attr_ids)
		{
		  internal_class->num_lob_attrs = query_class->num_lob_attrs[i];
		  internal_class->lob_attr_ids = query_class->lob_attr_ids[i];
		}
	      else
		{
		  internal_class->num_lob_attrs = 0;
		  internal_class->lob_attr_ids = NULL;
		}
	      break;
	    }
	}
    }

  if (internal_class->class_hfid == NULL)
    {
      return ER_FAILED;
    }

  /* Start a HEAP_SCANCACHE object on the new class. Partitioned classes and class hierarchies are handled differently */
  if (internal_class->needs_pruning)
    {
      /* Get a scan_cache object from the pruning context. We don't close the previous one here, it will be closed when
       * the pruning context is cleared. */
      PRUNING_SCAN_CACHE *pcache = NULL;
      pcache =
	locator_get_partition_scancache (&internal_class->context, internal_class->class_oid,
					 internal_class->class_hfid, op_type, false);
      if (pcache == NULL)
	{
	  return ER_FAILED;
	}
      internal_class->scan_cache = &pcache->scan_cache;
    }
  else
    {
      if (internal_class->m_inited_scancache)
	{
	  if (query_class->has_uniques && BTREE_IS_MULTI_ROW_OP (op_type))
	    {
	      /* In this case, consider class hierarchy as well as single class. Therefore, construct the local
	       * statistical information by collecting the statistical information during scanning on each class of
	       * class hierarchy. */
	      qexec_update_btree_unique_stats_info (thread_p, &internal_class->m_unique_stats,
						    &internal_class->m_scancache);
	    }
	  (void) locator_end_force_scan_cache (thread_p, &internal_class->m_scancache);
	  internal_class->m_inited_scancache = false;
	}
      error =
	locator_start_force_scan_cache (thread_p, &internal_class->m_scancache, internal_class->class_hfid,
					internal_class->class_oid, op_type);
      if (error != NO_ERROR)
	{
	  return error;
	}
      internal_class->m_inited_scancache = true;
      internal_class->scan_cache = &internal_class->m_scancache;
      internal_class->scan_cache->mvcc_snapshot = logtb_get_mvcc_snapshot (thread_p);

    }
  COPY_OID (&internal_class->prev_class_oid, current_oid);

  return NO_ERROR;
}

static int
qexec_execute_merge (THREAD_ENTRY * thread_p, XASL_NODE * xasl, XASL_STATE * xasl_state)
{
  int error = NO_ERROR;
  int savepoint_used = 0;
  LOG_LSA lsa;

  /* start a topop */
  error = xtran_server_start_topop (thread_p, &lsa);
  if (error != NO_ERROR)
    {
      GOTO_EXIT_ON_ERROR;
    }
  savepoint_used = 1;

  /* execute insert aptr */
  if (xasl->proc.merge.insert_xasl)
    {
      XASL_NODE *xptr = xasl->proc.merge.insert_xasl;
      if (xptr && xptr->aptr_list)
	{
	  error = qexec_execute_mainblock (thread_p, xptr->aptr_list, xasl_state, NULL);
	}
    }
  /* execute update */
  if (error == NO_ERROR && xasl->proc.merge.update_xasl)
    {
      error = qexec_execute_update (thread_p, xasl->proc.merge.update_xasl, xasl->proc.merge.has_delete, xasl_state);
    }
  /* execute insert */
  if (error == NO_ERROR && xasl->proc.merge.insert_xasl)
    {
      error = qexec_execute_insert (thread_p, xasl->proc.merge.insert_xasl, xasl_state, true);
    }

  /* check error */
  if (error != NO_ERROR)
    {
      GOTO_EXIT_ON_ERROR;
    }

  /* setup list file for result count */
  error = qexec_setup_list_id (thread_p, xasl);
  if (error != NO_ERROR)
    {
      GOTO_EXIT_ON_ERROR;
    }

  xasl->list_id->tuple_cnt = 0;

  /* set result count */
  if (xasl->proc.merge.update_xasl)
    {
      xasl->list_id->tuple_cnt += xasl->proc.merge.update_xasl->list_id->tuple_cnt;
      /* monitor */
      perfmon_inc_stat (thread_p, PSTAT_QM_NUM_UPDATES);
    }

  if (xasl->proc.merge.insert_xasl)
    {
      xasl->list_id->tuple_cnt += xasl->proc.merge.insert_xasl->list_id->tuple_cnt;
      /* monitor */
      perfmon_inc_stat (thread_p, PSTAT_QM_NUM_INSERTS);
    }

  /* end topop */
  if (xtran_server_end_topop (thread_p, LOG_RESULT_TOPOP_ATTACH_TO_OUTER, &lsa) != TRAN_ACTIVE)
    {
      GOTO_EXIT_ON_ERROR;
    }

  return NO_ERROR;

exit_on_error:

  if (savepoint_used)
    {
      xtran_server_end_topop (thread_p, LOG_RESULT_TOPOP_ABORT, &lsa);
    }

  return error;
}

static int
qexec_init_agg_hierarchy_helpers (THREAD_ENTRY * thread_p, ACCESS_SPEC_TYPE * spec, AGGREGATE_TYPE * aggregate_list,
				  HIERARCHY_AGGREGATE_HELPER ** helpersp, int *helpers_countp)
{
  int agg_count = 0, part_count = 0, i;
  AGGREGATE_TYPE *agg = NULL;
  HIERARCHY_AGGREGATE_HELPER *helpers = NULL;
  PRUNING_CONTEXT context;
  int error = NO_ERROR;
  PARTITION_SPEC_TYPE *part = NULL;

  /* count aggregates */
  agg = aggregate_list;
  agg_count = 0;
  while (agg)
    {
      if (!agg->flag.agg_optimized)
	{
	  agg = agg->next;
	  continue;
	}
      agg = agg->next;
      agg_count++;
    }

  if (agg_count == 0)
    {
      *helpersp = NULL;
      *helpers_countp = 0;
      return NO_ERROR;
    }

  partition_init_pruning_context (&context);

  helpers = (HIERARCHY_AGGREGATE_HELPER *) db_private_alloc (thread_p, agg_count * sizeof (HIERARCHY_AGGREGATE_HELPER));
  if (helpers == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1,
	      agg_count * sizeof (HIERARCHY_AGGREGATE_HELPER));
      error = ER_OUT_OF_VIRTUAL_MEMORY;
      goto error_return;
    }

  for (i = 0; i < agg_count; i++)
    {
      helpers[i].btids = NULL;
      helpers[i].hfids = NULL;
    }

  /* count pruned partitions */
  for (part_count = 0, part = spec->parts; part != NULL; part_count++, part = part->next);
  if (part_count == 0)
    {
      error = NO_ERROR;
      goto error_return;
    }

  error = partition_load_pruning_context (thread_p, &ACCESS_SPEC_CLS_OID (spec), spec->pruning_type, &context);
  if (error != NO_ERROR)
    {
      goto error_return;
    }

  agg = aggregate_list;
  i = 0;
  while (agg != NULL)
    {
      if (!agg->flag.agg_optimized)
	{
	  agg = agg->next;
	  continue;
	}
      error = partition_load_aggregate_helper (&context, spec, part_count, &agg->btid, &helpers[i]);
      if (error != NO_ERROR)
	{
	  goto error_return;
	}
      agg = agg->next;
      i++;
    }

  partition_clear_pruning_context (&context);
  *helpersp = helpers;
  *helpers_countp = agg_count;
  return NO_ERROR;

error_return:
  if (helpers != NULL)
    {
      for (i = 0; i < agg_count; i++)
	{
	  if (helpers[i].btids != NULL)
	    {
	      db_private_free (thread_p, helpers[i].btids);
	    }
	  if (helpers[i].hfids != NULL)
	    {
	      db_private_free (thread_p, helpers[i].hfids);
	    }
	}
      db_private_free (thread_p, helpers);
    }

  partition_clear_pruning_context (&context);

  *helpersp = NULL;
  *helpers_countp = 0;
  return error;
}

static int
qexec_evaluate_partition_aggregates (THREAD_ENTRY * thread_p, ACCESS_SPEC_TYPE * spec, AGGREGATE_TYPE * agg_list,
				     bool * is_scan_needed)
{
  int error = NO_ERROR;
  int i = 0, helpers_count = 0;
  HIERARCHY_AGGREGATE_HELPER *helpers = NULL;
  AGGREGATE_TYPE *agg_ptr = NULL;
  BTID root_btid;
  error = qexec_init_agg_hierarchy_helpers (thread_p, spec, agg_list, &helpers, &helpers_count);
  if (error != NO_ERROR)
    {
      *is_scan_needed = true;
      goto cleanup;
    }
  i = 0;
  for (agg_ptr = agg_list; agg_ptr; agg_ptr = agg_ptr->next)
    {
      if (!agg_ptr->flag.agg_optimized)
	{
	  continue;
	}

      if (agg_ptr->function == PT_COUNT_STAR && *is_scan_needed)
	{
	  agg_ptr->flag.agg_optimized = false;
	  i++;
	  continue;
	}
      BTID_COPY (&root_btid, &agg_ptr->btid);
      error = qdata_evaluate_aggregate_hierarchy (thread_p, agg_ptr, &ACCESS_SPEC_HFID (spec), &root_btid, &helpers[i]);
      if (error != NO_ERROR)
	{
	  agg_ptr->flag.agg_optimized = false;
	  *is_scan_needed = true;
	  goto cleanup;
	}
      i++;
    }

cleanup:
  if (helpers != NULL)
    {
      for (i = 0; i < helpers_count; i++)
	{
	  if (helpers[i].btids != NULL)
	    {
	      db_private_free (thread_p, helpers[i].btids);
	    }
	  if (helpers[i].hfids != NULL)
	    {
	      db_private_free (thread_p, helpers[i].hfids);
	    }
	}
      db_private_free (thread_p, helpers);
    }
  return error;
}

static int
qexec_evaluate_aggregates_optimize (THREAD_ENTRY * thread_p, AGGREGATE_TYPE * agg_list, ACCESS_SPEC_TYPE * spec,
				    bool * is_scan_needed)
{
  AGGREGATE_TYPE *agg_ptr;
  int error = NO_ERROR;
  OID super_oid;

  OID_SET_NULL (&super_oid);

  for (agg_ptr = agg_list; agg_ptr; agg_ptr = agg_ptr->next)
    {
      if (!agg_ptr->flag.agg_optimized)
	{
	  /* scan is needed for this aggregate */
	  *is_scan_needed = true;
	  continue;
	}

      /* If we deal with a count optimization and the snapshot wasn't already taken then prepare current class for
       * optimization and force a snapshot */
      if (!*is_scan_needed && agg_ptr->function == PT_COUNT_STAR)
	{
	  LOG_TDES *tdes = LOG_FIND_TDES (LOG_FIND_THREAD_TRAN_INDEX (thread_p));

	  if (tdes == NULL || tdes->isolation >= TRAN_REPEATABLE_READ)
	    {
	      /* COUNT(*) optimization uses global statistics that bypass MVCC visibility;
	       * fall back to full scan under REPEATABLE_READ or SERIALIZABLE to prevent phantom reads. */
	      agg_ptr->flag.agg_optimized = false;
	      *is_scan_needed = true;
	      continue;
	    }

#if defined (SERVER_MODE)
	  /* Parallel UNION branches executing this query share tdes (and therefore
	   * log_upd_stats.classes_cos_hash / unique_stats_hash) across worker threads that adopt the
	   * main thread's tran_index. All accesses to those per-tran hash tables below must be
	   * serialized with the same lock logtb_get_mvcc_snapshot() uses, or concurrent mht_get()/
	   * mht_put() calls on the shared hash can corrupt it (observed as an infinite spin) or let one
	   * worker see COS_LOADED before another worker's statistics write becomes visible (observed as
	   * count(*) wrongly returning -1). */
	  THREAD_ENTRY *main_thread_p = NULL;
	  if (thread_p->m_px_orig_thread_entry != NULL)
	    {
	      main_thread_p = thread_get_main_thread (thread_p);
	    }
#endif /* SERVER_MODE */
	  QEXEC_COUNT_OPT_PX_LOCK (main_thread_p);

	  LOG_TRAN_CLASS_COS *class_cos = logtb_tran_find_class_cos (thread_p, &ACCESS_SPEC_CLS_OID (spec),
								     true);
	  if (class_cos == NULL)
	    {
	      agg_ptr->flag.agg_optimized = false;
	      *is_scan_needed = true;
	      QEXEC_COUNT_OPT_PX_UNLOCK (main_thread_p);
	      continue;
	    }

	  /* to check for query like 'select count(*), count(*) ...' */
	  if (class_cos->count_state != COS_LOADED)
	    {

	      class_cos->count_state = COS_TO_LOAD;
	      if (logtb_tran_find_btid_stats (thread_p, &agg_ptr->btid, true) == NULL)
		{
		  agg_ptr->flag.agg_optimized = false;
		  *is_scan_needed = true;
		  QEXEC_COUNT_OPT_PX_UNLOCK (main_thread_p);
		  continue;
		}

	      if (!tdes->mvccinfo.snapshot.valid)
		{
		  /* logtb_get_mvcc_snapshot() takes main_thread_p->m_px_lock_mutex itself; release it
		   * here first to avoid a self-deadlock, then reacquire before touching class_cos again. */
		  QEXEC_COUNT_OPT_PX_UNLOCK (main_thread_p);
		  if (logtb_get_mvcc_snapshot (thread_p) == NULL)
		    {
		      error = er_errid ();
		      return (error == NO_ERROR ? ER_FAILED : error);
		    }
		  QEXEC_COUNT_OPT_PX_LOCK (main_thread_p);
		}

	      /* 
	       * build_mvcc_info() loads stats only for classes already marked COS_TO_LOAD at snapshot time.
	       * Under parallel UNION execution, the snapshot may have been built by another thread before this
	       * class was marked COS_TO_LOAD, so its stats were never loaded.  Always retry here if still needed.
	       */
	      if (class_cos->count_state != COS_LOADED)
		{
		  if (logtb_load_global_statistics_to_tran (thread_p) != NO_ERROR)
		    {
		      error = er_errid ();
		      QEXEC_COUNT_OPT_PX_UNLOCK (main_thread_p);
		      return (error == NO_ERROR ? ER_FAILED : error);
		    }
		}

	      if (class_cos->count_state != COS_LOADED)
		{
		  agg_ptr->flag.agg_optimized = false;
		  *is_scan_needed = true;
		  QEXEC_COUNT_OPT_PX_UNLOCK (main_thread_p);
		  continue;
		}
	    }

	  QEXEC_COUNT_OPT_PX_UNLOCK (main_thread_p);
	}

      if (thread_is_on_trace (thread_p))
	{
	  char *agg_index_name;
	  SCAN_AGL *agl;

	  error = heap_get_indexinfo_of_btid (thread_p, &ACCESS_SPEC_CLS_OID (spec), &agg_ptr->btid,
					      NULL, NULL, NULL, NULL, &agg_index_name, NULL);
	  if (error != NO_ERROR)
	    {
	      return error;
	    }

	  for (agl = spec->s_id.scan_stats.agl; agl; agl = agl->next)
	    {
	      if (strcmp (agl->agg_index_name, agg_index_name) == 0)
		{
		  /* same index name found */
		  break;
		}
	    }

	  if (agl == NULL)
	    {
	      agl = (SCAN_AGL *) malloc (sizeof (SCAN_AGL));
	      if (agl == NULL)
		{
		  return ER_FAILED;
		}

	      agl->agg_index_name = agg_index_name;
	      agl->next = spec->s_id.scan_stats.agl;
	      spec->s_id.scan_stats.agl = agl;
	    }
	  else
	    {
	      /* same index name found */
	      free (agg_index_name);
	    }
	}
    }

  if (spec->pruning_type == DB_PARTITIONED_CLASS)
    {
      /* evaluate aggregate across partition hierarchy */
      return qexec_evaluate_partition_aggregates (thread_p, spec, agg_list, is_scan_needed);
    }
  else if (spec->pruning_type == DB_PARTITION_CLASS)
    {
      error = partition_find_root_class_oid (thread_p, &ACCESS_SPEC_CLS_OID (spec), &super_oid);
      if (error != NO_ERROR)
	{
	  *is_scan_needed = true;
	  return error;
	}
    }

  for (agg_ptr = agg_list; agg_ptr; agg_ptr = agg_ptr->next)
    {
      if (agg_ptr->flag.agg_optimized)
	{
	  if (agg_ptr->function == PT_COUNT_STAR && *is_scan_needed)
	    {
	      /* If scan is needed, do not optimize PT_COUNT_STAR. */
	      agg_ptr->flag.agg_optimized = false;
	      continue;
	    }
	  if (qdata_evaluate_aggregate_optimize (thread_p, agg_ptr, &ACCESS_SPEC_HFID (spec), &super_oid) != NO_ERROR)
	    {
	      agg_ptr->flag.agg_optimized = false;
	      *is_scan_needed = true;
	    }
	}
    }

  spec->s_id.scan_stats.noscan = (*is_scan_needed) ? false : true;

  return error;
}

int
qexec_setup_topn_proc (THREAD_ENTRY * thread_p, XASL_NODE * xasl, VAL_DESCR * vd)
{
  BINARY_HEAP *heap = NULL;
  DB_VALUE ubound_val;
  REGU_VARIABLE_LIST var_list = NULL;
  TOPN_TUPLES *top_n = NULL;
  int error = NO_ERROR, ubound = 0, count = 0;
  UINT64 estimated_size = 0, max_size = 0;
  static int sr_nbuffers = prm_get_integer_value (PRM_ID_SR_NBUFFERS);

  if (xasl->type != BUILDLIST_PROC)
    {
      return NO_ERROR;
    }

  if (xasl->orderby_list == NULL)
    {
      /* Not ordered */
      return NO_ERROR;
    }
  if (xasl->ordbynum_pred == NULL)
    {
      /* No limit specified */
      return NO_ERROR;
    }

  if (xasl->option == Q_DISTINCT)
    {
      /* We cannot handle distinct ordering */
      return NO_ERROR;
    }

  if (XASL_IS_FLAGED (xasl, XASL_HAS_CONNECT_BY) || XASL_IS_FLAGED (xasl, XASL_SKIP_ORDERBY_LIST)
      || XASL_IS_FLAGED (xasl, XASL_USES_MRO))
    {
      return NO_ERROR;
    }

  if (xasl->proc.buildlist.groupby_list != NULL || xasl->proc.buildlist.a_eval_list != NULL)
    {
      /* Cannot handle group by and analytics with order by */
      return NO_ERROR;
    }

  db_make_null (&ubound_val);
  error = qexec_get_orderbynum_upper_bound (thread_p, xasl->ordbynum_pred, vd, &ubound_val);
  if (error != NO_ERROR)
    {
      return error;
    }
  if (DB_IS_NULL (&ubound_val))
    {
      return NO_ERROR;
    }
  if (DB_VALUE_TYPE (&ubound_val) != DB_TYPE_INTEGER)
    {
      TP_DOMAIN_STATUS status;
      status = tp_value_cast (&ubound_val, &ubound_val, &tp_Integer_domain, 1);
      if (status != DOMAIN_COMPATIBLE)
	{
	  pr_clear_value (&ubound_val);
	  return NO_ERROR;
	}
    }

  ubound = db_get_int (&ubound_val);
  pr_clear_value (&ubound_val);

  if (ubound == 0)
    {
      return NO_ERROR;
    }

  estimated_size = 0;
  count = 0;
  var_list = xasl->outptr_list->valptrp;
  while (var_list)
    {
      if (var_list->value.domain == NULL)
	{
	  /* probably an error but just abandon top-n */
	  return NO_ERROR;
	}
      if (TP_IS_SET_TYPE (TP_DOMAIN_TYPE (var_list->value.domain)))
	{
	  /* do not apply this to collections */
	  return NO_ERROR;
	}
      if (REGU_VARIABLE_IS_FLAGED (&var_list->value, REGU_VARIABLE_HIDDEN_COLUMN))
	{
	  /* skip hidden values */
	  var_list = var_list->next;
	  continue;
	}

      if (var_list->value.domain->precision != TP_FLOATING_PRECISION_VALUE)
	{
	  /* Ignore floating point precision domains for now. We will decide whether or not to continue with top-N
	   * whenever we add/replace a tuple. */
	  estimated_size += tp_domain_memory_size (var_list->value.domain);
	}
      count++;
      var_list = var_list->next;
    }

  if (estimated_size >= (UINT64) QFILE_MAX_TUPLE_SIZE_IN_PAGE)
    {
      /* Do not keep these values in memory */
      return NO_ERROR;
    }

  /* At any time, we will handle at most ubound tuples */
  estimated_size *= ubound;
  max_size = (UINT64) sr_nbuffers *IO_PAGESIZE;
  if (estimated_size > max_size)
    {
      /* Do not use more than the sort buffer size. Using the entire sort buffer is possible because this is the only
       * sort operation which is being executed for this transaction at this time. */
      return NO_ERROR;
    }


  top_n = (TOPN_TUPLES *) db_private_alloc (thread_p, sizeof (TOPN_TUPLES));
  if (top_n == NULL)
    {
      error = ER_FAILED;
      goto error_return;
    }

  top_n->max_size = max_size;
  top_n->total_size = 0;

  top_n->tuples = (TOPN_TUPLE *) db_private_alloc (thread_p, ubound * sizeof (TOPN_TUPLE));
  if (top_n->tuples == NULL)
    {
      error = ER_FAILED;
      goto error_return;
    }
  memset (top_n->tuples, 0, ubound * sizeof (TOPN_TUPLE));

  heap = bh_create (thread_p, ubound, sizeof (TOPN_TUPLE *), qexec_topn_compare, top_n);
  if (heap == NULL)
    {
      error = ER_FAILED;
      goto error_return;
    }

  top_n->heap = heap;
  top_n->sort_items = xasl->orderby_list;
  top_n->values_count = count;

  xasl->topn_items = top_n;

  return NO_ERROR;

error_return:
  if (heap != NULL)
    {
      bh_destroy (thread_p, heap);
    }
  if (top_n != NULL)
    {
      if (top_n->tuples != NULL)
	{
	  db_private_free (thread_p, top_n->tuples);
	}
      db_private_free (thread_p, top_n);
    }

  return error;
}

static BH_CMP_RESULT
qexec_topn_compare (const void *left, const void *right, BH_CMP_ARG arg)
{
  int pos;
  SORT_LIST *key = NULL;
  TOPN_TUPLES *proc = (TOPN_TUPLES *) arg;
  TOPN_TUPLE *left_tuple = *((TOPN_TUPLE **) left);
  TOPN_TUPLE *right_tuple = *((TOPN_TUPLE **) right);
  BH_CMP_RESULT cmp;

  for (key = proc->sort_items; key != NULL; key = key->next)
    {
      pos = key->pos_descr.pos_no;
      cmp = qexec_topn_cmpval (&left_tuple->values[pos], &right_tuple->values[pos], key);
      if (cmp == BH_EQ)
	{
	  continue;
	}
      return cmp;
    }

  return BH_EQ;
}

static BH_CMP_RESULT
qexec_topn_cmpval (DB_VALUE * left, DB_VALUE * right, SORT_LIST * sort_spec)
{
  int cmp;
  if (DB_IS_NULL (left))
    {
      if (DB_IS_NULL (right))
	{
	  return BH_EQ;
	}
      cmp = DB_LT;
      if ((sort_spec->s_order == S_ASC && sort_spec->s_nulls == S_NULLS_LAST)
	  || (sort_spec->s_order == S_DESC && sort_spec->s_nulls == S_NULLS_FIRST))
	{
	  cmp = -cmp;
	}
    }
  else if (DB_IS_NULL (right))
    {
      cmp = DB_GT;
      if ((sort_spec->s_order == S_ASC && sort_spec->s_nulls == S_NULLS_LAST)
	  || (sort_spec->s_order == S_DESC && sort_spec->s_nulls == S_NULLS_FIRST))
	{
	  cmp = -cmp;
	}
    }
  else
    {
      if (TP_DOMAIN_TYPE (sort_spec->pos_descr.dom) == DB_TYPE_VARIABLE
	  || TP_DOMAIN_COLLATION_FLAG (sort_spec->pos_descr.dom) != TP_DOMAIN_COLL_NORMAL)
	{
	  /* In cases like order by val + ?, the domain of the expression is not known at compile time */
	  cmp = tp_value_compare (left, right, 1, 1);
	}
      else
	{
	  cmp =
	    sort_spec->pos_descr.dom->type->cmpval (left, right, 1, 1, NULL, sort_spec->pos_descr.dom->collation_id);
	}
    }
  if (sort_spec->s_order == S_DESC)
    {
      cmp = -cmp;
    }

  switch (cmp)
    {
    case DB_GT:
      return BH_GT;

    case DB_LT:
      return BH_LT;

    case DB_EQ:
      return BH_EQ;

    default:
      break;
    }

  return BH_CMP_ERROR;
}

TOPN_STATUS
qexec_add_tuple_to_topn (THREAD_ENTRY * thread_p, TOPN_TUPLES * topn_items, QFILE_TUPLE_DESCRIPTOR * tpldescr)
{
  int error = NO_ERROR;
  BH_CMP_RESULT res = BH_EQ;
  SORT_LIST *key = NULL;
  int pos = 0;
  TOPN_TUPLE *heap_max = NULL;

  assert (topn_items != NULL && tpldescr != NULL);

  if (!bh_is_full (topn_items->heap))
    {
      /* Add current tuple to heap. We haven't reached top-N yet */
      TOPN_TUPLE *tpl = NULL;
      int idx = topn_items->heap->element_count;

      if (topn_items->total_size + tpldescr->tpl_size > topn_items->max_size)
	{
	  /* abandon top-N */
	  return TOPN_OVERFLOW;
	}

      tpl = &topn_items->tuples[idx];

      /* tpl must be unused */
      assert_release (tpl->values == NULL);

      error = qdata_tuple_to_values_array (thread_p, tpldescr, &tpl->values);
      if (error != NO_ERROR)
	{
	  return TOPN_FAILURE;
	}

      tpl->values_size = tpldescr->tpl_size;
      topn_items->total_size += tpldescr->tpl_size;

      (void) bh_insert (topn_items->heap, &tpl);

      return TOPN_SUCCESS;
    }

  /* We only add a tuple to the heap if it is "smaller" than the current root. Rather than allocating memory for a new
   * tuple and testing it, we test the heap root directly on the outptr list and replace it if we have to. */
  if (!bh_peek_max (topn_items->heap, &heap_max))
    {
      assert (false);
    }
  assert (heap_max != NULL);

  for (key = topn_items->sort_items; key != NULL; key = key->next)
    {
      pos = key->pos_descr.pos_no;
      res = qexec_topn_cmpval (&heap_max->values[pos], tpldescr->f_valp[pos], key);
      if (res == BH_EQ)
	{
	  continue;
	}
      if (res == BH_LT)
	{
	  /* skip this tuple */
	  return TOPN_SUCCESS;
	}
      break;
    }
  if (res == BH_EQ)
    {
      return TOPN_SUCCESS;
    }

  /* Test if we can accommodate the new tuple */
  if (topn_items->total_size - heap_max->values_size + tpldescr->tpl_size > topn_items->max_size)
    {
      /* Abandon top-N */
      return TOPN_OVERFLOW;
    }

  /* Replace heap root. We don't need the heap_max object anymore so we will use it for the new tuple. */
  topn_items->total_size -= heap_max->values_size;
  qexec_clear_topn_tuple (thread_p, heap_max, tpldescr->f_cnt);

  error = qdata_tuple_to_values_array (thread_p, tpldescr, &heap_max->values);
  if (error != NO_ERROR)
    {
      return TOPN_FAILURE;
    }

  heap_max->values_size = tpldescr->tpl_size;
  topn_items->total_size += tpldescr->tpl_size;

  (void) bh_down_heap (topn_items->heap, 0);

  return TOPN_SUCCESS;
}

int
qexec_topn_tuples_to_list_id (THREAD_ENTRY * thread_p, XASL_NODE * xasl, XASL_STATE * xasl_state, bool is_final,
			      QFILE_LIST_ID * merged_results)
{
  QFILE_LIST_ID *list_id = NULL;
  QFILE_TUPLE_DESCRIPTOR *tpl_descr = NULL;
  TOPN_TUPLES *topn = NULL;
  BINARY_HEAP *heap = NULL;
  REGU_VARIABLE_LIST varp = NULL;
  TOPN_TUPLE *tuple = NULL;
  int row = 0, i, value_size, values_count, error = NO_ERROR;
  ORDBYNUM_INFO ordby_info;
  DB_LOGICAL res = V_FALSE;
  bool use_xasl_list = (merged_results == NULL);

  /* setup ordby_info so that we can evaluate the orderby_num() predicate */
  ordby_info.xasl_state = xasl_state;
  ordby_info.ordbynum_pred = xasl->ordbynum_pred;
  ordby_info.ordbynum_flag = xasl->ordbynum_flag;
  ordby_info.ordbynum_pos_cnt = 0;
  ordby_info.ordbynum_val = xasl->ordbynum_val;
  db_make_bigint (ordby_info.ordbynum_val, 0);

  list_id = use_xasl_list ? xasl->list_id : merged_results;
  topn = xasl->topn_items;
  heap = topn->heap;
  tpl_descr = &list_id->tpl_descr;
  values_count = topn->values_count;
  if (use_xasl_list)
    {
      /* orderby_topnsort trace stat is recorded only when finalizing into xasl->list_id, not a redirected list. */
      xasl->orderby_stats.orderby_topnsort = true;
    }

  /* convert binary heap to sorted array */
  bh_to_sorted_array (heap);

  /* dump all items in heap to listfile */
  if (tpl_descr->f_valp == NULL && list_id->type_list.type_cnt > 0)
    {
      size_t size = values_count * DB_SIZEOF (DB_VALUE *);

      tpl_descr->f_valp = (DB_VALUE **) malloc (size);
      if (tpl_descr->f_valp == NULL)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, size);
	  error = ER_FAILED;
	  goto cleanup;
	}
    }

  varp = xasl->outptr_list->valptrp;
  for (row = 0; row < heap->element_count; row++)
    {
      tuple = QEXEC_GET_BH_TOPN_TUPLE (heap, row);

      /* evaluate orderby_num predicate */
      res = qexec_eval_ordbynum_pred (thread_p, &ordby_info);
      if (res != V_TRUE)
	{
	  if (res == V_ERROR)
	    {
	      error = ER_FAILED;
	      goto cleanup;
	    }

	  if (is_final)
	    {
	      /* skip this tuple */
	      qexec_clear_topn_tuple (thread_p, tuple, values_count);
	      QEXEC_GET_BH_TOPN_TUPLE (heap, row) = NULL;
	      continue;
	    }
	}

      tuple = QEXEC_GET_BH_TOPN_TUPLE (heap, row);
      tpl_descr->tpl_size = QFILE_TUPLE_LENGTH_SIZE;

      tpl_descr->f_cnt = 0;

      for (varp = xasl->outptr_list->valptrp; varp != NULL; varp = varp->next)
	{
	  if (REGU_VARIABLE_IS_FLAGED (&varp->value, REGU_VARIABLE_HIDDEN_COLUMN))
	    {
	      continue;
	    }

	  if (varp->value.type == TYPE_ORDERBY_NUM)
	    {
	      pr_clone_value (ordby_info.ordbynum_val, &tuple->values[tpl_descr->f_cnt]);
	    }

	  tpl_descr->f_valp[tpl_descr->f_cnt] = &tuple->values[tpl_descr->f_cnt];

	  value_size = qdata_get_tuple_value_size_from_dbval (&tuple->values[tpl_descr->f_cnt]);
	  if (value_size == ER_FAILED)
	    {
	      error = value_size;
	      goto cleanup;
	    }

	  tpl_descr->tpl_size += value_size;
	  tpl_descr->f_cnt++;
	}

      error = qfile_generate_tuple_into_list (thread_p, list_id, T_NORMAL);
      if (error != NO_ERROR)
	{
	  goto cleanup;
	}
      /* clear tuple values */
      qexec_clear_topn_tuple (thread_p, tuple, values_count);
      QEXEC_GET_BH_TOPN_TUPLE (heap, row) = NULL;
    }

cleanup:
  if (tuple != NULL)
    {
      qexec_clear_topn_tuple (thread_p, tuple, values_count);
    }

  for (i = row; i < heap->element_count; i++)
    {
      if (QEXEC_GET_BH_TOPN_TUPLE (heap, i) != NULL)
	{
	  tuple = QEXEC_GET_BH_TOPN_TUPLE (heap, i);
	  qexec_clear_topn_tuple (thread_p, tuple, values_count);
	  QEXEC_GET_BH_TOPN_TUPLE (heap, i) = NULL;
	}
    }

  if (heap != NULL)
    {
      bh_destroy (thread_p, heap);
    }

  if (xasl->topn_items != NULL)
    {
      if (xasl->topn_items->tuples != NULL)
	{
	  db_private_free (thread_p, xasl->topn_items->tuples);
	}
      db_private_free (thread_p, xasl->topn_items);
      xasl->topn_items = NULL;
    }

  if (is_final)
    {
      qfile_close_list (thread_p, list_id);
    }
  else
    {
      /* reset ORDERBY_NUM value */
      assert (DB_VALUE_TYPE (xasl->ordbynum_val) == DB_TYPE_BIGINT);
      db_make_bigint (xasl->ordbynum_val, 0);
    }
  return error;
}

void
qexec_clear_topn_items (THREAD_ENTRY * thread_p, XASL_NODE * xasl)
{
  int i;
  BINARY_HEAP *heap;

  if (xasl->topn_items == NULL)
    {
      return;
    }

  /* inline twins at qexec_clear_xasl share this deref-before-guard; out of scope here (follow-up ticket) */
  heap = xasl->topn_items->heap;
  if (heap != NULL)
    {
      for (i = 0; i < heap->element_count; i++)
	{
	  if (QEXEC_GET_BH_TOPN_TUPLE (heap, i) != NULL)	/* cheap insurance; qexec_clear_topn_tuple self-guards too */
	    {
	      qexec_clear_topn_tuple (thread_p, QEXEC_GET_BH_TOPN_TUPLE (heap, i), xasl->topn_items->values_count);
	    }
	}
      bh_destroy (thread_p, heap);
    }

  if (xasl->topn_items->tuples != NULL)
    {
      db_private_free_and_init (thread_p, xasl->topn_items->tuples);
    }

  db_private_free_and_init (thread_p, xasl->topn_items);
}

static void
qexec_clear_topn_tuple (THREAD_ENTRY * thread_p, TOPN_TUPLE * tuple, int count)
{
  int i;
  if (tuple == NULL)
    {
      return;
    }

  if (tuple->values != NULL)
    {
      for (i = 0; i < count; i++)
	{
	  pr_clear_value (&tuple->values[i]);
	}
      db_private_free_and_init (thread_p, tuple->values);
    }
  tuple->values_size = 0;
}

static int
qexec_get_orderbynum_upper_bound (THREAD_ENTRY * thread_p, PRED_EXPR * pred, VAL_DESCR * vd, DB_VALUE * ubound)
{
  int error = NO_ERROR;
  REGU_VARIABLE *lhs, *rhs;
  REL_OP op;
  DB_VALUE *val;
  int cmp;
  DB_VALUE left_bound, right_bound;

  assert_release (pred != NULL);
  assert_release (ubound != NULL);

  db_make_null (ubound);
  db_make_null (&left_bound);
  db_make_null (&right_bound);

  if (pred->type == T_PRED && pred->pe.m_pred.bool_op == B_AND)
    {
      error = qexec_get_orderbynum_upper_bound (thread_p, pred->pe.m_pred.lhs, vd, &left_bound);
      if (error != NO_ERROR)
	{
	  goto error_return;
	}

      error = qexec_get_orderbynum_upper_bound (thread_p, pred->pe.m_pred.rhs, vd, &right_bound);
      if (error != NO_ERROR)
	{
	  goto error_return;
	}

      if (DB_IS_NULL (&left_bound) && DB_IS_NULL (&right_bound))
	{
	  /* no valid bounds */
	  goto cleanup;
	}

      cmp = tp_value_compare (&left_bound, &right_bound, 1, 1);
      if (cmp == DB_GT)
	{
	  error = pr_clone_value (&left_bound, ubound);
	}
      else
	{
	  error = pr_clone_value (&right_bound, ubound);
	}

      if (error != NO_ERROR)
	{
	  goto error_return;
	}

      goto cleanup;
    }

  if (pred->type == T_EVAL_TERM)
    {
      /* This should be TYPE_CONSTANT comp TYPE_VALUE. If not, we bail out */
      lhs = pred->pe.m_eval_term.et.et_comp.lhs;
      rhs = pred->pe.m_eval_term.et.et_comp.rhs;
      op = pred->pe.m_eval_term.et.et_comp.rel_op;
      if (lhs->type != TYPE_CONSTANT)
	{
	  if (lhs->type != TYPE_POS_VALUE && lhs->type != TYPE_DBVAL && lhs->type != TYPE_INARITH)
	    {
	      goto cleanup;
	    }

	  if (rhs->type != TYPE_CONSTANT)
	    {
	      goto cleanup;
	    }

	  /* reverse comparison */
	  rhs = lhs;
	  lhs = pred->pe.m_eval_term.et.et_comp.rhs;
	  switch (op)
	    {
	    case R_GT:
	      op = R_LT;
	      break;
	    case R_GE:
	      op = R_LE;
	      break;
	    case R_LT:
	      op = R_GT;
	      break;
	    case R_LE:
	      op = R_GE;
	      break;
	    default:
	      goto cleanup;
	    }
	}
      if (rhs->type != TYPE_POS_VALUE && rhs->type != TYPE_DBVAL && rhs->type != TYPE_INARITH)
	{
	  goto cleanup;
	}

      if (op != R_LT && op != R_LE)
	{
	  /* we're only interested in orderby_num less than value */
	  goto cleanup;
	}

      error = fetch_peek_dbval (thread_p, rhs, vd, NULL, NULL, NULL, &val);
      if (error != NO_ERROR)
	{
	  goto error_return;
	}

      if (op == R_LT)
	{
	  /* add 1 so we can use R_LE */
	  DB_VALUE one_val;
	  db_make_int (&one_val, 1);
	  error = qdata_subtract_dbval (val, &one_val, ubound, rhs->domain);
	}
      else
	{
	  error = pr_clone_value (val, ubound);
	}

      if (error != NO_ERROR)
	{
	  goto error_return;
	}
      goto cleanup;
    }

  return error;

error_return:
  db_make_null (ubound);

cleanup:
  pr_clear_value (&left_bound);
  pr_clear_value (&right_bound);

  return error;
}

static int
qexec_clear_agg_orderby_const_list (THREAD_ENTRY * thread_p, XASL_NODE * xasl, bool is_final)
{
  AGGREGATE_TYPE *agg_list, *agg_p;
  int pg_cnt = 0;
  assert (xasl != NULL);

  agg_list = xasl->proc.buildvalue.agg_list;
  for (agg_p = agg_list; agg_p; agg_p = agg_p->next)
    {
      if ((agg_p->function == PT_CUME_DIST || agg_p->function == PT_PERCENT_RANK)
	  && agg_p->info.dist_percent.const_array != NULL)
	{
	  db_private_free_and_init (thread_p, agg_p->info.dist_percent.const_array);
	  agg_p->info.dist_percent.list_len = 0;
	}

      if (agg_p->function == PT_PERCENTILE_CONT || agg_p->function == PT_PERCENTILE_DISC)
	{
	  if (agg_p->info.percentile.percentile_reguvar != NULL)
	    {
	      pg_cnt +=
		qexec_clear_regu_var (thread_p, xasl, agg_p->info.percentile.percentile_reguvar, is_final, false);
	    }
	}
    }

  return pg_cnt;
}

static int
qexec_clear_regu_variable_list (THREAD_ENTRY * thread_p, XASL_NODE * xasl_p, REGU_VARIABLE_LIST list, bool is_final,
				bool for_parallel_aptr)
{
  REGU_VARIABLE_LIST list_node;
  int pg_cnt = 0;

  assert (list != NULL);

  for (list_node = list; list_node; list_node = list_node->next)
    {
      pg_cnt += qexec_clear_regu_var (thread_p, xasl_p, &list_node->value, is_final, for_parallel_aptr);
    }

  return pg_cnt;
}

static void
qexec_set_xasl_trace_to_session (THREAD_ENTRY * thread_p, XASL_NODE * xasl)
{
  size_t sizeloc;
  char *trace_str = NULL;
  FILE *fp;
  trace_json_t *trace;

  if (thread_p->trace_format == QUERY_TRACE_TEXT)
    {
      fp = port_open_memstream (&trace_str, &sizeloc);
      if (fp)
	{
	  qdump_print_stats_text (fp, xasl, 0);
	  port_close_memstream (fp, &trace_str, &sizeloc);
	}
    }
  else if (thread_p->trace_format == QUERY_TRACE_JSON)
    {
      trace = trace_json_object ();
      qdump_print_stats_json (xasl, trace);
      trace_str = trace_json_dumps (trace);

      trace_json_decref (trace);
    }

  if (trace_str != NULL)
    {
      session_set_trace_stats (thread_p, trace_str, thread_p->trace_format);
    }
}

static void
qexec_clear_pred_xasl (THREAD_ENTRY * thread_p, PRED_EXPR * pred)
{
  PRED_EXPR *pr;

  if (pred == NULL)
    {
      return;
    }

  switch (pred->type)
    {
    case T_PRED:
      qexec_clear_pred_xasl (thread_p, pred->pe.m_pred.lhs);
      for (pr = pred->pe.m_pred.rhs; pr && pr->type == T_PRED; pr = pr->pe.m_pred.rhs)
	{
	  qexec_clear_pred_xasl (thread_p, pr->pe.m_pred.lhs);
	}
      qexec_clear_pred_xasl (thread_p, pr);
      break;
    case T_EVAL_TERM:
      /* operands of type TYPE_LIST_ID are the XASLs we need to clear list files for */
      if (pred->pe.m_eval_term.et_type == T_COMP_EVAL_TERM)
	{
	  COMP_EVAL_TERM *et_comp = &pred->pe.m_eval_term.et.et_comp;
	  if (et_comp->rel_op == R_EXISTS && et_comp->lhs->type == TYPE_LIST_ID)
	    {
	      qexec_clear_head_lists (thread_p, et_comp->lhs->xasl);
	    }
	}
      else if (pred->pe.m_eval_term.et_type == T_ALSM_EVAL_TERM)
	{
	  ALSM_EVAL_TERM *et_alsm = &pred->pe.m_eval_term.et.et_alsm;
	  if (et_alsm->elemset->type == TYPE_LIST_ID)
	    {
	      qexec_clear_head_lists (thread_p, et_alsm->elemset->xasl);
	    }
	}
      /* no need to check into eval terms of type T_LIKE_EVAL_TERM and T_RLIKE_EVAL_TERM since they don't have
       * TYPE_LIST_ID operands */
      break;
    case T_NOT_TERM:
      qexec_clear_pred_xasl (thread_p, pred->pe.m_not_term);
      break;
    }
}

int
qexec_alloc_agg_hash_context_buildlist_xasl (THREAD_ENTRY * thread_p, xasl_node * xasl, XASL_STATE * xasl_state,
					     bool not_use_membuf)
{
  assert (xasl->type == BUILDLIST_PROC);
  return qexec_alloc_agg_hash_context (thread_p, &xasl->proc.buildlist, xasl_state, not_use_membuf);
}

static int
qexec_alloc_agg_hash_context (THREAD_ENTRY * thread_p, BUILDLIST_PROC_NODE * proc, XASL_STATE * xasl_state,
			      bool not_use_membuf)
{
  QFILE_TUPLE_VALUE_TYPE_LIST type_list;
  REGU_VARIABLE_LIST regu_list;
  AGGREGATE_TYPE *agg_list;
  int value_count = 0, i = 0, error_code = NO_ERROR;
  int open_list_flag = not_use_membuf ? QFILE_NOT_USE_MEMBUF : 0;

  if (!proc->g_hash_eligible)
    {
      return NO_ERROR;
    }
  assert (proc->agg_hash_context != NULL);

  /* clear fields (in case of error, things will get properly disposed) */
  proc->agg_hash_context->key_domains = NULL;
  proc->agg_hash_context->accumulator_domains = NULL;
  proc->agg_hash_context->temp_dbval_array = NULL;
  proc->agg_hash_context->part_list_id = NULL;
  proc->agg_hash_context->sorted_part_list_id = NULL;
  proc->agg_hash_context->hash_table = NULL;
  proc->agg_hash_context->temp_key = NULL;
  proc->agg_hash_context->temp_part_key = NULL;
  proc->agg_hash_context->curr_part_key = NULL;
  proc->agg_hash_context->temp_part_value = NULL;
  proc->agg_hash_context->curr_part_value = NULL;
  proc->agg_hash_context->sort_key.key = NULL;
  proc->agg_hash_context->sort_key.nkeys = 0;

  /*
   * create temporary dbvalue array
   */
  if (proc->g_func_count > 0)
    {
      proc->agg_hash_context->temp_dbval_array =
	(DB_VALUE *) db_private_alloc (thread_p, sizeof (DB_VALUE) * proc->g_func_count);
      if (proc->agg_hash_context->temp_dbval_array == NULL)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1,
		  sizeof (DB_VALUE) * proc->g_func_count);
	  goto exit_on_error;
	}
    }

  /*
   * keep key domains
   */
  proc->agg_hash_context->key_domains =
    (TP_DOMAIN **) db_private_alloc (thread_p, sizeof (TP_DOMAIN *) * proc->g_hkey_size);
  if (proc->agg_hash_context->key_domains == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, sizeof (TP_DOMAIN *) * proc->g_hkey_size);
      goto exit_on_error;
    }

  regu_list = proc->g_hk_scan_regu_list;
  for (i = 0; i < proc->g_hkey_size; i++, regu_list = regu_list->next)
    {
      assert (regu_list);
      proc->agg_hash_context->key_domains[i] = regu_list->value.domain;
    }

  /*
   * keep accumulator domains
   */
  if (proc->g_func_count > 0)
    {
      proc->agg_hash_context->accumulator_domains =
	(AGGREGATE_ACCUMULATOR_DOMAIN **) db_private_alloc (thread_p,
							    sizeof (AGGREGATE_ACCUMULATOR_DOMAIN *) *
							    proc->g_func_count);
      if (proc->agg_hash_context->accumulator_domains == NULL)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1,
		  sizeof (AGGREGATE_ACCUMULATOR_DOMAIN *) * proc->g_func_count);
	  goto exit_on_error;
	}

      agg_list = proc->g_agg_list;
      for (i = 0; i < proc->g_func_count; i++, agg_list = agg_list->next)
	{
	  assert (agg_list);
	  proc->agg_hash_context->accumulator_domains[i] = &agg_list->accumulator_domain;
	}
    }

  /*
   * create partial list file
   */

  /* compute number of values and alloc type list */
  type_list.type_cnt = proc->g_hkey_size + proc->g_func_count * 3 + 1;
  type_list.domp = (TP_DOMAIN **) db_private_alloc (thread_p, sizeof (TP_DOMAIN *) * type_list.type_cnt);
  if (type_list.domp == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, sizeof (TP_DOMAIN *) * type_list.type_cnt);
      goto exit_on_error;
    }

  /* register key domains */
  regu_list = proc->g_hk_scan_regu_list;
  value_count = 0;
  while (regu_list)
    {
      type_list.domp[value_count++] = regu_list->value.domain;
      regu_list = regu_list->next;
    }

  /* register accumulator domains */
  for (i = 0; i < proc->g_func_count; i++)
    {
      /* value and value2 are variable */
      type_list.domp[value_count++] = &tp_Variable_domain;
      type_list.domp[value_count++] = &tp_Variable_domain;

      /* third one is integer counter */
      type_list.domp[value_count++] = &tp_Integer_domain;
    }

  /* register counter domain */
  type_list.domp[value_count++] = &tp_Integer_domain;

  /* create sort key */
  proc->agg_hash_context->sort_key.key = NULL;
  proc->agg_hash_context->sort_key.nkeys = 0;

  /* create list files */
  proc->agg_hash_context->part_list_id =
    qfile_open_list (thread_p, &type_list, NULL, xasl_state->query_id, open_list_flag, NULL);
  proc->agg_hash_context->sorted_part_list_id =
    qfile_open_list (thread_p, &type_list, NULL, xasl_state->query_id, 0, NULL);

  /* create tuple descriptor for partial list files */
  proc->agg_hash_context->part_list_id->tpl_descr.f_cnt = type_list.type_cnt;
  proc->agg_hash_context->part_list_id->tpl_descr.f_valp =
    (DB_VALUE **) malloc (sizeof (DB_VALUE) * type_list.type_cnt);
  if (proc->agg_hash_context->part_list_id->tpl_descr.f_valp == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, sizeof (DB_VALUE) * type_list.type_cnt);
      goto exit_on_error;
    }

  proc->agg_hash_context->sorted_part_list_id->tpl_descr.f_cnt = type_list.type_cnt;
  proc->agg_hash_context->sorted_part_list_id->tpl_descr.f_valp =
    (DB_VALUE **) malloc (sizeof (DB_VALUE) * type_list.type_cnt);
  if (proc->agg_hash_context->sorted_part_list_id->tpl_descr.f_valp == NULL)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, sizeof (DB_VALUE) * type_list.type_cnt);
      goto exit_on_error;
    }
  /* initialize scan; this way we can call qfile_close_scan on an unopened scan without repercussions */
  proc->agg_hash_context->part_scan_id.status = S_CLOSED;

  /* free memory */
  db_private_free (thread_p, type_list.domp);

  /*
   * create hash table
   */
  proc->agg_hash_context->hash_table =
    mht_create ("Hash aggregate evaluation", HASH_AGGREGATE_DEFAULT_TABLE_SIZE, qdata_hash_agg_hkey, qdata_agg_hkey_eq);
  if (proc->agg_hash_context->hash_table == NULL)
    {
      goto exit_on_error;
    }
  else
    {
      /* we need the least recently used list */
      proc->agg_hash_context->hash_table->build_lru_list = true;
    }

  /*
   * create temp keys
   */
  proc->agg_hash_context->temp_key = qdata_alloc_agg_hkey (thread_p, proc->g_hkey_size, false);
  proc->agg_hash_context->temp_part_key = qdata_alloc_agg_hkey (thread_p, proc->g_hkey_size, true);
  proc->agg_hash_context->curr_part_key = qdata_alloc_agg_hkey (thread_p, proc->g_hkey_size, true);

  if (proc->agg_hash_context->temp_key == NULL || proc->agg_hash_context->temp_part_key == NULL
      || proc->agg_hash_context->curr_part_key == NULL)
    {
      goto exit_on_error;
    }

  /*
   * create temp values
   */
  proc->agg_hash_context->temp_part_value = qdata_alloc_agg_hvalue (thread_p, proc->g_func_count, proc->g_agg_list);
  proc->agg_hash_context->curr_part_value = qdata_alloc_agg_hvalue (thread_p, proc->g_func_count, proc->g_agg_list);

  if (proc->agg_hash_context->temp_part_value == NULL || proc->agg_hash_context->curr_part_value == NULL)
    {
      goto exit_on_error;
    }

  /*
   * initialize recdes
   */
  proc->agg_hash_context->tuple_recdes.data = 0;
  proc->agg_hash_context->tuple_recdes.type = 0;
  proc->agg_hash_context->tuple_recdes.length = 0;
  proc->agg_hash_context->tuple_recdes.area_size = 0;

  /*
   * initialize sort input tuple
   */
  proc->agg_hash_context->input_tuple.size = 0;
  proc->agg_hash_context->input_tuple.tpl = NULL;

  /*
   * initialize remaining fields
   */
  proc->agg_hash_context->hash_size = 0;
  proc->agg_hash_context->group_count = 0;
  proc->agg_hash_context->tuple_count = 0;
  proc->agg_hash_context->sorted_count = 0;
  proc->agg_hash_context->state = HS_ACCEPT_ALL;

  /* all ok */
  return NO_ERROR;

exit_on_error:

  qexec_free_agg_hash_context (thread_p, proc);
  return (error_code == NO_ERROR && (error_code = er_errid ()) == NO_ERROR) ? ER_FAILED : error_code;
}

static void
qexec_free_agg_hash_context (THREAD_ENTRY * thread_p, BUILDLIST_PROC_NODE * proc)
{
  if (!proc->g_hash_eligible)
    {
      return;
    }

  /* clear group by regular var list */
  for (REGU_VARIABLE_LIST p = proc->g_regu_list; p; p = p->next)
    {
      if (p->value.vfetch_to != NULL)
	{
	  pr_clear_value (p->value.vfetch_to);
	}
    }

  /* free value array */
  if (proc->agg_hash_context->temp_dbval_array != NULL)
    {
      db_private_free (thread_p, proc->agg_hash_context->temp_dbval_array);
      proc->agg_hash_context->temp_dbval_array = NULL;
    }

  /* free domain lists */
  if (proc->agg_hash_context->accumulator_domains != NULL)
    {
      db_private_free (thread_p, proc->agg_hash_context->accumulator_domains);
      proc->agg_hash_context->accumulator_domains = NULL;
    }

  if (proc->agg_hash_context->key_domains != NULL)
    {
      db_private_free (thread_p, proc->agg_hash_context->key_domains);
      proc->agg_hash_context->key_domains = NULL;
    }

  /* free sort key */
  qfile_clear_sort_key_info (&proc->agg_hash_context->sort_key);

  /* free entries and hash table */
  if (proc->agg_hash_context->hash_table != NULL)
    {
      (void) mht_clear (proc->agg_hash_context->hash_table, qdata_free_agg_hentry, (void *) thread_p);
      mht_destroy (proc->agg_hash_context->hash_table);

      proc->agg_hash_context->hash_table = NULL;
    }

  /* close scan */
  qfile_close_scan (thread_p, &proc->agg_hash_context->part_scan_id);

  /* free partial lists */
  if (proc->agg_hash_context->part_list_id != NULL)
    {
      qfile_close_list (thread_p, proc->agg_hash_context->part_list_id);
      qfile_destroy_list (thread_p, proc->agg_hash_context->part_list_id);
      qfile_free_list_id (proc->agg_hash_context->part_list_id);
      proc->agg_hash_context->part_list_id = NULL;
    }

  if (proc->agg_hash_context->sorted_part_list_id != NULL)
    {
      qfile_close_list (thread_p, proc->agg_hash_context->sorted_part_list_id);
      qfile_destroy_list (thread_p, proc->agg_hash_context->sorted_part_list_id);
      qfile_free_list_id (proc->agg_hash_context->sorted_part_list_id);
      proc->agg_hash_context->sorted_part_list_id = NULL;
    }

  /* free temp keys and values */
  if (proc->agg_hash_context->temp_key != NULL)
    {
      qdata_free_agg_hkey (thread_p, proc->agg_hash_context->temp_key);
      proc->agg_hash_context->temp_key = NULL;
    }

  if (proc->agg_hash_context->temp_part_key != NULL)
    {
      qdata_free_agg_hkey (thread_p, proc->agg_hash_context->temp_part_key);
      proc->agg_hash_context->temp_part_key = NULL;
    }

  if (proc->agg_hash_context->curr_part_key != NULL)
    {
      qdata_free_agg_hkey (thread_p, proc->agg_hash_context->curr_part_key);
      proc->agg_hash_context->curr_part_key = NULL;
    }

  if (proc->agg_hash_context->temp_part_value != NULL)
    {
      qdata_free_agg_hvalue (thread_p, proc->agg_hash_context->temp_part_value);
      proc->agg_hash_context->temp_part_value = NULL;
    }

  if (proc->agg_hash_context->curr_part_value != NULL)
    {
      qdata_free_agg_hvalue (thread_p, proc->agg_hash_context->curr_part_value);
      proc->agg_hash_context->curr_part_value = NULL;
    }

  /* free recdes area */
  if (proc->agg_hash_context->tuple_recdes.data != NULL)
    {
      db_private_free (thread_p, proc->agg_hash_context->tuple_recdes.data);
      proc->agg_hash_context->tuple_recdes.data = NULL;
      proc->agg_hash_context->tuple_recdes.area_size = 0;
    }

  /* reinit counters */
  proc->agg_hash_context->hash_size = 0;
  proc->agg_hash_context->group_count = 0;
  proc->agg_hash_context->tuple_count = 0;
}

static int
qexec_build_agg_hkey (THREAD_ENTRY * thread_p, XASL_STATE * xasl_state, REGU_VARIABLE_LIST regu_list, QFILE_TUPLE tpl,
		      AGGREGATE_HASH_KEY * key)
{
  int rc = NO_ERROR;

  /* build key */
  key->free_values = false;	/* references precreated DB_VALUES */
  key->val_count = 0;
  while (regu_list != NULL)
    {
      if (tpl == NULL)
	{
	  /* tpl is NULL when called during the processing phase */
	  key->values[key->val_count] = regu_list->value.vfetch_to;
	}
      else
	{
	  rc =
	    fetch_peek_dbval (thread_p, &regu_list->value, &xasl_state->vd, NULL, NULL, tpl,
			      &key->values[key->val_count]);
	  if (rc != NO_ERROR)
	    {
	      return rc;
	    }
	}

      /* next */
      regu_list = regu_list->next;
      key->val_count++;
    }

  /* all ok */
  return NO_ERROR;
}

static int
qexec_locate_agg_hentry_in_list (THREAD_ENTRY * thread_p, AGGREGATE_HASH_CONTEXT * context, AGGREGATE_HASH_KEY * key,
				 bool * found)
{
  DB_VALUE_COMPARE_RESULT result;
  bool done = false;
  int diff_pos;

  while (!done)
    {
      /* stop on last scan (or error) */
      done = (context->part_scan_code != S_SUCCESS);

      /* compare keys and invert if necessary */
      result = qdata_agg_hkey_compare (context->curr_part_key, key, &diff_pos);
      if (diff_pos >= 0 && result != DB_EQ)
	{
	  if (context->sort_key.key[diff_pos].is_desc)
	    {
	      if (result == DB_GT)
		{
		  result = DB_LT;
		}
	      else if (result == DB_LT)
		{
		  result = DB_GT;
		}
	    }
	}

      /* decide based on comparison result */
      if (result == DB_UNK || result == DB_NE)
	{
	  /* incomparable types or null value; should not get here */
	  return ER_FAILED;
	}
      else if (result == DB_EQ)
	{
	  /* found key */
	  *found = true;
	  return NO_ERROR;
	}
      else if (result == DB_GT)
	{
	  /* current key in partial list is greater than provided key */
	  *found = false;
	  return NO_ERROR;
	}
      else if (!done)
	{
	  /* scan for next */
	  context->part_scan_code =
	    qdata_load_agg_hentry_from_list (thread_p, &context->part_scan_id, context->curr_part_key,
					     context->curr_part_value, context->key_domains,
					     context->accumulator_domains);
	}
    }

  /* reached end of scan, no match */
  *found = false;
  return (context->part_scan_code == S_ERROR ? ER_FAILED : NO_ERROR);
}

int
qexec_execute_subquery_for_result_cache (THREAD_ENTRY * thread_p, XASL_NODE * xasl, XASL_STATE * xasl_state)
{
  assert (xasl != NULL);
  assert (xasl->sub_xasl_id != NULL);

  int i;
  int host_var_count = xasl->sub_host_var_count;
  int *host_var_index = xasl->sub_host_var_index;

  QFILE_LIST_ID *list_id = NULL;	/* list-id of cached result */
  DB_VALUE *dbval_p = NULL;	/* db values' pointer for searching cached query */
  XASL_CACHE_ENTRY *ent = NULL;	/* xasl for cached query */
  QFILE_LIST_CACHE_ENTRY *list_cache_entry_p;

  xcache_find_sha1 (thread_p, &xasl->sub_xasl_id->sha1, XASL_CACHE_SEARCH_GENERIC, &ent, NULL);
  if (ent)
    {
      DB_VALUE_ARRAY params;
      bool cached_result;

      if (host_var_count > 0)
	{
	  dbval_p = (DB_VALUE *) malloc (sizeof (DB_VALUE) * host_var_count);
	  for (i = 0; i < host_var_count; i++)
	    {
	      dbval_p[i] = xasl_state->vd.dbval_ptr[host_var_index[i]];
	    }
	}

      params.size = host_var_count;
      params.vals = dbval_p;

      list_cache_entry_p = qfile_lookup_list_cache_entry (thread_p, ent, &params, &cached_result);
      if (cached_result && list_cache_entry_p)
	{
	  list_id = &list_cache_entry_p->list_id;
	  xasl->sub_cache_ref_count = list_cache_entry_p->ref_count;
	}

      if (host_var_count > 0)
	{
	  free (dbval_p);
	}

      xcache_unfix (thread_p, ent);
    }

  if (list_id == NULL)
    {
      xasl->status = XASL_FAILURE;
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_RESULT_CACHE_INVALID, 0);

      return ER_FAILED;
    }

  xasl->status = XASL_SUCCESS;

  qfile_copy_list_id (xasl->list_id, list_id, false, QFILE_PROHIBIT_DEPENDENT);

  /* for checking the cached list file */
  xasl->list_id->is_result_cached = true;
  xasl->list_id->query_id = xasl_state->query_id;

  return NO_ERROR;
}

qexec_open_scan (THREAD_ENTRY * thread_p, ACCESS_SPEC_TYPE * curr_spec, VAL_LIST * val_list, VAL_DESCR * vd,
		 bool force_select_lock, int fixed, int grouped, bool iscan_oid_order, SCAN_ID * s_id,
		 QUERY_ID query_id, SCAN_OPERATION_TYPE scan_op_type, bool scan_immediately_stop,
		 bool * p_mvcc_select_lock_needed, XASL_NODE * xasl)
{
  bool mvcc_select_lock_needed = false;
  int error_code = NO_ERROR;

  if (curr_spec->pruning_type == DB_PARTITIONED_CLASS && !curr_spec->pruned)
    {
      error_code = qexec_prune_spec (thread_p, curr_spec, vd, scan_op_type);
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
    }


  if (curr_spec->type == TARGET_CLASS && mvcc_is_mvcc_disabled_class (&ACCESS_SPEC_CLS_OID (curr_spec)))
    {
      assert (!force_select_lock);

      /* We expect to update or delete a non MVCC objects via a scan are only _db_serial, _db_ha_apply_info and
       * _db_collation objects. */
      assert ((scan_op_type != S_DELETE && scan_op_type != S_UPDATE) || oid_is_serial (&ACCESS_SPEC_CLS_OID (curr_spec))
	      || (oid_check_cached_class_oid (OID_CACHE_HA_APPLY_INFO_CLASS_ID, &ACCESS_SPEC_CLS_OID (curr_spec)))
	      || (oid_check_cached_class_oid (OID_CACHE_COLLATION_CLASS_ID, &ACCESS_SPEC_CLS_OID (curr_spec))));
    }
  else
    {
      if (force_select_lock)
	{
	  mvcc_select_lock_needed = true;
	}
      else
	{
	  mvcc_select_lock_needed = ACCESS_SPEC_IS_FLAGED (curr_spec, ACCESS_SPEC_FLAG_FOR_UPDATE);
	}
    }

  /* Finalize cached-scan activation once per open, before dispatching on access method. The
   * driving-scan gate is assigned next to fixed_scan in qexec_execute_mainblock_internal ();
   * specs opened outside that loop (merge, UPDATE/DELETE/INSERT select scans, ...) keep the
   * false set at unpack time. Runtime-only; never serialized (see xasl.h / stream_to_xasl.c). */
  curr_spec->cached_scan = curr_spec->cached_scan
    && qexec_is_cached_scan_eligible (curr_spec, scan_op_type, mvcc_select_lock_needed, fixed, grouped);

  switch (curr_spec->type)
    {
    case TARGET_CLASS:
      {
	switch (curr_spec->access)
	  {
	  case ACCESS_METHOD_SEQUENTIAL:
	    {
#if SERVER_MODE && !WINDOWS
	      error_code =
		scan_open_parallel_heap_scan (thread_p, s_id, mvcc_select_lock_needed, scan_op_type, fixed, grouped,
					      vd, curr_spec, &ACCESS_SPEC_CLS_OID (curr_spec),
					      &ACCESS_SPEC_HFID (curr_spec), xasl, query_id);
	      if (error_code != NO_ERROR)
		{
		  ASSERT_ERROR ();
		  goto exit_on_error;
		}

	      if (s_id->type == S_PARALLEL_HEAP_SCAN)
		{
		  assert (s_id->s.phsid.manager != nullptr);
		}
	      else
		{
		  /* fallback to single-thread heap scan */
		  assert (s_id->type == S_HEAP_SCAN);

		  /* for partitioned class */
		  if (xasl->list_id->tfile_vfid != NULL && !VPID_ISNULL (&xasl->list_id->first_vpid))
		    {
		      qfile_reopen_list_as_append_mode (thread_p, xasl->list_id);
		    }
#endif /* SERVER_MODE && !WINDOWS */
		  error_code =
		    scan_open_heap_scan (thread_p, s_id, mvcc_select_lock_needed, scan_op_type, fixed, grouped,
					 curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
					 &ACCESS_SPEC_CLS_OID (curr_spec), &ACCESS_SPEC_HFID (curr_spec),
					 curr_spec->s.cls_node.cls_regu_list_pred, curr_spec->where_pred,
					 curr_spec->s.cls_node.cls_regu_list_rest, curr_spec->s.cls_node.num_attrs_pred,
					 curr_spec->s.cls_node.attrids_pred, curr_spec->s.cls_node.cache_pred,
					 curr_spec->s.cls_node.num_attrs_rest, curr_spec->s.cls_node.attrids_rest,
					 curr_spec->s.cls_node.cache_rest, S_HEAP_SCAN,
					 curr_spec->s.cls_node.cache_reserved,
					 curr_spec->s.cls_node.cls_regu_list_reserved, curr_spec->cached_scan);
		  if (error_code != NO_ERROR)
		    {
		      ASSERT_ERROR ();
		      goto exit_on_error;
		    }
#if SERVER_MODE && !WINDOWS
		}
#endif /* SERVER_MODE && !WINDOWS */
	      break;
	    }			/* case ACCESS_METHOD_SEQUENTIAL */

	  case ACCESS_METHOD_SEQUENTIAL_RECORD_INFO:	/* fall through */
	    {
	      SCAN_TYPE scan_type = S_HEAP_SCAN_RECORD_INFO;

	      error_code = scan_open_heap_scan (thread_p, s_id, mvcc_select_lock_needed, scan_op_type, fixed, grouped,
						curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
						&ACCESS_SPEC_CLS_OID (curr_spec), &ACCESS_SPEC_HFID (curr_spec),
						curr_spec->s.cls_node.cls_regu_list_pred, curr_spec->where_pred,
						curr_spec->s.cls_node.cls_regu_list_rest,
						curr_spec->s.cls_node.num_attrs_pred,
						curr_spec->s.cls_node.attrids_pred, curr_spec->s.cls_node.cache_pred,
						curr_spec->s.cls_node.num_attrs_rest,
						curr_spec->s.cls_node.attrids_rest, curr_spec->s.cls_node.cache_rest,
						scan_type, curr_spec->s.cls_node.cache_reserved,
						curr_spec->s.cls_node.cls_regu_list_reserved, curr_spec->cached_scan);
	      if (error_code != NO_ERROR)
		{
		  ASSERT_ERROR ();
		  goto exit_on_error;
		}

	      break;
	    }			/* case ACCESS_METHOD_SEQUENTIAL_RECORD_INFO */

	  case ACCESS_METHOD_SEQUENTIAL_PAGE_SCAN:
	    error_code = scan_open_heap_page_scan (thread_p, s_id, val_list, vd, &ACCESS_SPEC_CLS_OID (curr_spec),
						   &ACCESS_SPEC_HFID (curr_spec), curr_spec->where_pred,
						   S_HEAP_PAGE_SCAN, curr_spec->s.cls_node.cache_reserved,
						   curr_spec->s.cls_node.cls_regu_list_reserved);
	    if (error_code != NO_ERROR)
	      {
		ASSERT_ERROR ();
		goto exit_on_error;
	      }
	    break;

	  case ACCESS_METHOD_INDEX:
	    error_code = scan_open_index_scan (thread_p, s_id, mvcc_select_lock_needed, scan_op_type, fixed, grouped,
					       curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
					       curr_spec->indexptr, &ACCESS_SPEC_CLS_OID (curr_spec),
					       &ACCESS_SPEC_HFID (curr_spec), curr_spec->s.cls_node.cls_regu_list_key,
					       curr_spec->where_key, curr_spec->s.cls_node.cls_regu_list_pred,
					       curr_spec->where_pred, curr_spec->s.cls_node.cls_regu_list_rest,
					       curr_spec->where_range, curr_spec->s.cls_node.cls_regu_list_range,
					       curr_spec->s.cls_node.cls_output_val_list,
					       curr_spec->s.cls_node.cls_regu_val_list,
					       curr_spec->s.cls_node.num_attrs_key, curr_spec->s.cls_node.attrids_key,
					       curr_spec->s.cls_node.cache_key, curr_spec->s.cls_node.num_attrs_pred,
					       curr_spec->s.cls_node.attrids_pred, curr_spec->s.cls_node.cache_pred,
					       curr_spec->s.cls_node.num_attrs_rest,
					       curr_spec->s.cls_node.attrids_rest, curr_spec->s.cls_node.cache_rest,
					       curr_spec->s.cls_node.num_attrs_range,
					       curr_spec->s.cls_node.attrids_range, curr_spec->s.cls_node.cache_range,
					       iscan_oid_order, query_id, ACCESS_SPEC_IS_FLAGED (curr_spec,
												 ACCESS_SPEC_FLAG_ONLY_MIN_MAX_SCAN));
	    if (error_code != NO_ERROR)
	      {
		ASSERT_ERROR ();
		goto exit_on_error;
	      }

#if SERVER_MODE && !WINDOWS
	    error_code = scan_open_parallel_index_scan (thread_p, s_id, vd, curr_spec,
							&ACCESS_SPEC_CLS_OID (curr_spec), &ACCESS_SPEC_HFID (curr_spec),
							xasl, query_id);
	    if (error_code != NO_ERROR)
	      {
		ASSERT_ERROR ();
		goto exit_on_error;
	      }
#endif /* SERVER_MODE && !WINDOWS */

	    /* monitor */
	    perfmon_inc_stat (thread_p, PSTAT_QM_NUM_ISCANS);
	    break;

	  case ACCESS_METHOD_INDEX_KEY_INFO:
	    error_code =
	      scan_open_index_key_info_scan (thread_p, s_id, val_list, vd, curr_spec->indexptr,
					     &ACCESS_SPEC_CLS_OID (curr_spec), &ACCESS_SPEC_HFID (curr_spec),
					     curr_spec->where_pred, curr_spec->s.cls_node.cls_output_val_list,
					     iscan_oid_order, query_id, curr_spec->s.cls_node.cache_reserved,
					     curr_spec->s.cls_node.cls_regu_list_reserved);
	    if (error_code != NO_ERROR)
	      {
		ASSERT_ERROR ();
		goto exit_on_error;
	      }

	    /* monitor */
	    perfmon_inc_stat (thread_p, PSTAT_QM_NUM_ISCANS);
	    break;

	  case ACCESS_METHOD_INDEX_NODE_INFO:
	    error_code =
	      scan_open_index_node_info_scan (thread_p, s_id, val_list, vd, curr_spec->indexptr,
					      curr_spec->where_pred, curr_spec->s.cls_node.cache_reserved,
					      curr_spec->s.cls_node.cls_regu_list_reserved);
	    if (error_code != NO_ERROR)
	      {
		ASSERT_ERROR ();
		goto exit_on_error;
	      }

	    /* monitor */
	    perfmon_inc_stat (thread_p, PSTAT_QM_NUM_ISCANS);
	    break;

	  default:
	    er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_INVALID_XASLNODE, 0);
	    return ER_QPROC_INVALID_XASLNODE;
	  }			/* switch (curr_spec->access) */

	break;
      }				/* case TARGET_CLASS */

    case TARGET_CLASS_ATTR:
      error_code =
	scan_open_class_attr_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
				   &ACCESS_SPEC_CLS_OID (curr_spec), &ACCESS_SPEC_HFID (curr_spec),
				   curr_spec->s.cls_node.cls_regu_list_pred, curr_spec->where_pred,
				   curr_spec->s.cls_node.cls_regu_list_rest, curr_spec->s.cls_node.num_attrs_pred,
				   curr_spec->s.cls_node.attrids_pred, curr_spec->s.cls_node.cache_pred,
				   curr_spec->s.cls_node.num_attrs_rest, curr_spec->s.cls_node.attrids_rest,
				   curr_spec->s.cls_node.cache_rest);
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
      break;

    case TARGET_LIST:
      {
	/* open a list file scan */
	QFILE_LIST_ID *list_id = NULL;
	bool is_connect_by_list = false;

	if (ACCESS_SPEC_XASL_NODE (curr_spec) && ACCESS_SPEC_XASL_NODE (curr_spec)->spec_list == curr_spec)
	  {
	    /* if XASL of access spec for list scan is itself then this is for HQ */
	    list_id = ACCESS_SPEC_CONNECT_BY_LIST_ID (curr_spec);
	    is_connect_by_list = true;
	  }
	else
	  {
	    list_id = ACCESS_SPEC_LIST_ID (curr_spec);
	  }

#if SERVER_MODE && !WINDOWS
	/* connect-by HQ shares list with producer XASL — never parallelize */
	if (!is_connect_by_list)
	  {
	    error_code = scan_open_parallel_list_scan (thread_p, s_id, vd, curr_spec, list_id, xasl, query_id);
	    if (error_code != NO_ERROR)
	      {
		ASSERT_ERROR ();
		goto exit_on_error;
	      }

	    if (s_id->type == S_PARALLEL_LIST_SCAN)
	      {
		assert (s_id->s.pllsid_parallel.manager != nullptr);
		break;
	      }
	  }
#endif /* SERVER_MODE && !WINDOWS */
	error_code =
	  scan_open_list_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
			       list_id, curr_spec->s.list_node.list_regu_list_pred,
			       curr_spec->where_pred, curr_spec->s.list_node.list_regu_list_rest,
			       curr_spec->s.list_node.list_regu_list_build,
			       curr_spec->s.list_node.list_regu_list_probe,
			       curr_spec->s.list_node.hash_list_scan_yn, false);
	if (error_code != NO_ERROR)
	  {
	    ASSERT_ERROR ();
	    goto exit_on_error;
	  }

	break;
      }				/* case TARGET_LIST */

    case TARGET_SHOWSTMT:
      /* open a showstmt scan */
      error_code =
	scan_open_showstmt_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
				 curr_spec->where_pred, curr_spec->s.showstmt_node.show_type,
				 curr_spec->s.showstmt_node.arg_list);
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
      break;

    case TARGET_REGUVAL_LIST:
      /* open a regu value list scan */
      error_code =
	scan_open_values_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
			       ACCESS_SPEC_RLIST_VALPTR_LIST (curr_spec));
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
      break;

    case TARGET_SET:
      /* open a set based derived table scan */
      error_code =
	scan_open_set_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
			    ACCESS_SPEC_SET_PTR (curr_spec), ACCESS_SPEC_SET_REGU_LIST (curr_spec),
			    curr_spec->where_pred);
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
      break;

    case TARGET_JSON_TABLE:
      /* open a json table based derived table scan */
      error_code =
	scan_open_json_table_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list,
				   vd, curr_spec->where_pred);
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
      break;

    case TARGET_METHOD:
      error_code =
	scan_open_method_scan (thread_p, s_id, grouped, curr_spec->single_fetch, curr_spec->s_dbval, val_list, vd,
			       ACCESS_SPEC_METHOD_LIST_ID (curr_spec), ACCESS_SPEC_METHOD_SIG_ARRAY (curr_spec));
      if (error_code != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
      break;

    case TARGET_DBLINK:
      {
	DBLINK_HOST_VARS host_vars;

	host_vars.count = curr_spec->s.dblink_node.host_var_count;
	host_vars.index = curr_spec->s.dblink_node.host_var_index;

	/* inject reuse flag before open: scan_init_scan_id does not touch s.dblid.scan_info,
	 * so the flag survives across open/close cycles. */
	s_id->s.dblid.scan_info.cursor_rewind = IS_DBLINK_CURSOR_REWIND_XASL (xasl);

	error_code = scan_open_dblink_scan (thread_p, s_id, curr_spec, vd, val_list, &host_vars);
	if (error_code != NO_ERROR)
	  {
	    ASSERT_ERROR ();
	    goto exit_on_error;
	  }

	/* DBLINK (..., "SELECT <result columns part> FROM ...") AS tname ( <alias columns part> )
	 * s_id->s.dblid.scan_buf.col_cnt is the number of elements in the list <result columns part>.
	 * val_list->val_cnt is the number of elements in the list <alias columns part>. */
	if (val_list->val_cnt != s_id->s.dblid.scan_info.col_cnt)
	  {
	    er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_DBLINK_INVALID_COLUMNS_SPECIFIED, 0);
	    error_code = ER_DBLINK_INVALID_COLUMNS_SPECIFIED;
	    goto exit_on_error;
	  }

	break;
      }				/* case TARGET_DBLINK */

    default:
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_INVALID_XASLNODE, 0);
      error_code = ER_QPROC_INVALID_XASLNODE;
      goto exit_on_error;
    }				/* switch */

  s_id->scan_immediately_stop = scan_immediately_stop;

  if (p_mvcc_select_lock_needed)
    {
      *p_mvcc_select_lock_needed = mvcc_select_lock_needed;
    }

  if (scan_op_type == S_SELECT && curr_spec->pruning_type == DB_PARTITIONED_CLASS && curr_spec->pruned)
    {
      error_code = qexec_init_next_partition (thread_p, curr_spec, xasl);
      if (error_code != S_SUCCESS)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}
    }

  return NO_ERROR;

exit_on_error:
  /* TODO: cleared by qexec_clear_access_spec_list; redundant? */
  if (curr_spec->pruning_type == DB_PARTITIONED_CLASS && curr_spec->parts != NULL)
    {
      /* reset pruning info */
      free (curr_spec->parts);
      curr_spec->parts = NULL;
      curr_spec->curent = NULL;
      curr_spec->pruned = false;
    }

  /* free sampling pick on early-error; idempotent vs clear backstop */

  ASSERT_ERROR_AND_SET (error_code);
  return error_code;
}

qexec_init_next_partition (THREAD_ENTRY * thread_p, ACCESS_SPEC_TYPE * spec, XASL_NODE * xasl)
{
  int error = NO_ERROR;
  OID class_oid;
  HFID class_hfid;
  BTID btid;
  int i;

  if (spec->type != TARGET_CLASS && spec->type != TARGET_CLASS_ATTR)
    {
      return S_END;
    }

  if (spec->parts == NULL)
    {
      return S_END;
    }

  /* close current scan and open a new one on the next partition */
  scan_end_scan (thread_p, &spec->s_id);
  scan_close_scan (thread_p, &spec->s_id);

  /* we also need to reset caches for attributes */
  qexec_reset_regu_variable_list (spec->s.cls_node.cls_regu_list_pred);
  qexec_reset_regu_variable_list (spec->s.cls_node.cls_regu_list_rest);
  qexec_reset_regu_variable_list (spec->s.cls_node.cls_regu_list_key);
  qexec_reset_pred_expr (spec->where_pred);
  qexec_reset_pred_expr (spec->where_key);

  if (spec->curent == NULL)
    {
      /* first partition */
      spec->curent = spec->parts;
    }
  else
    {
#if SERVER_MODE && !WINDOWS
      /* save stats for the partition before ending the current scan */
      if (thread_is_on_trace (thread_p))
	{
	  /* parallel-only: serial leaves m_stats_last stale and clobbers per-row deltas accumulated via 5406 */
	  if (spec->s_id.type == S_PARALLEL_HEAP_SCAN)
	    {
	      if (spec->s_id.s.phsid.trace_storage)
		{
		  if (thread_p->m_px_stats != NULL)
		    {
		      spec->s_id.scan_stats.num_fetches +=
			thread_p->m_px_stats[pstat_Metadata[PSTAT_PB_NUM_FETCHES].start_offset];
		      spec->s_id.scan_stats.num_ioreads +=
			thread_p->m_px_stats[pstat_Metadata[PSTAT_PB_NUM_IOREADS].start_offset];
		    }

		  spec->s_id.s.phsid.trace_storage->set_last_partition_stats (&spec->curent->scan_stats);
		}
	    }
	  else if (spec->s_id.type == S_PARALLEL_INDEX_SCAN)
	    {
	      if (spec->s_id.s.pisid.trace_storage)
		{
		  if (thread_p->m_px_stats != NULL)
		    {
		      spec->s_id.scan_stats.num_fetches +=
			thread_p->m_px_stats[pstat_Metadata[PSTAT_PB_NUM_FETCHES].start_offset];
		      spec->s_id.scan_stats.num_ioreads +=
			thread_p->m_px_stats[pstat_Metadata[PSTAT_PB_NUM_IOREADS].start_offset];
		    }

		  spec->s_id.s.pisid.trace_storage->set_last_partition_stats (&spec->curent->scan_stats);
		}
	    }
	}
#endif

      /* move to next partition */
      if (spec->curent->next == NULL)
	{
	  /* no more partitions */
	  spec->curent = NULL;
	}
      else
	{
	  spec->curent = spec->curent->next;
	}
    }

  /* prepare to record stats for the next partition */
  if (thread_is_on_trace (thread_p))
    {
      if (spec->curent != NULL)
	{
	  spec->s_id.partition_stats = &spec->curent->scan_stats;

	  spec->s_id.partition_stats->covered_index = spec->s_id.scan_stats.covered_index;
	  spec->s_id.partition_stats->multi_range_opt = spec->s_id.scan_stats.multi_range_opt;
	  spec->s_id.partition_stats->index_skip_scan = spec->s_id.scan_stats.index_skip_scan;
	  spec->s_id.partition_stats->loose_index_scan = spec->s_id.scan_stats.loose_index_scan;
	  spec->s_id.partition_stats->noscan = spec->s_id.scan_stats.noscan;

	  /* SCAN_STATS for DB_PARTITION_CLASS does not support AGL (Aggregate Lookup Optimization). */
	  spec->s_id.partition_stats->agl = NULL;
	}
      else
	{
	  spec->s_id.partition_stats = NULL;
	}
    }

  if (spec->curent == NULL)
    {
      /* reset back to root class */
      COPY_OID (&class_oid, &ACCESS_SPEC_CLS_OID (spec));
      HFID_COPY (&class_hfid, &ACCESS_SPEC_HFID (spec));
      if (IS_ANY_INDEX_ACCESS (spec->access))
	{
	  btid = spec->btid;
	}
    }
  else
    {
      COPY_OID (&class_oid, &spec->curent->oid);
      HFID_COPY (&class_hfid, &spec->curent->hfid);
      if (IS_ANY_INDEX_ACCESS (spec->access))
	{
	  btid = spec->curent->btid;
	}
    }

  switch (spec->type)
    {
    case TARGET_CLASS:
      {
	switch (spec->access)
	  {
	  case ACCESS_METHOD_SEQUENTIAL:
	    {
	      QUERY_ID query_id = spec->s_id.vd->xasl_state->query_id;
	      HEAP_SCAN_ID *hsidp = &spec->s_id.s.hsid;

	      /* clear caches */
	      if (hsidp->caches_inited)
		{
		  heap_attrinfo_end (thread_p, hsidp->pred_attrs.attr_cache);
		  heap_attrinfo_end (thread_p, hsidp->rest_attrs.attr_cache);
		  if (hsidp->cache_recordinfo != NULL)
		    {
		      for (i = 0; i < HEAP_RECORD_INFO_COUNT; i++)
			{
			  pr_clear_value (hsidp->cache_recordinfo[i]);
			}
		    }
		  hsidp->caches_inited = false;
		}
	      hsidp->scancache_inited = false;

#if SERVER_MODE && !WINDOWS
	      error =
		scan_open_parallel_heap_scan (thread_p, &spec->s_id, spec->s_id.mvcc_select_lock_needed,
					      spec->s_id.scan_op_type, spec->s_id.fixed, spec->s_id.grouped,
					      spec->s_id.vd, spec, &class_oid, &class_hfid, xasl, query_id);
	      if (error != NO_ERROR)
		{
		  ASSERT_ERROR ();
		  return S_ERROR;
		}

	      if (spec->s_id.type == S_PARALLEL_HEAP_SCAN)
		{
		  assert (spec->s_id.type == S_PARALLEL_HEAP_SCAN);
		  assert (spec->s_id.s.phsid.manager != nullptr);
		}
	      else
		{
		  /* fallback to single-thread heap scan */
		  assert (spec->s_id.type == S_HEAP_SCAN);

		  /* for partitioned class */
		  if (xasl->list_id->tfile_vfid != NULL && !VPID_ISNULL (&xasl->list_id->first_vpid))
		    {
		      qfile_reopen_list_as_append_mode (thread_p, xasl->list_id);
		    }
#endif /* SERVER_MODE && !WINDOWS */
		  error =
		    scan_open_heap_scan (thread_p, &spec->s_id, spec->s_id.mvcc_select_lock_needed,
					 spec->s_id.scan_op_type, spec->s_id.fixed, spec->s_id.grouped,
					 spec->s_id.single_fetch, spec->s_dbval, spec->s_id.val_list, spec->s_id.vd,
					 &class_oid, &class_hfid, spec->s.cls_node.cls_regu_list_pred, spec->where_pred,
					 spec->s.cls_node.cls_regu_list_rest, spec->s.cls_node.num_attrs_pred,
					 spec->s.cls_node.attrids_pred, spec->s.cls_node.cache_pred,
					 spec->s.cls_node.num_attrs_rest, spec->s.cls_node.attrids_rest,
					 spec->s.cls_node.cache_rest, S_HEAP_SCAN, spec->s.cls_node.cache_reserved,
					 spec->s.cls_node.cls_regu_list_reserved, spec->s_id.cached_scan);
		  if (error != NO_ERROR)
		    {
		      ASSERT_ERROR ();
		      return S_ERROR;
		    }
#if SERVER_MODE && !WINDOWS
		}
#endif /* SERVER_MODE && !WINDOWS */

	      break;
	    }			/* case ACCESS_METHOD_SEQUENTIAL */

	  case ACCESS_METHOD_SEQUENTIAL_RECORD_INFO:	/* fall through */
	    {
	      HEAP_SCAN_ID *hsidp = &spec->s_id.s.hsid;
	      SCAN_TYPE scan_type = S_HEAP_SCAN_RECORD_INFO;

	      /* clear caches */
	      if (hsidp->caches_inited)
		{
		  heap_attrinfo_end (thread_p, hsidp->pred_attrs.attr_cache);
		  heap_attrinfo_end (thread_p, hsidp->rest_attrs.attr_cache);
		  if (hsidp->cache_recordinfo != NULL)
		    {
		      for (i = 0; i < HEAP_RECORD_INFO_COUNT; i++)
			{
			  pr_clear_value (hsidp->cache_recordinfo[i]);
			}
		    }
		  hsidp->caches_inited = false;
		}
	      hsidp->scancache_inited = false;

	      error =
		scan_open_heap_scan (thread_p, &spec->s_id, spec->s_id.mvcc_select_lock_needed, spec->s_id.scan_op_type,
				     spec->s_id.fixed, spec->s_id.grouped, spec->s_id.single_fetch, spec->s_dbval,
				     spec->s_id.val_list, spec->s_id.vd, &class_oid, &class_hfid,
				     spec->s.cls_node.cls_regu_list_pred, spec->where_pred,
				     spec->s.cls_node.cls_regu_list_rest, spec->s.cls_node.num_attrs_pred,
				     spec->s.cls_node.attrids_pred, spec->s.cls_node.cache_pred,
				     spec->s.cls_node.num_attrs_rest, spec->s.cls_node.attrids_rest,
				     spec->s.cls_node.cache_rest, scan_type, spec->s.cls_node.cache_reserved,
				     spec->s.cls_node.cls_regu_list_reserved, spec->s_id.cached_scan);
	      if (error != NO_ERROR)
		{
		  return S_ERROR;
		}

	      break;
	    }			/* case ACCESS_METHOD_SEQUENTIAL_RECORD_INFO */

	  case ACCESS_METHOD_SEQUENTIAL_PAGE_SCAN:
	    {
	      HEAP_PAGE_SCAN_ID *hpsidp = &spec->s_id.s.hpsid;

	      /* clear caches */
	      if (hpsidp->cache_page_info != NULL)
		{
		  for (i = 0; i < HEAP_PAGE_INFO_COUNT; i++)
		    {
		      pr_clear_value (hpsidp->cache_page_info[i]);
		    }
		}

	      error =
		scan_open_heap_page_scan (thread_p, &spec->s_id, spec->s_id.val_list, spec->s_id.vd, &class_oid,
					  &class_hfid, spec->where_pred, S_HEAP_PAGE_SCAN,
					  spec->s.cls_node.cache_reserved, spec->s.cls_node.cls_regu_list_reserved);
	      if (error != NO_ERROR)
		{
		  return S_ERROR;
		}

	      break;
	    }			/* case ACCESS_METHOD_SEQUENTIAL_PAGE_SCAN */

	  case ACCESS_METHOD_INDEX:
	    {
	      QUERY_ID query_id = spec->s_id.vd->xasl_state->query_id;
	      INDX_SCAN_ID *isidp = &spec->s_id.s.isid;
	      bool iscan_oid_order = spec->s_id.s.isid.iscan_oid_order;

	      /* clear caches */
	      if (isidp->caches_inited)
		{
		  if (isidp->range_pred.regu_list)
		    {
		      heap_attrinfo_end (thread_p, isidp->range_attrs.attr_cache);

		      /* some attributes might remain also cached in pred_expr
		       * (lhs|rhs).value.attr_descr.cache_dbvalp might point to attr_cache values
		       * see fetch_peek_dbval for example */
		      qexec_reset_pred_expr (isidp->range_pred.pred_expr);
		    }
		  if (isidp->key_pred.regu_list)
		    {
		      heap_attrinfo_end (thread_p, isidp->key_attrs.attr_cache);
		    }
		  heap_attrinfo_end (thread_p, isidp->pred_attrs.attr_cache);
		  heap_attrinfo_end (thread_p, isidp->rest_attrs.attr_cache);
		  isidp->caches_inited = false;
		}
	      spec->s_id.s.isid.scancache_inited = false;

	      spec->indexptr->btid = btid;

	      error =
		scan_open_index_scan (thread_p, &spec->s_id, spec->s_id.mvcc_select_lock_needed,
				      spec->s_id.scan_op_type, spec->s_id.fixed, spec->s_id.grouped,
				      spec->s_id.single_fetch, spec->s_dbval, spec->s_id.val_list, spec->s_id.vd,
				      spec->indexptr, &class_oid, &class_hfid, spec->s.cls_node.cls_regu_list_key,
				      spec->where_key, spec->s.cls_node.cls_regu_list_pred, spec->where_pred,
				      spec->s.cls_node.cls_regu_list_rest, spec->where_range,
				      spec->s.cls_node.cls_regu_list_range, spec->s.cls_node.cls_output_val_list,
				      spec->s.cls_node.cls_regu_val_list, spec->s.cls_node.num_attrs_key,
				      spec->s.cls_node.attrids_key, spec->s.cls_node.cache_key,
				      spec->s.cls_node.num_attrs_pred, spec->s.cls_node.attrids_pred,
				      spec->s.cls_node.cache_pred, spec->s.cls_node.num_attrs_rest,
				      spec->s.cls_node.attrids_rest, spec->s.cls_node.cache_rest,
				      spec->s.cls_node.num_attrs_range, spec->s.cls_node.attrids_range,
				      spec->s.cls_node.cache_range, iscan_oid_order, query_id,
				      ACCESS_SPEC_IS_FLAGED (spec, ACCESS_SPEC_FLAG_ONLY_MIN_MAX_SCAN));
	      if (error != NO_ERROR)
		{
		  return S_ERROR;
		}

#if SERVER_MODE && !WINDOWS
	      error =
		scan_open_parallel_index_scan (thread_p, &spec->s_id, spec->s_id.vd, spec,
					       &class_oid, &class_hfid, xasl, query_id);
	      if (error != NO_ERROR)
		{
		  return S_ERROR;
		}
#endif /* SERVER_MODE && !WINDOWS */

	      break;
	    }			/* case ACCESS_METHOD_INDEX */

	  case ACCESS_METHOD_JSON_TABLE:	/* fall through */
	  case ACCESS_METHOD_SCHEMA:	/* fall through */
	  case ACCESS_METHOD_INDEX_KEY_INFO:	/* fall through */
	  case ACCESS_METHOD_INDEX_NODE_INFO:	/* fall through */
	  default:
	    /* impossible case */
	    er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_INVALID_XASLNODE, 0);
	    return S_ERROR;
	  }			/* switch (spec->access) */

	break;
      }				/* case TARGET_CLASS */

    case TARGET_CLASS_ATTR:
      /* clear caches */
      if (spec->s_id.s.hsid.caches_inited)
	{
	  heap_attrinfo_end (thread_p, spec->s_id.s.hsid.pred_attrs.attr_cache);
	  heap_attrinfo_end (thread_p, spec->s_id.s.hsid.rest_attrs.attr_cache);
	  spec->s_id.s.hsid.caches_inited = false;
	}

      error =
	scan_open_class_attr_scan (thread_p, &spec->s_id, spec->s_id.grouped, spec->single_fetch, spec->s_dbval,
				   spec->s_id.val_list, spec->s_id.vd, &class_oid, &class_hfid,
				   spec->s.cls_node.cls_regu_list_pred, spec->where_pred,
				   spec->s.cls_node.cls_regu_list_rest, spec->s.cls_node.num_attrs_pred,
				   spec->s.cls_node.attrids_pred, spec->s.cls_node.cache_pred,
				   spec->s.cls_node.num_attrs_rest, spec->s.cls_node.attrids_rest,
				   spec->s.cls_node.cache_rest);
      if (error != NO_ERROR)
	{
	  return S_ERROR;
	}
      break;

    default:
      /* impossible case */
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_INVALID_XASLNODE, 0);
      return S_ERROR;
    }				/* switch (spec->type) */

  if (spec->curent == NULL)
    {
      return S_END;
    }

  error = scan_start_scan (thread_p, &spec->s_id);
  if (error != NO_ERROR)
    {
      return S_ERROR;
    }

  ASSERT_NO_ERROR_OR_INTERRUPTED ();
  return S_SUCCESS;
}

int
xserial_get_current_value (THREAD_ENTRY * thread_p, DB_VALUE * result_num, const OID * oid_p, int cached_num)
{
  int ret = NO_ERROR;
  SERIAL_CACHE_ENTRY *entry;

  assert (oid_p != NULL);
  assert (result_num != NULL);

  if (cached_num <= 1)
    {
      /* not used serial cache */
      ret = xserial_get_current_value_internal (thread_p, result_num, oid_p);
    }
  else
    {
      /* used serial cache: lock-free lookup, per-entry mutex for the value read */
      OID key = *oid_p;
      entry = serial_Cache_hashmap.find (thread_p, key);
      if (entry != NULL)
	{
	  pr_clone_value (&entry->cur_val, result_num);
	  pthread_mutex_unlock (&entry->mutex);
	}
      else
	{
	  ret = xserial_get_current_value_internal (thread_p, result_num, oid_p);
	}
    }

  return ret;
}

int
xserial_get_cached_num (THREAD_ENTRY * thread_p, int *cached_num, const OID * serial_oidp)
{
  int ret = NO_ERROR;
  HEAP_SCANCACHE scan_cache;
  SCAN_CODE scan;
  RECDES recdesc = RECDES_INITIALIZER;
  HEAP_CACHE_ATTRINFO attr_info, *attr_info_p = NULL;
  ATTR_ID attrid;
  DB_VALUE *val;
  OID serial_class_oid;

  *cached_num = 0;

  oid_get_serial_oid (&serial_class_oid);
  heap_scancache_quick_start_with_class_oid (thread_p, &scan_cache, &serial_class_oid);

  /* get record into record desc; consumed only through the attribute layer (CBRD-26847) */
  scan =
    heap_get_visible_version (thread_p, serial_oidp, &serial_class_oid, &recdesc, &scan_cache, PEEK, NULL_CHN,
			      HEAP_RECDES_DONT_CONSUME_RAW_BYTES);
  if (scan != S_SUCCESS)
    {
      if (er_errid () == ER_PB_BAD_PAGEID)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_UNKNOWN_OBJECT, 3, serial_oidp->volid, serial_oidp->pageid,
		  serial_oidp->slotid);
	}
      else
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_CANNOT_FETCH_SERIAL, 0);
	}
      goto exit_on_error;
    }

  /* retrieve the cached_num attribute */
  if (serial_get_attrid (thread_p, SERIAL_ATTR_CACHED_NUM_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  if (attrid != NOT_FOUND)
    {
      ret = heap_attrinfo_start (thread_p, &serial_class_oid, 1, &attrid, &attr_info);
      if (ret != NO_ERROR)
	{
	  goto exit_on_error;
	}
      attr_info_p = &attr_info;

      ret = heap_attrinfo_read_dbvalues (thread_p, serial_oidp, &recdesc, attr_info_p);
      if (ret != NO_ERROR)
	{
	  goto exit_on_error;
	}

      val = heap_attrinfo_access (attrid, attr_info_p);
      *cached_num = db_get_int (val);

      heap_attrinfo_end (thread_p, attr_info_p);
      attr_info_p = NULL;
    }

  heap_scancache_end (thread_p, &scan_cache);

  return NO_ERROR;

exit_on_error:

  if (attr_info_p != NULL)
    {
      heap_attrinfo_end (thread_p, attr_info_p);
    }

  heap_scancache_end (thread_p, &scan_cache);

  ret = (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
  return ret;
}

static int
xserial_get_current_value_internal (THREAD_ENTRY * thread_p, DB_VALUE * result_num, const OID * serial_oidp)
{
  int ret = NO_ERROR;
  HEAP_SCANCACHE scan_cache;
  SCAN_CODE scan;
  RECDES recdesc = RECDES_INITIALIZER;
  HEAP_CACHE_ATTRINFO attr_info, *attr_info_p = NULL;
  ATTR_ID attrid;
  DB_VALUE *cur_val;
  OID serial_class_oid;

  oid_get_serial_oid (&serial_class_oid);
  heap_scancache_quick_start_with_class_oid (thread_p, &scan_cache, &serial_class_oid);

  /* get record into record desc; consumed only through the attribute layer (CBRD-26847) */
  scan =
    heap_get_visible_version (thread_p, serial_oidp, &serial_class_oid, &recdesc, &scan_cache, PEEK, NULL_CHN,
			      HEAP_RECDES_DONT_CONSUME_RAW_BYTES);
  if (scan != S_SUCCESS)
    {
      if (er_errid () == ER_PB_BAD_PAGEID)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_UNKNOWN_OBJECT, 3, serial_oidp->volid, serial_oidp->pageid,
		  serial_oidp->slotid);
	}
      else
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_CANNOT_FETCH_SERIAL, 0);
	}
      goto exit_on_error;
    }

  /* retrieve attribute */
  if (serial_get_attrid (thread_p, SERIAL_ATTR_CURRENT_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  ret = heap_attrinfo_start (thread_p, oid_Serial_class_oid, 1, &attrid, &attr_info);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  attr_info_p = &attr_info;

  ret = heap_attrinfo_read_dbvalues (thread_p, serial_oidp, &recdesc, attr_info_p);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  cur_val = heap_attrinfo_access (attrid, attr_info_p);

  pr_share_value (cur_val, result_num);

  heap_attrinfo_end (thread_p, attr_info_p);

  heap_scancache_end (thread_p, &scan_cache);

  return NO_ERROR;

exit_on_error:

  if (attr_info_p != NULL)
    {
      heap_attrinfo_end (thread_p, attr_info_p);
    }

  heap_scancache_end (thread_p, &scan_cache);

  ret = (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
  return ret;
}

int
xserial_get_next_value (THREAD_ENTRY * thread_p, DB_VALUE * result_num, const OID * oid_p, int cached_num,
			int num_alloc, int is_auto_increment, bool force_set_last_insert_id)
{
  int ret = NO_ERROR;
  SERIAL_CACHE_ENTRY *entry;

  assert (oid_p != NULL);
  assert (result_num != NULL);

  CHECK_MODIFICATION_NO_RETURN (thread_p, ret);
  if (ret != NO_ERROR)
    {
      return ret;
    }

  if (num_alloc < 1)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_INVALID_PARAMETER, 0);
      return ER_FAILED;
    }

  if (cached_num <= 1)
    {
      /* not used serial cache */
      ret = xserial_get_next_value_internal (thread_p, result_num, oid_p, num_alloc, NULL);
    }
  else
    {
      /* used serial cache: lock-free lookup, per-entry mutex for the value advance */
      OID key = *oid_p;
      entry = serial_Cache_hashmap.find (thread_p, key);
      if (entry != NULL)
	{
	  ret = serial_get_next_cached_value (thread_p, entry, num_alloc);
	  if (ret == NO_ERROR)
	    {
	      pr_clone_value (&entry->cur_val, result_num);
	    }
	  pthread_mutex_unlock (&entry->mutex);
	}
      else
	{
	  /* Cache miss: find_or_insert claims the entry (locked). The inserter is the initializer and
	   * loads one block; others wait on the entry mutex and reuse it. No OID X_LOCK (so no blocking
	   * lock while a query page is fixed); one block reserved (so a first-access burst leaves no gap). */
	  bool inserted = serial_Cache_hashmap.find_or_insert (thread_p, key, entry);
	  if (entry == NULL)
	    {
	      assert (er_errid () != NO_ERROR);
	      ret = er_errid ();
	    }
	  else if (inserted)
	    {
	      /* Initializer: on success internal fills+unlocks the entry (or drops it if the on-disk
	       * serial is no longer cached). On failure it leaves it locked, so drop the placeholder. */
	      ret = xserial_get_next_value_internal (thread_p, result_num, oid_p, num_alloc, entry);
	      if (ret != NO_ERROR)
		{
		  if (!serial_Cache_hashmap.erase_locked (thread_p, key, entry) && entry != NULL)
		    {
		      pthread_mutex_unlock (&entry->mutex);
		    }
		}
	    }
	  else
	    {
	      /* Another thread initialized the entry first; reuse it. */
	      ret = serial_get_next_cached_value (thread_p, entry, num_alloc);
	      if (ret == NO_ERROR)
		{
		  pr_clone_value (&entry->cur_val, result_num);
		}
	      pthread_mutex_unlock (&entry->mutex);
	    }
	}
    }

  if (ret == NO_ERROR && is_auto_increment == GENERATE_AUTO_INCREMENT)
    {
      /* we update current insert id for this session here */
      /* Note that we ignore an error during updating current insert id. */
      (void) xsession_set_cur_insert_id (thread_p, result_num, force_set_last_insert_id);
    }

  return ret;
}

static int
serial_get_next_cached_value (THREAD_ENTRY * thread_p, SERIAL_CACHE_ENTRY * entry, int num_alloc)
{
  DB_VALUE cmp_result;
  DB_VALUE next_val;
  int error, nturns;
  bool exhausted = false;

  assert (1 <= num_alloc);

  db_make_null (&next_val);

  /* check if cached numbers were already exhausted */
  if (num_alloc == 1)
    {
      error = numeric_db_value_compare (&entry->cur_val, &entry->last_cached_val, &cmp_result);
      if (error != NO_ERROR)
	{
	  return error;
	}
      if (db_get_int (&cmp_result) == 0)
	{
	  /* entry is cached to number of cached_num */
	  exhausted = true;
	}
    }
  else
    {
      error =
	serial_get_nth_value (&entry->inc_val, &entry->cur_val, &entry->min_val, &entry->max_val, &entry->cyclic,
			      num_alloc, &next_val);
      if (error != NO_ERROR)
	{
	  return error;
	}

      error = numeric_db_value_compare (&next_val, &entry->last_cached_val, &cmp_result);
      if (error != NO_ERROR)
	{
	  return error;
	}

      if (db_get_int (&cmp_result) >= 0)
	{
	  exhausted = true;
	}

    }

  /* consumed all cached value */
  if (exhausted == true)
    {
      DB_VALUE new_last_cached_val;

      db_make_null (&new_last_cached_val);

      nturns = CEIL_PTVDIV (num_alloc, entry->cached_num);

      error =
	serial_reserve_block_end (&entry->inc_val, &entry->last_cached_val, &entry->min_val, &entry->max_val,
				  &entry->cyclic, (nturns * entry->cached_num), &new_last_cached_val);

      if (error != NO_ERROR)
	{
	  return error;
	}

      error = numeric_db_value_compare (&new_last_cached_val, &entry->last_cached_val, &cmp_result);
      if (error != NO_ERROR)
	{
	  return error;
	}

      /* A reservation clamped to the range boundary can reserve nothing new; leave the entry and
       * _db_serial alone then, because the value generation below raises the range overflow anyway
       * and a durable write per failing call buys nothing. */
      if (db_get_int (&cmp_result) != 0)
	{
	  pr_clone_value (&new_last_cached_val, &entry->last_cached_val);

	  /* cur_val of _db_serial is updated to last_cached_val of entry */
	  error = serial_update_cur_val_of_serial (thread_p, entry, num_alloc);
	  if (error != NO_ERROR)
	    {
	      return error;
	    }
	}
    }

  /* get next value */
  if (num_alloc == 1)
    {
      error =
	serial_get_nth_value (&entry->inc_val, &entry->cur_val, &entry->min_val, &entry->max_val, &entry->cyclic,
			      num_alloc, &next_val);
      if (error != NO_ERROR)
	{
	  return error;
	}
    }

  pr_clone_value (&next_val, &entry->cur_val);

  return NO_ERROR;
}

static int
serial_store_cur_val_of_serial (THREAD_ENTRY * thread_p, SERIAL_CACHE_ENTRY * entry, DB_VALUE * store_val,
				int num_alloc, bool log_supplemental)
{
  int ret = NO_ERROR;
  HEAP_SCANCACHE scan_cache;
  SCAN_CODE scan;
  RECDES recdesc = RECDES_INITIALIZER;
  HEAP_CACHE_ATTRINFO attr_info, *attr_info_p = NULL;
  DB_VALUE *val;
  DB_VALUE key_val;
  ATTR_ID attrid;
  OID serial_class_oid;

  db_make_null (&key_val);

  CHECK_MODIFICATION_NO_RETURN (thread_p, ret);
  if (ret != NO_ERROR)
    {
      return ret;
    }

  oid_get_serial_oid (&serial_class_oid);
  heap_scancache_quick_start_modify_with_class_oid (thread_p, &scan_cache, &serial_class_oid);

  /* record body is consumed through the attribute layer; record type is copied separately (CBRD-26847) */
  scan =
    heap_get_visible_version (thread_p, &entry->oid, &serial_class_oid, &recdesc, &scan_cache, PEEK, NULL_CHN,
			      HEAP_RECDES_DONT_CONSUME_RAW_BYTES);
  if (scan != S_SUCCESS)
    {
      if (er_errid () == ER_PB_BAD_PAGEID)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_UNKNOWN_OBJECT, 3, entry->oid.volid, entry->oid.pageid,
		  entry->oid.slotid);
	}
      else
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_CANNOT_FETCH_SERIAL, 0);
	}
      goto exit_on_error;
    }

  /* retrieve attribute */
  ret = heap_attrinfo_start (thread_p, oid_Serial_class_oid, -1, NULL, &attr_info);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  ret = heap_attrinfo_read_dbvalues (thread_p, &entry->oid, &recdesc, &attr_info);
  if (ret != NO_ERROR)
    {
      heap_attrinfo_end (thread_p, &attr_info);
      goto exit_on_error;
    }

  attr_info_p = &attr_info;

  if (serial_get_attrid (thread_p, SERIAL_ATTR_UNIQUE_NAME_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_clone_value (val, &key_val);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_CURRENT_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  ret = heap_attrinfo_set (&entry->oid, attrid, store_val, attr_info_p);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  ret =
    serial_update_serial_object (thread_p, scan_cache.page_watcher.pgptr, &recdesc, attr_info_p, oid_Serial_class_oid,
				 &entry->oid, &key_val);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  if (log_supplemental && prm_get_integer_value (PRM_ID_SUPPLEMENTAL_LOG) > 0 && thread_p->no_supplemental_log == false)
    {
      LOG_TDES *tdes = LOG_FIND_CURRENT_TDES (thread_p);

      if (tdes)
	{
	  if (!tdes->has_supplemental_log)
	    {
	      log_append_supplemental_info (thread_p, LOG_SUPPLEMENT_TRAN_USER, strlen (tdes->client.get_db_user ()),
					    tdes->client.get_db_user ());

	      tdes->has_supplemental_log = true;
	    }
	}

      (void) log_append_supplemental_serial (thread_p, db_get_string (&key_val), num_alloc, NULL, &entry->oid);
    }

  pr_clear_value (&key_val);

  heap_attrinfo_end (thread_p, attr_info_p);

  heap_scancache_end (thread_p, &scan_cache);

  return NO_ERROR;

exit_on_error:

  pr_clear_value (&key_val);

  if (attr_info_p != NULL)
    {
      heap_attrinfo_end (thread_p, attr_info_p);
    }

  heap_scancache_end (thread_p, &scan_cache);

  return (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
}

static int
serial_update_cur_val_of_serial (THREAD_ENTRY * thread_p, SERIAL_CACHE_ENTRY * entry, int num_alloc)
{
  return serial_store_cur_val_of_serial (thread_p, entry, &entry->last_cached_val, num_alloc, true);
}

static int
serial_flush_cur_val_of_serial (THREAD_ENTRY * thread_p, SERIAL_CACHE_ENTRY * entry)
{
  DB_VALUE durable_val;
  DB_VALUE cmp_result;
  int error;

  if (DB_IS_NULL (&entry->cur_val) || DB_IS_NULL (&entry->last_cached_val))
    {
      /* nothing was issued from this entry yet */
      return NO_ERROR;
    }

  error = numeric_db_value_compare (&entry->cur_val, &entry->last_cached_val, &cmp_result);
  if (error != NO_ERROR)
    {
      return error;
    }

  if (db_get_int (&cmp_result) == 0)
    {
      /* the block was consumed exactly; the durable value already matches */
      return NO_ERROR;
    }

  /* Only hand the tail back while the durable value is still the block end this entry reserved. A
   * reset/rebase DDL writes cur_val itself and owns it from then on; it decaches before it writes,
   * so the flush it triggers still runs here, while the block end is what is on disk. */
  db_make_null (&durable_val);
  if (xserial_get_current_value_internal (thread_p, &durable_val, &entry->oid) != NO_ERROR)
    {
      /* the row is gone (dropped serial); nothing to write back */
      er_clear ();
      return NO_ERROR;
    }

  error = numeric_db_value_compare (&durable_val, &entry->last_cached_val, &cmp_result);
  pr_clear_value (&durable_val);
  if (error != NO_ERROR)
    {
      return error;
    }

  if (db_get_int (&cmp_result) != 0)
    {
      return NO_ERROR;
    }

  return serial_store_cur_val_of_serial (thread_p, entry, &entry->cur_val, 0, false);
}

static void
serial_flush_entry_best_effort (THREAD_ENTRY * thread_p, SERIAL_CACHE_ENTRY * entry)
{
  if (serial_flush_cur_val_of_serial (thread_p, entry) != NO_ERROR)
    {
      er_log_debug (ARG_FILE_LINE,
		    "serial cache write-back failed for (%d|%d|%d); the unissued tail of its block is lost\n",
		    OID_AS_ARGS (&entry->oid));
      er_clear ();
    }
}

static int
xserial_get_next_value_internal (THREAD_ENTRY * thread_p, DB_VALUE * result_num, const OID * serial_oidp,
				 int num_alloc, SERIAL_CACHE_ENTRY * claimed_entry)
{
  int ret = NO_ERROR;
  HEAP_SCANCACHE scan_cache;
  SCAN_CODE scan;
  RECDES recdesc = RECDES_INITIALIZER;
  HEAP_CACHE_ATTRINFO attr_info, *attr_info_p = NULL;
  DB_VALUE *val = NULL;
  DB_VALUE cur_val;
  DB_VALUE inc_val;
  DB_VALUE max_val;
  DB_VALUE min_val;
  DB_VALUE cyclic;
  DB_VALUE started;
  DB_VALUE next_val;
  DB_VALUE key_val;
  DB_VALUE last_val;
  int cached_num, nturns;
  SERIAL_CACHE_ENTRY *entry = NULL;
  ATTR_ID attrid;
  OID serial_class_oid;

  bool is_started;

  db_make_null (&key_val);

  oid_get_serial_oid (&serial_class_oid);
  heap_scancache_quick_start_modify_with_class_oid (thread_p, &scan_cache, &serial_class_oid);

  /* record body is consumed through the attribute layer; record type is copied separately (CBRD-26847) */
  scan =
    heap_get_visible_version (thread_p, serial_oidp, &serial_class_oid, &recdesc, &scan_cache, PEEK, NULL_CHN,
			      HEAP_RECDES_DONT_CONSUME_RAW_BYTES);
  if (scan != S_SUCCESS)
    {
      if (er_errid () == ER_PB_BAD_PAGEID)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_UNKNOWN_OBJECT, 3, serial_oidp->volid, serial_oidp->pageid,
		  serial_oidp->slotid);
	}
      else
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_CANNOT_FETCH_SERIAL, 0);
	}
      goto exit_on_error;
    }

  /* retrieve attribute */
  ret = heap_attrinfo_start (thread_p, oid_Serial_class_oid, -1, NULL, &attr_info);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  attr_info_p = &attr_info;

  ret = heap_attrinfo_read_dbvalues (thread_p, serial_oidp, &recdesc, attr_info_p);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  if (serial_get_attrid (thread_p, SERIAL_ATTR_CACHED_NUM_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  if (attrid == NOT_FOUND)
    {
      cached_num = 0;
    }
  else
    {
      val = heap_attrinfo_access (attrid, attr_info_p);
      cached_num = db_get_int (val);
    }

  if (serial_get_attrid (thread_p, SERIAL_ATTR_UNIQUE_NAME_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_clone_value (val, &key_val);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_CURRENT_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_share_value (val, &cur_val);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_INCREMENT_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_share_value (val, &inc_val);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_MAX_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_share_value (val, &max_val);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_MIN_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_share_value (val, &min_val);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_CYCLIC_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_share_value (val, &cyclic);

  if (serial_get_attrid (thread_p, SERIAL_ATTR_STARTED_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  val = heap_attrinfo_access (attrid, attr_info_p);
  pr_share_value (val, &started);

  db_make_null (&last_val);

  is_started = db_get_int (&started);

  if (db_get_int (&started) == 0)
    {
      /* This is the first time to generate the serial value. */
      db_make_int (&started, 1);
      if (serial_get_attrid (thread_p, SERIAL_ATTR_STARTED_INDEX, attrid) != NO_ERROR)
	{
	  goto exit_on_error;
	}
      assert (attrid != NOT_FOUND);
      ret = heap_attrinfo_set (serial_oidp, attrid, &started, attr_info_p);
      if (ret == NO_ERROR)
	{
	  pr_share_value (&cur_val, &next_val);
	  if (cached_num > 1)
	    {
	      assert (1 <= num_alloc);
	      nturns = CEIL_PTVDIV (num_alloc, cached_num);

	      ret =
		serial_reserve_block_end (&inc_val, &cur_val, &min_val, &max_val, &cyclic,
					  (nturns * (cached_num - 1)), &last_val);
	    }

	  num_alloc--;
	}
    }

  if (num_alloc > 0)
    {
      if (cached_num > 1)
	{
	  nturns = CEIL_PTVDIV (num_alloc, cached_num);

	  ret =
	    serial_reserve_block_end (&inc_val, &cur_val, &min_val, &max_val, &cyclic, (nturns * cached_num),
				      &last_val);
	}

      if (ret == NO_ERROR)
	{
	  ret = serial_get_nth_value (&inc_val, &cur_val, &min_val, &max_val, &cyclic, num_alloc, &next_val);
	}
    }

  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  /* Now update record */
  if (serial_get_attrid (thread_p, SERIAL_ATTR_CURRENT_VAL_INDEX, attrid) != NO_ERROR)
    {
      goto exit_on_error;
    }
  assert (attrid != NOT_FOUND);
  if (cached_num > 1 && !DB_IS_NULL (&last_val))
    {
      ret = heap_attrinfo_set (serial_oidp, attrid, &last_val, attr_info_p);
    }
  else
    {
      ret = heap_attrinfo_set (serial_oidp, attrid, &next_val, attr_info_p);
    }
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  ret =
    serial_update_serial_object (thread_p, scan_cache.page_watcher.pgptr, &recdesc, attr_info_p, oid_Serial_class_oid,
				 serial_oidp, &key_val);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  if (prm_get_integer_value (PRM_ID_SUPPLEMENTAL_LOG) > 0 && thread_p->no_supplemental_log == false)
    {
      LOG_TDES *tdes = LOG_FIND_CURRENT_TDES (thread_p);

      if (tdes)
	{
	  if (!tdes->has_supplemental_log)
	    {
	      log_append_supplemental_info (thread_p, LOG_SUPPLEMENT_TRAN_USER, strlen (tdes->client.get_db_user ()),
					    tdes->client.get_db_user ());

	      tdes->has_supplemental_log = true;
	    }
	}

      (void) log_append_supplemental_serial (thread_p, db_get_string (&key_val), is_started ? num_alloc : num_alloc + 1,
					     NULL, serial_oidp);
    }

  /* copy result value */
  pr_share_value (&next_val, result_num);

  pr_clear_value (&key_val);

  heap_attrinfo_end (thread_p, attr_info_p);

  heap_scancache_end (thread_p, &scan_cache);

  if (claimed_entry != NULL)
    {
      /* Initializer's pre-claimed entry (owned here on success; caller cleans up only on error). */
      if (cached_num > 1)
	{
	  /* Fill and release it. */
	  pr_share_value (&next_val, &cur_val);
	  serial_set_cache_entry (claimed_entry, &inc_val, &cur_val, &min_val, &max_val, &started, &cyclic, &last_val,
				  cached_num);
	  pthread_mutex_unlock (&claimed_entry->mutex);
	}
      else
	{
	  /* On-disk serial is no longer cached (e.g. ALTER SERIAL ... NOCACHE after the plan compiled);
	   * drop the placeholder. erase_locked releases the mutex; on the rare mismatch, unlock it. */
	  OID key = *serial_oidp;
	  if (!serial_Cache_hashmap.erase_locked (thread_p, key, claimed_entry) && claimed_entry != NULL)
	    {
	      pthread_mutex_unlock (&claimed_entry->mutex);
	    }
	}
    }
  else if (cached_num > 1)
    {
      /* No pre-claimed entry (cached_num <= 1 plan whose on-disk cached_num was raised by
       * ALTER SERIAL ... CACHE). Install now; never overwrite an entry a concurrent thread won
       * -- that would reset a live cached counter and risk handing out duplicates. */
      OID key = *serial_oidp;
      bool inserted = serial_Cache_hashmap.find_or_insert (thread_p, key, entry);

      if (entry != NULL)
	{
	  if (inserted)
	    {
	      pr_share_value (&next_val, &cur_val);
	      serial_set_cache_entry (entry, &inc_val, &cur_val, &min_val, &max_val, &started, &cyclic, &last_val,
				      cached_num);
	    }
	  pthread_mutex_unlock (&entry->mutex);
	}
    }

  return NO_ERROR;

exit_on_error:

  pr_clear_value (&key_val);

  if (attr_info_p != NULL)
    {
      heap_attrinfo_end (thread_p, attr_info_p);
    }

  heap_scancache_end (thread_p, &scan_cache);

  return (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
}

static int
serial_update_serial_object (THREAD_ENTRY * thread_p, PAGE_PTR pgptr, RECDES * recdesc, HEAP_CACHE_ATTRINFO * attr_info,
			     const OID * serial_class_oidp, const OID * serial_oidp, DB_VALUE * key_val)
{
  // *INDENT-OFF*
  cubmem::stack_block<IO_MAX_PAGE_SIZE> copyarea;
  // *INDENT-ON*
  record_descriptor new_recdesc;
  SCAN_CODE scan;
  LOG_DATA_ADDR addr;
  int ret;
  int sp_success;
  int tran_index;
  LOCK lock_mode = NULL_LOCK;

  assert_release (serial_class_oidp != NULL && !OID_ISNULL (serial_class_oidp));

  tran_index = LOG_FIND_THREAD_TRAN_INDEX (thread_p);
  lock_mode = lock_get_object_lock (serial_oidp, serial_class_oidp);

  /* need to start topop for replication Replication will recognize and realize a special type of update for serial by
   * this top operation log record. If lock_mode is X_LOCK means we created or altered the serial obj in an
   * uncommitted trans For this case, topop and flush mark are not used, since these may cause problem with replication
   * log. */
  if (lock_mode != X_LOCK)
    {
      log_sysop_start (thread_p);
    }

  if (lock_mode != X_LOCK && !LOG_CHECK_LOG_APPLIER (thread_p) && log_does_allow_replication () == true)
    {
      repl_start_flush_mark (thread_p);
    }

  new_recdesc.set_external_buffer (copyarea);

  scan = heap_attrinfo_transform_to_disk (thread_p, attr_info, recdesc, &new_recdesc);
  if (scan != S_SUCCESS)
    {
      assert (false);
      goto exit_on_error;
    }

  /* Log the changes */
  new_recdesc.set_type (recdesc->type);
  addr.offset = serial_oidp->slotid;
  addr.pgptr = pgptr;

  assert (spage_is_updatable (thread_p, addr.pgptr, serial_oidp->slotid, (int) new_recdesc.get_size ()));

  log_append_redo_recdes (thread_p, RVHF_UPDATE, &addr, &new_recdesc.get_recdes ());

  /* Now really update */
  sp_success = spage_update (thread_p, addr.pgptr, serial_oidp->slotid, &new_recdesc.get_recdes ());
  if (sp_success != SP_SUCCESS)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_CANNOT_UPDATE_SERIAL, 0);
      goto exit_on_error;
    }

  /* make replication log for the special type of update for serial */
  if (!LOG_CHECK_LOG_APPLIER (thread_p) && log_does_allow_replication () == true)
    {
      repl_log_insert (thread_p, serial_class_oidp, serial_oidp, LOG_REPLICATION_DATA, RVREPL_DATA_UPDATE, key_val,
		       REPL_INFO_TYPE_RBR_NORMAL);
      repl_add_update_lsa (thread_p, serial_oidp);

      if (lock_mode != X_LOCK)
	{
	  repl_end_flush_mark (thread_p, false);
	}
    }

  if (lock_mode != X_LOCK)
    {
      log_sysop_commit (thread_p);
    }

  return NO_ERROR;

exit_on_error:

  if (lock_mode != X_LOCK)
    {
      log_sysop_abort (thread_p);
    }

  ASSERT_ERROR_AND_SET (ret);
  return ret;
}

static int
serial_get_nth_value (DB_VALUE * inc_val, DB_VALUE * cur_val, DB_VALUE * min_val, DB_VALUE * max_val, DB_VALUE * cyclic,
		      int nth, DB_VALUE * result_val)
{
  return serial_get_nth_value_internal (inc_val, cur_val, min_val, max_val, cyclic, nth, result_val, false);
}

static int
serial_reserve_block_end (DB_VALUE * inc_val, DB_VALUE * cur_val, DB_VALUE * min_val, DB_VALUE * max_val,
			  DB_VALUE * cyclic, int nth, DB_VALUE * result_val)
{
  return serial_get_nth_value_internal (inc_val, cur_val, min_val, max_val, cyclic, nth, result_val, true);
}

static int
serial_get_nth_value_internal (DB_VALUE * inc_val, DB_VALUE * cur_val, DB_VALUE * min_val, DB_VALUE * max_val,
			       DB_VALUE * cyclic, int nth, DB_VALUE * result_val, bool clamp_block)
{
  DB_VALUE tmp_val, cmp_result, add_val;
  unsigned char num[DB_NUMERIC_BUF_SIZE];
  int inc_val_flag;
  int ret;

  inc_val_flag = numeric_db_value_is_positive (inc_val);
  if (inc_val_flag < 0)
    {
      return ER_FAILED;
    }

  /* Now calculate next value */
  if (nth > 1)
    {
      numeric_coerce_int_to_num (nth, num, NULL);
      db_make_numeric (&tmp_val, num, DB_MAX_FIXED_NUMERIC_PRECISION, 0, DB_NUMERIC_BUF_SIZE, false, false);
      numeric_db_value_mul (inc_val, &tmp_val, &add_val);
      FLOAT_TO_FIXED_NUMERIC (&add_val);
    }
  else
    {
      pr_share_value (inc_val, &add_val);
    }

  /* inc_val_flag (1 or 0) */
  if (inc_val_flag > 0)
    {
      ret = numeric_db_value_sub (max_val, &add_val, &tmp_val);
      if (ret != NO_ERROR)
	{
	  return ret;
	}
      FLOAT_TO_FIXED_NUMERIC (&tmp_val);
      ret = numeric_db_value_compare (cur_val, &tmp_val, &cmp_result);
      if (ret != NO_ERROR)
	{
	  return ret;
	}

      /* cur_val + inc_val * cached_num > max_val */
      if (db_get_int (&cmp_result) > 0)
	{
	  if (db_get_int (cyclic))
	    {
	      pr_share_value (min_val, result_val);
	    }
	  else if (clamp_block)
	    {
	      /* Reserving a cache block would overshoot max_val; clamp it to the boundary so
	       * values up through max_val stay usable instead of failing early. */
	      pr_share_value (max_val, result_val);
	    }
	  else
	    {
	      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_SERIAL_RANGE_OVERFLOW, 0);
	      return ER_QPROC_SERIAL_RANGE_OVERFLOW;
	    }
	}
      else
	{
	  (void) numeric_db_value_add (cur_val, &add_val, result_val);
	  FLOAT_TO_FIXED_NUMERIC (result_val);
	}
    }
  else
    {
      ret = numeric_db_value_sub (min_val, &add_val, &tmp_val);
      if (ret != NO_ERROR)
	{
	  return ret;
	}
      FLOAT_TO_FIXED_NUMERIC (&tmp_val);
      ret = numeric_db_value_compare (cur_val, &tmp_val, &cmp_result);
      if (ret != NO_ERROR)
	{
	  return ret;
	}

      /* cur_val + inc_val * cached_num < min_val */
      if (db_get_int (&cmp_result) < 0)
	{
	  if (db_get_int (cyclic))
	    {
	      pr_share_value (max_val, result_val);
	    }
	  else if (clamp_block)
	    {
	      /* Reserving a cache block would undershoot min_val; clamp it to the boundary so
	       * values down through min_val stay usable instead of failing early. */
	      pr_share_value (min_val, result_val);
	    }
	  else
	    {
	      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_QPROC_SERIAL_RANGE_OVERFLOW, 0);
	      return ER_QPROC_SERIAL_RANGE_OVERFLOW;
	    }
	}
      else
	{
	  (void) numeric_db_value_add (cur_val, &add_val, result_val);
	  FLOAT_TO_FIXED_NUMERIC (result_val);
	}
    }

  return NO_ERROR;
}

int
serial_initialize_cache_pool (THREAD_ENTRY * thread_p, bool load_attr_info)
{
  unsigned int i;
  const int freelist_block_count = 2;
  const int freelist_block_size = NCACHE_OBJECTS / freelist_block_count;

  if (serial_Cache_initialized)
    {
      serial_finalize_cache_pool ();
    }

  if (!load_attr_info)
    {
      /* Without a client workspace the load swizzles the object-domain owner OID and divides by
       * the empty MOP table in ws_mop (SIGFPE). restoredb/restoreslave generate no serial values,
       * so the cache pool is not built either; a later normal boot initializes everything. */
      return NO_ERROR;
    }

  serial_Cache_hashmap.init (serial_Cache_Ts, THREAD_TS_SERIAL_CACHE, SERIAL_CACHE_HASH_SIZE, freelist_block_size,
			     freelist_block_count, serial_Cache_entry_descriptor);
  serial_Cache_initialized = true;

  for (i = 0; i < sizeof (serial_Attrs_id) / sizeof (ATTR_ID); i++)
    {
      serial_Attrs_id[i] = -1;
    }

  /* Load the _db_serial attribute layout once, now that the catalog is available. */
  return serial_load_attribute_info_of_db_serial (thread_p);
}

void
serial_flush_cache_pool (THREAD_ENTRY * thread_p)
{
  if (!serial_Cache_initialized)
    {
      return;
    }

  // *INDENT-OFF*
  serial_cache_hashmap_type::iterator it { thread_p, serial_Cache_hashmap };
  // *INDENT-ON*

  for (SERIAL_CACHE_ENTRY * entry = it.iterate (); entry != NULL; entry = it.iterate ())
    {
      serial_flush_entry_best_effort (thread_p, entry);
    }
}

void
serial_finalize_cache_pool (void)
{
  if (serial_Cache_initialized)
    {
      serial_Cache_hashmap.destroy ();
      serial_Cache_initialized = false;
    }

  serial_Num_attrs = -1;
  OID_SET_NULL (&db_serial_class_oid);
}

static int
serial_get_attrid (THREAD_ENTRY * thread_p, int attr_index, ATTR_ID &attrid)
{
  attrid = NOT_FOUND;

  /* serial_Attrs_id[] is read-only after boot, so no lock is needed here (see its declaration). */
  assert (serial_Num_attrs >= 0);
  if (attr_index >= 0 && attr_index <= serial_Num_attrs)
    {
      attrid = serial_Attrs_id[attr_index];
    }

  return NO_ERROR;
}

static int
serial_load_attribute_info_of_db_serial (THREAD_ENTRY * thread_p)
{
  HEAP_SCANCACHE scan;
  RECDES class_record;
  HEAP_CACHE_ATTRINFO attr_info;
  int i, error = NO_ERROR;
  char *attr_name_p, *string = NULL;
  int alloced_string = 0;

  serial_Num_attrs = -1;

  oid_get_serial_oid (&db_serial_class_oid);

  if (heap_scancache_quick_start_with_class_oid (thread_p, &scan, &db_serial_class_oid) != NO_ERROR)
    {
      return ER_FAILED;
    }
  if (heap_get_class_record (thread_p, &db_serial_class_oid, &class_record, &scan, PEEK) != S_SUCCESS)
    {
      heap_scancache_end (thread_p, &scan);
      return ER_FAILED;
    }

  error = heap_attrinfo_start (thread_p, &db_serial_class_oid, -1, NULL, &attr_info);
  if (error != NO_ERROR)
    {
      (void) heap_scancache_end (thread_p, &scan);
      return error;
    }

  for (i = 0; i < attr_info.num_values; i++)
    {
      string = NULL;
      alloced_string = 0;

      error = or_get_attrname (&class_record, i, &string, &alloced_string);
      if (error != NO_ERROR)
	{
	  ASSERT_ERROR ();
	  goto exit_on_error;
	}

      attr_name_p = string;
      if (attr_name_p == NULL)
	{
	  error = ER_FAILED;
	  goto exit_on_error;
	}

      if (strcmp (attr_name_p, SERIAL_ATTR_UNIQUE_NAME) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_UNIQUE_NAME_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_NAME) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_NAME_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_OWNER) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_OWNER_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_CURRENT_VAL) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_CURRENT_VAL_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_INCREMENT_VAL) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_INCREMENT_VAL_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_MAX_VAL) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_MAX_VAL_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_MIN_VAL) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_MIN_VAL_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_CYCLIC) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_CYCLIC_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_STARTED) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_STARTED_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_CLASS_NAME) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_CLASS_NAME_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_ATTR_NAME) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_ATTR_NAME_INDEX] = i;
	}
      else if (strcmp (attr_name_p, SERIAL_ATTR_CACHED_NUM) == 0)
	{
	  serial_Attrs_id[SERIAL_ATTR_CACHED_NUM_INDEX] = i;
	}

      if (string != NULL && alloced_string)
	{
	  db_private_free_and_init (NULL, string);
	}
    }

  serial_Num_attrs = attr_info.num_values;

  heap_attrinfo_end (thread_p, &attr_info);
  error = heap_scancache_end (thread_p, &scan);

  return error;

exit_on_error:

  heap_attrinfo_end (thread_p, &attr_info);
  (void) heap_scancache_end (thread_p, &scan);

  return error;
}

static void
serial_set_cache_entry (SERIAL_CACHE_ENTRY * entry, DB_VALUE * inc_val, DB_VALUE * cur_val, DB_VALUE * min_val,
			DB_VALUE * max_val, DB_VALUE * started, DB_VALUE * cyclic, DB_VALUE * last_val, int cached_num)
{
  pr_clone_value (cur_val, &entry->cur_val);
  pr_clone_value (inc_val, &entry->inc_val);
  pr_clone_value (max_val, &entry->max_val);
  pr_clone_value (min_val, &entry->min_val);
  pr_clone_value (cyclic, &entry->cyclic);
  pr_clone_value (last_val, &entry->last_cached_val);
  pr_clone_value (started, &entry->started);
  entry->cached_num = cached_num;
}

static void
serial_clear_value (SERIAL_CACHE_ENTRY * entry)
{
  pr_clear_value (&entry->cur_val);
  pr_clear_value (&entry->inc_val);
  pr_clear_value (&entry->max_val);
  pr_clear_value (&entry->min_val);
  pr_clear_value (&entry->cyclic);
  pr_clear_value (&entry->started);
  entry->cached_num = 0;
}

serial_entry::serial_entry ()
{
  pthread_mutex_init (&mutex, NULL);
}

serial_entry::~serial_entry ()
{
  pthread_mutex_destroy (&mutex);
}

static void *
serial_cache_entry_alloc (void)
{
  SERIAL_CACHE_ENTRY *entry = (SERIAL_CACHE_ENTRY *) malloc (sizeof (SERIAL_CACHE_ENTRY));
  if (entry == NULL)
    {
      return NULL;
    }
  pthread_mutex_init (&entry->mutex, NULL);
  return entry;
}

static int
serial_cache_entry_free (void *entry)
{
  pthread_mutex_destroy (&((SERIAL_CACHE_ENTRY *) entry)->mutex);
  free (entry);
  return NO_ERROR;
}

static int
serial_cache_entry_init (void *entry)
{
  SERIAL_CACHE_ENTRY *ent = (SERIAL_CACHE_ENTRY *) entry;

  db_make_null (&ent->cur_val);
  db_make_null (&ent->inc_val);
  db_make_null (&ent->max_val);
  db_make_null (&ent->min_val);
  db_make_null (&ent->cyclic);
  db_make_null (&ent->started);
  db_make_null (&ent->last_cached_val);
  ent->cached_num = 0;
  return NO_ERROR;
}

static int
serial_cache_entry_uninit (void *entry)
{
  SERIAL_CACHE_ENTRY *ent = (SERIAL_CACHE_ENTRY *) entry;

  serial_clear_value (ent);
  pr_clear_value (&ent->last_cached_val);
  return NO_ERROR;
}

static int
serial_cache_entry_key_copy (void *src, void *dest)
{
  COPY_OID ((OID *) dest, (OID *) src);
  return NO_ERROR;
}

static int
serial_cache_entry_key_compare (void *key1, void *key2)
{
  return oid_compare (key1, key2);
}

static unsigned int
serial_cache_entry_key_hash (void *key, int htsize)
{
  return oid_hash (key, (unsigned int) htsize);
}

void
xserial_decache (THREAD_ENTRY * thread_p, OID * oidp)
{
  xcache_remove_by_oid (thread_p, oidp);

  if (serial_Cache_initialized)
    {
      OID key = *oidp;
      SERIAL_CACHE_ENTRY *entry = serial_Cache_hashmap.find (thread_p, key);

      if (entry != NULL)
	{
	  /* Hand the unissued tail back before losing the entry, so the next block resumes at the
	   * last value actually issued instead of past the block end. */
	  serial_flush_entry_best_effort (thread_p, entry);

	  if (!serial_Cache_hashmap.erase_locked (thread_p, key, entry) && entry != NULL)
	    {
	      pthread_mutex_unlock (&entry->mutex);
	    }
	}
    }
}

int
serial_cache_index_btid (THREAD_ENTRY * thread_p)
{
  int error_code = NO_ERROR;
  OID serial_oid = OID_INITIALIZER;

  /* Get serial class OID. */
  oid_get_serial_oid (&serial_oid);
  assert (!OID_ISNULL (&serial_oid));

  /* Now try to get index BTID. */
  error_code = heap_get_btid_from_index_name (thread_p, &serial_oid, "pk_db_serial_unique_name", &serial_Cached_btid);
  if (error_code != NO_ERROR)
    {
      ASSERT_ERROR ();
      return error_code;
    }
  /* Safe guard: successfully read a non-NULL BTID. */
  assert (!BTID_IS_NULL (&serial_Cached_btid));
  return NO_ERROR;
}

void
serial_get_index_btid (BTID * output)
{
  /* Safe guard: a non-NULL serial index BTID is cached. */
  assert (!BTID_IS_NULL (&serial_Cached_btid));
  /* Safe guard: output parameter for index BTID is not NULL. */
  assert (output != NULL);

  BTID_COPY (output, &serial_Cached_btid);
}

static bool
is_class (OID * obj_oid, OID * class_oid)
{
  if (OID_EQ (class_oid, oid_Root_class_oid))
    {
      return true;
    }
  return false;
}

static int
process_value (THREAD_ENTRY * thread_p, DB_VALUE * value)
{
  int return_value = 0;
  SCAN_CODE scan_code;

  switch (DB_VALUE_TYPE (value))
    {
    case DB_TYPE_OID:
      {
	OID *ref_oid;
	OID ref_class_oid;
	HEAP_SCANCACHE scan_cache;

	ref_oid = db_get_oid (value);

	if (OID_ISNULL (ref_oid))
	  {
	    break;
	  }

	heap_scancache_quick_start (&scan_cache);
	scan_cache.mvcc_snapshot = logtb_get_mvcc_snapshot (thread_p);
	/* existence/class probe: recdes is NULL, so no record body is consumed (CBRD-26847) */
	scan_code =
	  heap_get_visible_version (thread_p, ref_oid, &ref_class_oid, NULL, &scan_cache, PEEK, NULL_CHN,
				    HEAP_RECDES_DONT_CONSUME_RAW_BYTES);
	heap_scancache_end (thread_p, &scan_cache);

	if (scan_code == S_ERROR)
	  {
	    ASSERT_ERROR_AND_SET (return_value);
	    break;
	  }
	else if (scan_code != S_SUCCESS)
	  {
	    OID_SET_NULL (ref_oid);
	    return_value = 1;
	    break;
	  }

	if (is_class (ref_oid, &ref_class_oid))
	  {
	    break;
	  }

#if defined(CUBRID_DEBUG)
	printf (msgcat_message (MSGCAT_CATALOG_UTILS, MSGCAT_UTIL_SET_COMPACTDB, COMPACTDB_MSG_REFOID), ref_oid->volid,
		ref_oid->pageid, ref_oid->slotid, ref_class_oid.volid, ref_class_oid.pageid, ref_class_oid.slotid);
#endif

	break;
      }

    case DB_TYPE_POINTER:
    case DB_TYPE_SET:
    case DB_TYPE_MULTISET:
    case DB_TYPE_SEQUENCE:
      {
	return_value = process_set (thread_p, db_get_set (value));
	break;
      }

    default:
      break;
    }

  return return_value;
}

static int
process_set (THREAD_ENTRY * thread_p, DB_SET * set)
{
  SET_ITERATOR *it;
  DB_VALUE *element_value;
  int return_value = 0;
  int error_code;

  it = set_iterate (set);
  while ((element_value = set_iterator_value (it)) != NULL)
    {
      error_code = process_value (thread_p, element_value);
      if (error_code > 0)
	{
	  return_value += error_code;
	}
      else if (error_code != NO_ERROR)
	{
	  set_iterator_free (it);
	  return error_code;
	}
      set_iterator_next (it);
    }
  set_iterator_free (it);

  return return_value;
}

static int
process_object (THREAD_ENTRY * thread_p, HEAP_SCANCACHE * upd_scancache, HEAP_CACHE_ATTRINFO * attr_info, OID * oid)
{
  int i, result = 0;
  HEAP_ATTRVALUE *value = NULL;
  int force_count = 0, updated_n_attrs_id = 0;
  int *atts_id = NULL;
  int error_code;
  SCAN_CODE scan_code;
  RECDES copy_recdes;

  if (upd_scancache == NULL || attr_info == NULL || oid == NULL)
    {
      return -1;
    }

  copy_recdes.data = NULL;

  /* get object with X_LOCK */
  scan_code = locator_lock_and_get_object (thread_p, oid, &upd_scancache->node.class_oid, &copy_recdes, upd_scancache,
					   X_LOCK, COPY, NULL_CHN, LOG_WARNING_IF_DELETED,
					   HEAP_RECDES_DONT_CONSUME_RAW_BYTES);
  if (scan_code != S_SUCCESS)
    {
      if (er_errid () == ER_HEAP_UNKNOWN_OBJECT)
	{
	  assert (scan_code == S_DOESNT_EXIST || scan_code == S_SNAPSHOT_NOT_SATISFIED);
	  er_clear ();
	}

      if (scan_code == S_DOESNT_EXIST || scan_code == S_SNAPSHOT_NOT_SATISFIED)
	{
	  return 0;
	}

      return -1;
    }

  atts_id = (int *) db_private_alloc (thread_p, attr_info->num_values * sizeof (int));
  if (atts_id == NULL)
    {
      return -1;
    }

  for (i = 0, value = attr_info->values; i < attr_info->num_values; i++, value++)
    {
      error_code = process_value (thread_p, &value->dbvalue);
      if (error_code > 0)
	{
	  value->state = HEAP_WRITTEN_ATTRVALUE;
	  atts_id[updated_n_attrs_id] = value->attrid;
	  updated_n_attrs_id++;
	}
      else if (error_code != NO_ERROR)
	{
	  db_private_free (thread_p, atts_id);
	  return error_code;
	}
    }

  if ((updated_n_attrs_id > 0)
      || (attr_info->read_classrepr != NULL && attr_info->last_classrepr != NULL
	  && attr_info->read_classrepr->id != attr_info->last_classrepr->id))
    {
      /* oid already locked at locator_lock_and_get_object */
      error_code =
	locator_attribute_info_force (thread_p, &upd_scancache->node.hfid, oid, attr_info, atts_id, updated_n_attrs_id,
				      LC_FLUSH_UPDATE, SINGLE_ROW_UPDATE, upd_scancache, &force_count, false,
				      REPL_INFO_TYPE_RBR_NORMAL, DB_NOT_PARTITIONED_CLASS, NULL, NULL, NULL,
				      UPDATE_INPLACE_NONE, &copy_recdes, false);
      if (error_code != NO_ERROR)
	{
	  if (error_code == ER_MVCC_NOT_SATISFIED_REEVALUATION)
	    {
	      result = 0;
	    }
	  else
	    {
	      result = -1;
	    }
	}
      else
	{
	  result = 1;
	}
    }

  if (atts_id)
    {
      db_private_free (thread_p, atts_id);
      atts_id = NULL;
    }

  return result;
}

static int
desc_disk_to_attr_info (THREAD_ENTRY * thread_p, OID * oid, RECDES * recdes, HEAP_CACHE_ATTRINFO * attr_info)
{
  if (oid == NULL || recdes == NULL || attr_info == NULL)
    {
      return ER_FAILED;
    }

  if (heap_attrinfo_clear_dbvalues (attr_info) != NO_ERROR)
    {
      return ER_FAILED;
    }

  if (heap_attrinfo_read_dbvalues (thread_p, oid, recdes, attr_info) != NO_ERROR)
    {
      return ER_FAILED;
    }

  return NO_ERROR;
}

static int
process_class (THREAD_ENTRY * thread_p, OID * class_oid, HFID * hfid, int max_space_to_process,
	       int *instance_lock_timeout, int *space_to_process, OID * last_processed_oid, int *total_objects,
	       int *failed_objects, int *modified_objects, int *big_objects)
{
  int nobjects, nfetched, i, j;
  OID last_oid, prev_oid;
  LOCK null_lock = NULL_LOCK;
  LOCK oid_lock = X_LOCK;
  LC_COPYAREA *fetch_area = NULL;	/* Area where objects are received */
  struct lc_copyarea_manyobjs *mobjs;	/* Describe multiple objects in area */
  struct lc_copyarea_oneobj *obj;	/* Describe on object in area */
  RECDES recdes;
  HEAP_CACHE_ATTRINFO attr_info;
  HEAP_SCANCACHE upd_scancache;
  int ret = NO_ERROR, object_processed;
  MVCC_SNAPSHOT *mvcc_snapshot = NULL;

  int nfailed_instances = 0;

  if (class_oid == NULL || hfid == NULL || space_to_process == NULL || *space_to_process <= 0
      || *space_to_process > max_space_to_process || last_processed_oid == NULL || total_objects == NULL
      || failed_objects == NULL || modified_objects == NULL || big_objects == NULL || *total_objects < 0
      || *failed_objects < 0)
    {
      return ER_FAILED;
    }

  if (!OID_IS_ROOTOID (class_oid))
    {
      mvcc_snapshot = logtb_get_mvcc_snapshot (thread_p);
      if (mvcc_snapshot == NULL)
	{
	  return ER_FAILED;
	}
    }

  nobjects = 0;
  nfetched = -1;

  ret = heap_scancache_start_modify (thread_p, &upd_scancache, hfid, class_oid, SINGLE_ROW_UPDATE, NULL);
  if (ret != NO_ERROR)
    {
      return ER_FAILED;
    }

  ret = heap_attrinfo_start (thread_p, class_oid, -1, NULL, &attr_info);
  if (ret != NO_ERROR)
    {
      heap_scancache_end_modify (thread_p, &upd_scancache);
      return ER_FAILED;
    }

  COPY_OID (&last_oid, last_processed_oid);
  COPY_OID (&prev_oid, last_processed_oid);

  while (nobjects != nfetched)
    {
      ret =
	xlocator_lock_and_fetch_all (thread_p, hfid, &oid_lock, instance_lock_timeout, class_oid, &null_lock, &nobjects,
				     &nfetched, &nfailed_instances, &last_oid, &fetch_area, mvcc_snapshot);

      if (ret == NO_ERROR)
	{
	  (*total_objects) += nfailed_instances;
	  (*failed_objects) += nfailed_instances;

	  if (fetch_area != NULL)
	    {
	      mobjs = LC_MANYOBJS_PTR_IN_COPYAREA (fetch_area);
	      obj = LC_START_ONEOBJ_PTR_IN_COPYAREA (mobjs);

	      for (i = 0; i < mobjs->num_objs; i++)
		{
		  if (obj->length > *space_to_process)
		    {
		      if (*space_to_process == max_space_to_process)
			{
			  (*total_objects)++;
			  (*big_objects)++;
			  lock_unlock_object (thread_p, &obj->oid, class_oid, oid_lock, true);
			}
		      else
			{
			  *space_to_process = 0;
			  COPY_OID (last_processed_oid, &prev_oid);

			  for (j = i; j < mobjs->num_objs; j++)
			    {
			      lock_unlock_object (thread_p, &obj->oid, class_oid, oid_lock, true);
			      obj = LC_NEXT_ONEOBJ_PTR_IN_COPYAREA (obj);
			    }

			  if (fetch_area)
			    {
			      locator_free_copy_area (fetch_area);
			    }
			  goto end;
			}
		    }
		  else
		    {
		      *space_to_process -= obj->length;

		      (*total_objects)++;
		      LC_RECDES_TO_GET_ONEOBJ (fetch_area, obj, &recdes);

		      if (desc_disk_to_attr_info (thread_p, &obj->oid, &recdes, &attr_info) == NO_ERROR)
			{
			  object_processed = process_object (thread_p, &upd_scancache, &attr_info, &obj->oid);

			  if (object_processed != 1)
			    {
			      lock_unlock_object (thread_p, &obj->oid, class_oid, oid_lock, true);

			      if (object_processed == -1)
				{
				  (*failed_objects)++;
				}
			    }
			  else
			    {
			      (*modified_objects)++;
			    }
			}
		      else
			{
			  (*failed_objects)++;
			}
		    }

		  COPY_OID (&prev_oid, &obj->oid);
		  obj = LC_NEXT_ONEOBJ_PTR_IN_COPYAREA (obj);
		}

	      if (fetch_area)
		{
		  locator_free_copy_area (fetch_area);
		}
	    }
	  else
	    {
	      /* No more objects */
	      break;
	    }
	}
      else
	{
	  ret = ER_FAILED;
	  break;
	}
    }

  COPY_OID (last_processed_oid, &last_oid);

end:

  heap_attrinfo_end (thread_p, &attr_info);
  heap_scancache_end_modify (thread_p, &upd_scancache);

  return ret;
}

int
boot_compact_db (THREAD_ENTRY * thread_p, OID * class_oids, int n_classes, int space_to_process,
		 int instance_lock_timeout, int class_lock_timeout, bool delete_old_repr,
		 OID * last_processed_class_oid, OID * last_processed_oid, int *total_objects, int *failed_objects,
		 int *modified_objects, int *big_objects, int *initial_last_repr_id)
{
  int result = NO_ERROR;
  int i, j, start_index = -1;
  int max_space_to_process;
  int lock_ret;
  HFID hfid;

  if (boot_can_compact (thread_p) == false)
    {
      return ER_COMPACTDB_ALREADY_STARTED;
    }

  if (class_oids == NULL || n_classes <= 0 || space_to_process <= 0 || last_processed_class_oid == NULL
      || last_processed_oid == NULL || total_objects == NULL || failed_objects == NULL || modified_objects == NULL
      || big_objects == NULL || initial_last_repr_id == NULL)
    {
      return ER_QPROC_INVALID_PARAMETER;
    }

  for (start_index = 0; start_index < n_classes; start_index++)
    {
      if (OID_EQ (class_oids + start_index, last_processed_class_oid))
	{
	  break;
	}
    }

  if (start_index == n_classes)
    {
      return ER_QPROC_INVALID_PARAMETER;
    }

  for (i = 0; i < n_classes; i++)
    {
      total_objects[i] = 0;
      failed_objects[i] = 0;
      modified_objects[i] = 0;
      big_objects[i] = 0;
    }

  max_space_to_process = space_to_process;
  for (i = start_index; i < n_classes; i++)
    {
      lock_ret =
	lock_object_wait_msecs (thread_p, class_oids + i, oid_Root_class_oid, IX_LOCK, LK_UNCOND_LOCK,
				class_lock_timeout);

      if (lock_ret != LK_GRANTED)
	{
	  total_objects[i] = COMPACTDB_LOCKED_CLASS;
	  OID_SET_NULL (last_processed_oid);
	  continue;
	}

      if (heap_get_class_info (thread_p, class_oids + i, &hfid, NULL, NULL) != NO_ERROR)
	{
	  lock_unlock_object (thread_p, class_oids + i, oid_Root_class_oid, IX_LOCK, true);
	  OID_SET_NULL (last_processed_oid);
	  total_objects[i] = COMPACTDB_INVALID_CLASS;
	  continue;
	}

      if (HFID_IS_NULL (&hfid))
	{
	  lock_unlock_object (thread_p, class_oids + i, oid_Root_class_oid, IX_LOCK, true);
	  OID_SET_NULL (last_processed_oid);
	  total_objects[i] = COMPACTDB_INVALID_CLASS;
	  continue;
	}

      if (OID_ISNULL (last_processed_oid))
	{
	  initial_last_repr_id[i] = heap_get_class_repr_id (thread_p, class_oids + i);
	  if (initial_last_repr_id[i] <= 0)
	    {
	      lock_unlock_object (thread_p, class_oids + i, oid_Root_class_oid, IX_LOCK, true);
	      total_objects[i] = COMPACTDB_INVALID_CLASS;
	      continue;
	    }
	}

      if (process_class
	  (thread_p, class_oids + i, &hfid, max_space_to_process, &instance_lock_timeout, &space_to_process,
	   last_processed_oid, total_objects + i, failed_objects + i, modified_objects + i,
	   big_objects + i) != NO_ERROR)
	{
	  OID_SET_NULL (last_processed_oid);
	  for (j = start_index; j <= i; j++)
	    {
	      total_objects[j] = COMPACTDB_UNPROCESSED_CLASS;
	      failed_objects[j] = 0;
	      modified_objects[j] = 0;
	      big_objects[j] = 0;
	    }

	  result = ER_FAILED;
	  break;
	}

      if (delete_old_repr && OID_ISNULL (last_processed_oid) && failed_objects[i] == 0
	  && heap_get_class_repr_id (thread_p, class_oids + i) == initial_last_repr_id[i])
	{
	  lock_ret =
	    lock_object_wait_msecs (thread_p, class_oids + i, oid_Root_class_oid, X_LOCK, LK_UNCOND_LOCK,
				    class_lock_timeout);
	  if (lock_ret == LK_GRANTED)
	    {
	      if (catalog_drop_old_representations (thread_p, class_oids + i) != NO_ERROR)
		{
		  for (j = start_index; j <= i; j++)
		    {
		      total_objects[j] = COMPACTDB_UNPROCESSED_CLASS;
		      failed_objects[j] = 0;
		      modified_objects[j] = 0;
		      big_objects[j] = 0;
		    }

		  result = ER_FAILED;
		}
	      else
		{
		  initial_last_repr_id[i] = COMPACTDB_REPR_DELETED;
		}

	      break;
	    }
	}

      if (space_to_process == 0)
	{
	  break;
	}
    }

  if (OID_ISNULL (last_processed_oid))
    {
      if (i < n_classes - 1)
	{
	  COPY_OID (last_processed_class_oid, class_oids + i + 1);
	}
      else
	{
	  OID_SET_NULL (last_processed_class_oid);
	}
    }
  else
    {
      COPY_OID (last_processed_class_oid, class_oids + i);
    }

  return result;
}

int
boot_heap_compact_pages (THREAD_ENTRY * thread_p, OID * class_oid)
{
  if (boot_can_compact (thread_p) == false)
    {
      return ER_COMPACTDB_ALREADY_STARTED;
    }

  return heap_compact_pages (thread_p, class_oid);
}

int
boot_compact_start (THREAD_ENTRY * thread_p)
{
  int current_tran_index = -1;

  if (csect_enter (thread_p, CSECT_COMPACTDB_ONE_INSTANCE, INF_WAIT) != NO_ERROR)
    {
      return ER_FAILED;
    }

  current_tran_index = LOG_FIND_THREAD_TRAN_INDEX (thread_p);
  if (current_tran_index != last_tran_index && compact_started == true)
    {
      csect_exit (thread_p, CSECT_COMPACTDB_ONE_INSTANCE);
      return ER_COMPACTDB_ALREADY_STARTED;
    }

  last_tran_index = current_tran_index;
  compact_started = true;

  csect_exit (thread_p, CSECT_COMPACTDB_ONE_INSTANCE);

  return NO_ERROR;
}

int
boot_compact_stop (THREAD_ENTRY * thread_p)
{
  int current_tran_index = -1;

  if (csect_enter (thread_p, CSECT_COMPACTDB_ONE_INSTANCE, INF_WAIT) != NO_ERROR)
    {
      return ER_FAILED;
    }

  current_tran_index = LOG_FIND_THREAD_TRAN_INDEX (thread_p);
  if (current_tran_index != last_tran_index && compact_started == true)
    {
      csect_exit (thread_p, CSECT_COMPACTDB_ONE_INSTANCE);
      return ER_FAILED;
    }

  last_tran_index = -1;
  compact_started = false;

  csect_exit (thread_p, CSECT_COMPACTDB_ONE_INSTANCE);

  return NO_ERROR;
}

bool
boot_can_compact (THREAD_ENTRY * thread_p)
{
  int current_tran_index = -1;
  if (csect_enter (thread_p, CSECT_COMPACTDB_ONE_INSTANCE, INF_WAIT) != NO_ERROR)
    {
      return false;
    }

  current_tran_index = LOG_FIND_THREAD_TRAN_INDEX (thread_p);
  if (current_tran_index != last_tran_index && compact_started == true)
    {
      csect_exit (thread_p, CSECT_COMPACTDB_ONE_INSTANCE);
      return false;
    }

  csect_exit (thread_p, CSECT_COMPACTDB_ONE_INSTANCE);

  return true;
}

static PAGE_PTR
heap_scan_pb_latch_and_fetch_debug (THREAD_ENTRY * thread_p, const VPID * vpid_ptr, PAGE_FETCH_MODE fetch_mode,
				    PGBUF_LATCH_MODE latch_mode, HEAP_SCANCACHE * scan_cache,
				    PGBUF_WATCHER * pg_watcher, const char *caller_file, const int caller_line,
				    const char *caller_func)
#endif				/* !NDEBUG */
{
  PAGE_PTR pgptr = NULL;
  PGBUF_LATCH_MODE page_latch_mode;

  assert (latch_mode == PGBUF_LATCH_READ || latch_mode == PGBUF_LATCH_WRITE);
  /* A live scan cache always records a real per-page latch intent (READ or WRITE).
   * PGBUF_LATCH_INVALID only appears before start / after end, and must not reach here. */
  assert (scan_cache == NULL
	  || scan_cache->page_latch == PGBUF_LATCH_READ || scan_cache->page_latch == PGBUF_LATCH_WRITE);

  /* A scan cache with a WRITE intent escalates every page latch to WRITE. */
  page_latch_mode = latch_mode;
  if (scan_cache != NULL && scan_cache->page_latch == PGBUF_LATCH_WRITE)
    {
      page_latch_mode = PGBUF_LATCH_WRITE;
    }

  if (pg_watcher != NULL)
    {
#if defined (NDEBUG)
      if (pgbuf_ordered_fix_release (thread_p, vpid_ptr, fetch_mode, page_latch_mode, pg_watcher) != NO_ERROR)
#else /* !NDEBUG */
      if (pgbuf_ordered_fix_debug (thread_p, vpid_ptr, fetch_mode, page_latch_mode, pg_watcher,
				   caller_file, caller_line, caller_func) != NO_ERROR)
#endif /* !NDEBUG */
	{
	  return NULL;
	}
      pgptr = pg_watcher->pgptr;
    }
  else
    {
#if defined (NDEBUG)
      pgptr = pgbuf_fix_release (thread_p, vpid_ptr, fetch_mode, page_latch_mode, PGBUF_UNCONDITIONAL_LATCH);
#else /* !NDEBUG */
      pgptr =
	pgbuf_fix_debug (thread_p, vpid_ptr, fetch_mode, page_latch_mode, PGBUF_UNCONDITIONAL_LATCH, caller_file,
			 caller_line, caller_func);
#endif /* !NDEBUG */
    }

#if !defined (NDEBUG)
  if (pgptr != NULL)
    {
      (void) pgbuf_check_page_ptype (thread_p, pgptr, PAGE_HEAP);
    }
#endif /* !NDEBUG */

  return pgptr;
}

