static int
heap_attrinfo_check (const OID * inst_oid, HEAP_CACHE_ATTRINFO * attr_info)
{
  int ret = NO_ERROR;

  if (inst_oid != NULL)
    {
      /*
       * The OIDs must be equal
       */
      if (!OID_EQ (&attr_info->inst_oid, inst_oid))
	{
	  if (!OID_ISNULL (&attr_info->inst_oid))
	    {
	      ret = ER_HEAP_WRONG_ATTRINFO;
	      er_set (ER_FATAL_ERROR_SEVERITY, ARG_FILE_LINE, ret, 6, attr_info->inst_oid.volid,
		      attr_info->inst_oid.pageid, attr_info->inst_oid.slotid, inst_oid->volid, inst_oid->pageid,
		      inst_oid->slotid);
	      goto exit_on_error;
	    }

	  attr_info->inst_oid = *inst_oid;
	}
    }
  else
    {
      if (!OID_ISNULL (&attr_info->inst_oid))
	{
	  ret = ER_HEAP_WRONG_ATTRINFO;
	  er_set (ER_FATAL_ERROR_SEVERITY, ARG_FILE_LINE, ret, 6, attr_info->inst_oid.volid,
		  attr_info->inst_oid.pageid, attr_info->inst_oid.slotid, NULL_VOLID, NULL_PAGEID, NULL_SLOTID);
	  goto exit_on_error;
	}
    }

  return ret;

exit_on_error:

  return (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
}

int
heap_attrinfo_set (const OID * inst_oid, ATTR_ID attrid, DB_VALUE * attr_val, HEAP_CACHE_ATTRINFO * attr_info)
{
  HEAP_ATTRVALUE *value;	/* Disk value Attr info for a particular attr */
  const PR_TYPE *pr_type;	/* Primitive type array function structure */
  TP_DOMAIN_STATUS dom_status;
  int ret = NO_ERROR;

  /*
   * check to make sure the attr_info has been used, should never be empty.
   */

  if (attr_info->num_values == -1)
    {
      return ER_FAILED;
    }

  ret = heap_attrinfo_check (inst_oid, attr_info);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  value = heap_attrvalue_locate (attrid, attr_info);
  if (value == NULL)
    {
      goto exit_on_error;
    }

  pr_type = pr_type_from_id (value->last_attrepr->type);
  if (pr_type == NULL)
    {
      goto exit_on_error;
    }

  ret = pr_clear_value (&value->dbvalue);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  ret =
    db_value_domain_init (&value->dbvalue, value->last_attrepr->type, value->last_attrepr->domain->precision,
			  value->last_attrepr->domain->scale);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  /*
   * As we use "writeval" to do the writing and that function gets
   * enough domain information, we can use non-exact domain matching
   * here to defer the coercion until it is written.
   */
  dom_status = tp_domain_check (value->last_attrepr->domain, attr_val, TP_EXACT_MATCH);
  if (dom_status == DOMAIN_COMPATIBLE)
    {
      /*
       * the domains match exactly, set the value and proceed.  Copy
       * the source only if it's a set-valued thing (that's the purpose
       * of the third argument).
       */
      ret = pr_type->setval (&value->dbvalue, attr_val, TP_IS_SET_TYPE (pr_type->id));
    }
  else
    {
      /* the domains don't match, must attempt coercion */
      dom_status = tp_value_auto_cast_with_precision_check (attr_val, &value->dbvalue, value->last_attrepr->domain);

      if (dom_status != DOMAIN_COMPATIBLE)
	{
	  ret = tp_domain_status_er_set (dom_status, ARG_FILE_LINE, attr_val, value->last_attrepr->domain);
	  assert (er_errid () != NO_ERROR);

	  db_make_null (&value->dbvalue);
	}
    }

  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  value->state = HEAP_WRITTEN_ATTRVALUE;

  return ret;

exit_on_error:

  return (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
}

int
heap_attrinfo_get_effective_key (THREAD_ENTRY * thread_p, HEAP_CACHE_ATTRINFO * attr_info, ATTR_ID attrid,
				 RECDES * old_recdes, DB_VALUE * key)
{
  HEAP_ATTRVALUE *value;
  HEAP_ATTRVALUE omitted;
  DB_VALUE prepared;
  const PR_TYPE *pr_type;
  OR_BUF buf;
  char scratch[64 + MAX_ALIGNMENT];
  char *data = PTR_ALIGN (scratch, MAX_ALIGNMENT);
  char *allocated = NULL;
  int length;
  int error = NO_ERROR;

  assert (DB_IS_NULL (key));
  db_make_null (&prepared);
  value = heap_attrvalue_locate (attrid, attr_info);
  if (value == NULL)
    {
      return er_errid () != NO_ERROR ? er_errid () : ER_FAILED;
    }
  if (value->state == HEAP_UNINIT_ATTRVALUE && old_recdes != NULL && old_recdes->data != NULL)
    {
      HEAP_CACHE_ATTRINFO old_key;

      error = heap_attrinfo_start (thread_p, &attr_info->class_oid, 1, &attrid, &old_key);
      if (error != NO_ERROR)
	{
	  goto cleanup;
	}
      error = heap_attrinfo_read_dbvalues_without_oid (thread_p, old_recdes, &old_key);
      if (error == NO_ERROR)
	{
	  error = pr_clone_value (&old_key.values[0].dbvalue, &prepared);
	}
      heap_attrinfo_end (thread_p, &old_key);
    }
  else if (value->state == HEAP_UNINIT_ATTRVALUE)
    {
      omitted = *value;
      db_make_null (&omitted.dbvalue);
      error = heap_attrvalue_read (NULL, &omitted, attr_info);
      if (error == NO_ERROR)
	{
	  error = pr_clone_value (&omitted.dbvalue, &prepared);
	}
      pr_clear_value (&omitted.dbvalue);
    }
  else
    {
      error = pr_clone_value (&value->dbvalue, &prepared);
    }
  if (error != NO_ERROR)
    {
      goto cleanup;
    }
  if (value->do_increment != 0)
    {
      error = qdata_increment_dbval (&prepared, &prepared, value->do_increment);
      if (error != NO_ERROR)
	{
	  goto cleanup;
	}
    }
  if (DB_IS_NULL (&prepared))
    {
      error = pr_clone_value (&prepared, key);
      goto cleanup;
    }

  pr_type = value->last_attrepr->domain->type;
  length = pr_type->get_disk_size_of_value (&prepared);
  if (length <= 0)
    {
      error = er_errid () != NO_ERROR ? er_errid () : ER_FAILED;
      goto cleanup;
    }
  if (length > 64)
    {
      allocated = (char *) db_private_alloc (thread_p, length);
      if (allocated == NULL)
	{
	  error = ER_OUT_OF_VIRTUAL_MEMORY;
	  goto cleanup;
	}
      data = allocated;
    }
  or_init (&buf, data, length);
  error = pr_type->data_writeval (&buf, &prepared);
  if (error == NO_ERROR)
    {
      length = CAST_BUFLEN (buf.ptr - data);
      or_init (&buf, data, length);
      error = pr_type->data_readval (&buf, key, value->last_attrepr->domain, length, true, NULL, 0);
    }

cleanup:
  pr_clear_value (&prepared);
  if (allocated != NULL)
    {
      db_private_free_and_init (thread_p, allocated);
    }
  if (error != NO_ERROR)
    {
      pr_clear_value (key);
    }
  return error;
}

static int
heap_attrinfo_set_uninitialized (THREAD_ENTRY * thread_p, OID * inst_oid, RECDES * recdes,
				 HEAP_CACHE_ATTRINFO * attr_info)
{
  int i;
  REPR_ID reprid;		/* Representation of object */
  HEAP_ATTRVALUE *value;	/* Disk value Attr info for a particular attr */
  int ret = NO_ERROR;

  ret = heap_attrinfo_check (inst_oid, attr_info);
  if (ret != NO_ERROR)
    {
      goto exit_on_error;
    }

  /*
   * Make sure that we have the needed cached representation.
   */

  if (recdes != NULL)
    {
      reprid = or_rep_id (recdes);
    }
  else
    {
      reprid = attr_info->last_classrepr->id;
    }

  if (attr_info->read_classrepr == NULL || attr_info->read_classrepr->id != reprid)
    {
      /* Get the needed representation */
      ret = heap_attrinfo_recache (thread_p, reprid, attr_info);
      if (ret != NO_ERROR)
	{
	  goto exit_on_error;
	}
    }

  /*
   * Go over the attribute values and set the ones that have not been
   * initialized
   */
  for (i = 0; i < attr_info->num_values; i++)
    {
      value = &attr_info->values[i];
      if (value->state == HEAP_UNINIT_ATTRVALUE)
	{
	  ret = heap_attrvalue_read (recdes, value, attr_info);
	  if (ret != NO_ERROR)
	    {
	      goto exit_on_error;
	    }
	}
      else if (value->state == HEAP_WRITTEN_ATTRVALUE
	       && (value->last_attrepr->type == DB_TYPE_BLOB || value->last_attrepr->type == DB_TYPE_CLOB))
	{
	  DB_VALUE *save;
	  save = db_value_copy (&value->dbvalue);
	  pr_clear_value (&value->dbvalue);

	  /* read and delete old value */
	  ret = heap_attrvalue_read (recdes, value, attr_info);
	  if (ret != NO_ERROR)
	    {
	      goto exit_on_error;
	    }
	  if (!db_value_is_null (&value->dbvalue))
	    {
	      DB_ELO *elo;

	      assert (db_value_type (&value->dbvalue) == DB_TYPE_BLOB
		      || db_value_type (&value->dbvalue) == DB_TYPE_CLOB);
	      elo = db_get_elo (&value->dbvalue);
	      if (elo)
		{
		  ret = db_elo_delete (elo);
		}
	      pr_clear_value (&value->dbvalue);
	      ret = (ret >= 0 ? NO_ERROR : ret);
	      if (ret != NO_ERROR)
		{
		  goto exit_on_error;
		}
	    }
	  value->state = HEAP_WRITTEN_ATTRVALUE;
	  pr_clone_value (save, &value->dbvalue);
	  pr_free_ext_value (save);
	}
    }

  if (recdes != NULL)
    {
      attr_info->inst_chn = or_chn (recdes);
    }
  else
    {
      attr_info->inst_chn = -1;
    }

  return ret;

exit_on_error:

  return (ret == NO_ERROR && (ret = er_errid ()) == NO_ERROR) ? ER_FAILED : ret;
}

static int
heap_attrinfo_get_record_payload_size (HEAP_CACHE_ATTRINFO * attr_info, std::vector<int> * column_size)
// *INDENT-ON*
{
  HEAP_ATTRVALUE *value;
  int size;
  int i;

  size = 0;
  for (i = 0; i < attr_info->num_values; i++)
    {
      value = &attr_info->values[i];

      if (value->last_attrepr->is_fixed != 0)
	{
	  (*column_size)[i] = tp_domain_disk_size (value->last_attrepr->domain);
	  size += (*column_size)[i];
	}
      else
	{
	  (*column_size)[i] = pr_data_writeval_disk_size (&value->dbvalue);
	  size += (*column_size)[i];
	}
    }

  return size;
}

static int
heap_attrinfo_get_record_header_size (HEAP_CACHE_ATTRINFO * attr_info, int payload_size, bool is_mvcc_class,
				      size_t * offset_size_ptr)
{
  int header_size;

  *offset_size_ptr = OR_BYTE_SIZE;

  header_size = is_mvcc_class ? OR_MVCC_INSERT_HEADER_SIZE : OR_NON_MVCC_HEADER_SIZE;
  header_size += OR_VAR_TABLE_SIZE_INTERNAL (attr_info->last_classrepr->n_variable, *offset_size_ptr);
  header_size += OR_BOUND_BIT_BYTES (attr_info->last_classrepr->n_attributes - attr_info->last_classrepr->n_variable);

  if (*offset_size_ptr == OR_BYTE_SIZE && header_size + payload_size > OR_MAX_BYTE)
    {
      header_size -= OR_VAR_TABLE_SIZE_INTERNAL (attr_info->last_classrepr->n_variable, *offset_size_ptr);
      *offset_size_ptr = OR_SHORT_SIZE;	/* 2 byte */
      header_size += OR_VAR_TABLE_SIZE_INTERNAL (attr_info->last_classrepr->n_variable, *offset_size_ptr);
    }
  if (*offset_size_ptr == OR_SHORT_SIZE && header_size + payload_size > OR_MAX_SHORT)
    {
      header_size -= OR_VAR_TABLE_SIZE_INTERNAL (attr_info->last_classrepr->n_variable, *offset_size_ptr);
      *offset_size_ptr = OR_INT_SIZE;	/* 4 byte */
      header_size += OR_VAR_TABLE_SIZE_INTERNAL (attr_info->last_classrepr->n_variable, *offset_size_ptr);
    }

  return header_size;
}

static int
heap_attrinfo_determine_disk_layout (HEAP_CACHE_ATTRINFO * attr_info, bool is_mvcc_class, bool suppress_oos,
					     size_t * offset_size_ptr,
					     std::vector<heap_oos_column_plan> * oos_plan, bool * has_oos,
					     bool * would_demote_oos, size_t * inline_size_after_oos_ptr)
// *INDENT-ON*
{
// *INDENT-OFF*
  std::vector<int> column_size (attr_info->num_values);
// *INDENT-ON*
  int payload_size, header_size;
  int mvcc_extra;
  int i;

  *has_oos = false;
  if (would_demote_oos != NULL)
    {
      *would_demote_oos = false;
    }

  /* calcuate the entire size of columns */
  payload_size = heap_attrinfo_get_record_payload_size (attr_info, &column_size);
  header_size = heap_attrinfo_get_record_header_size (attr_info, payload_size, is_mvcc_class, offset_size_ptr);
  mvcc_extra = is_mvcc_class ? OR_MVCC_MAX_HEADER_SIZE - OR_MVCC_INSERT_HEADER_SIZE : 0;

  /* FORCE_OUTLINE bypasses the normal record-size gate, but values must still be larger than the OOS stub so that
   * moving them out of row shrinks the inline record. */
  for (i = 0; i < attr_info->num_values; i++)
    {
      if (!attr_info->values[i].last_attrepr->is_fixed
	  && attr_info->values[i].last_attrepr->oos_storage == OR_ATTRIBUTE_OOS_STORAGE_FORCE_OUTLINE
	  && !db_value_is_null (&attr_info->values[i].dbvalue) && column_size[i] > OR_OOS_INLINE_SIZE)
	{
	  if (suppress_oos)
	    {
	      if (would_demote_oos != NULL)
		{
		  *would_demote_oos = true;
		}
	      continue;
	    }

	  (*oos_plan)[i].selected = true;
	  payload_size -= column_size[i];
	  payload_size += OR_OOS_INLINE_SIZE;
	  *has_oos = true;
	}
    }

  /* A forced value changes the payload and may change the variable-offset width. */
  header_size = heap_attrinfo_get_record_header_size (attr_info, payload_size, is_mvcc_class, offset_size_ptr);

  /* TODO: change the statistics */
  /* Push the largest remaining variable column to OOS one by one until the heap record fits within
   * DB_PAGESIZE/4 (PG TOAST style), instead of pushing every eligible column. */
  if (header_size + payload_size + mvcc_extra > DB_PAGESIZE / 4)
    {
      // *INDENT-OFF*
      std::vector<heap_oos_demote_candidate> oos_candidates;
      // *INDENT-ON*

      for (i = 0; i < attr_info->num_values; i++)
	{
	  /* a variable column is OOS-eligible only if externalizing it shrinks the inline record:
	   * its value must be larger than the OOS stub (OID + length) it is replaced with */
	  if (!(*oos_plan)[i].selected && !attr_info->values[i].last_attrepr->is_fixed
	      && column_size[i] > OR_OOS_INLINE_SIZE)
	    {
	      // *INDENT-OFF*
	      heap_oos_demote_priority priority =
		heap_oos_get_demote_priority (attr_info->values[i].last_attrepr->oos_storage
					      == OR_ATTRIBUTE_OOS_STORAGE_PREFER_INLINE);
	      oos_candidates.push_back ({ priority, column_size[i], i });
	      // *INDENT-ON*
	    }
	}

      if (suppress_oos)
	{
	  /* The caller only wants a fully-inline image plus the demotion verdict (e.g. to route a
	   * partitioned write before the target heap of its OOS value chains is known). */
	  if (would_demote_oos != NULL && !oos_candidates.empty ())
	    {
	      *would_demote_oos = true;
	    }

	  *inline_size_after_oos_ptr = header_size + payload_size;
	  return NO_ERROR;
	}

      // *INDENT-OFF*
      /* Demote order: columns flagged STORAGE PREFER_INLINE sink to the tail and are externalized
       * only as a last resort; within each priority class, largest first. The idx-descending
       * tiebreak preserves the legacy std::greater<std::pair> order for the no-hint (DEFAULT) case. */
      std::sort (oos_candidates.begin (), oos_candidates.end (), heap_oos_demote_candidate_precedes);
      // *INDENT-ON*

      // *INDENT-OFF*
      for (auto& cand : oos_candidates)
	// *INDENT-ON*
      {
	if (header_size + payload_size + mvcc_extra <= DB_PAGESIZE / 4)
	  {
	    break;
	  }
	(*oos_plan)[cand.attr_index].selected = true;
	payload_size -= cand.size;
	payload_size += OR_OOS_INLINE_SIZE;
	*has_oos = true;
      }

      /* re-calculate the header size */
      header_size = heap_attrinfo_get_record_header_size (attr_info, payload_size, is_mvcc_class, offset_size_ptr);
    }

  *inline_size_after_oos_ptr = header_size + payload_size;
  return NO_ERROR;
}

bool
heap_oos_find_vfid (THREAD_ENTRY * thread_p, const HFID * hfid, VFID * oos_vfid, bool docreate)
{
  HEAP_HDR_STATS *heap_hdr;	/* Header of heap structure */
  LOG_DATA_ADDR addr_hdr;	/* Address of logging data */
  VPID vpid;			/* Page-volume identifier */
  RECDES hdr_recdes;		/* Header record descriptor */
  PGBUF_LATCH_MODE mode;
  bool success;

  success = true;
  VFID_SET_NULL (oos_vfid);

  addr_hdr.vfid = &hfid->vfid;
  addr_hdr.offset = HEAP_HEADER_AND_CHAIN_SLOTID;

  /* Read the header page */
  vpid.volid = hfid->vfid.volid;
  vpid.pageid = hfid->hpgid;

  mode = (docreate == true ? PGBUF_LATCH_WRITE : PGBUF_LATCH_READ);
  addr_hdr.pgptr = pgbuf_fix (thread_p, &vpid, OLD_PAGE, mode, PGBUF_UNCONDITIONAL_LATCH);
  if (addr_hdr.pgptr == NULL)
    {
      goto exit_on_error;
    }

#if !defined (NDEBUG)
  (void) pgbuf_check_page_ptype (thread_p, addr_hdr.pgptr, PAGE_HEAP);
#endif /* !NDEBUG */

  /* Peek the header record */
  if (spage_get_record (thread_p, addr_hdr.pgptr, HEAP_HEADER_AND_CHAIN_SLOTID, &hdr_recdes, PEEK) != S_SUCCESS)
    {
      goto exit_on_error;
    }

  heap_hdr = (HEAP_HDR_STATS *) hdr_recdes.data;
  if (VFID_ISNULL (&heap_hdr->oos_vfid))
    {
      if (docreate == true)
	{
	  TDE_ALGORITHM tde_algo = TDE_ALGORITHM_NONE;

	  /* START A TOP SYSTEM OPERATION */
	  log_sysop_start (thread_p);
	  if (oos_create_file (thread_p, *hfid, heap_hdr->class_oid, *oos_vfid) != NO_ERROR)
	    {
	      log_sysop_abort (thread_p);
	      goto exit_on_error;
	    }

	  /* Apply TDE to the new OOS file atomically with its creation.
	   * Pattern mirrors heap_ovf_find_vfid */
	  if (heap_get_class_tde_algorithm (thread_p, &heap_hdr->class_oid, &tde_algo) != NO_ERROR)
	    {
	      log_sysop_abort (thread_p);
	      goto exit_on_error;
	    }

	  if (file_apply_tde_algorithm (thread_p, oos_vfid, tde_algo) != NO_ERROR)
	    {
	      log_sysop_abort (thread_p);
	      goto exit_on_error;
	    }

	  /* Log undo, then redo */
	  log_append_undo_data (thread_p, RVHF_STATS, &addr_hdr, sizeof (*heap_hdr), heap_hdr);
	  VFID_COPY (&heap_hdr->oos_vfid, oos_vfid);
	  log_append_redo_data (thread_p, RVHF_STATS, &addr_hdr, sizeof (*heap_hdr), heap_hdr);
	  pgbuf_set_dirty (thread_p, addr_hdr.pgptr, DONT_FREE);

	  log_sysop_commit (thread_p);
	}
      else
	{
	  /* No OOS file exists yet; oos_vfid stays NULL. This is not an error. */
	  goto end;
	}
    }
  else
    {
      VFID_COPY (oos_vfid, &heap_hdr->oos_vfid);
    }

  goto end;

exit_on_error:
  success = false;

end:
  if (addr_hdr.pgptr)
    {
      pgbuf_unfix_and_init (thread_p, addr_hdr.pgptr);
    }

  return success;
}

static SCAN_CODE
heap_attrinfo_dbvalue_to_recdes (THREAD_ENTRY * thread_p, HEAP_ATTRVALUE * value, OID class_oid, int lob_create_flag,
				 RECDES * recdes)
{
  DB_VALUE *dbvalue;
  const PR_TYPE *pr_type;
  DB_ELO dest_elo, *elo_p;
  char *save_meta_data, *new_meta_data;
  int length;
  int rv;
  OR_BUF buf;

  pr_type = value->last_attrepr->domain->type;
  if (pr_type == NULL)
    {
      return S_ERROR;
    }

  dbvalue = &value->dbvalue;

  assert (dbvalue != NULL && !db_value_is_null (dbvalue));

  if (lob_create_flag == LOB_FLAG_INCLUDE_LOB && value->state == HEAP_WRITTEN_ATTRVALUE
      && (pr_type->id == DB_TYPE_BLOB || pr_type->id == DB_TYPE_CLOB))
    {
      assert (db_value_type (dbvalue) == DB_TYPE_BLOB || db_value_type (dbvalue) == DB_TYPE_CLOB);

      elo_p = db_get_elo (dbvalue);

      if (elo_p == NULL)
	{
	  /* nothing to do here */
	  return S_SUCCESS;
	}

      if (heap_get_class_name (thread_p, &class_oid, &new_meta_data) != NO_ERROR || new_meta_data == NULL)
	{
	  return S_ERROR;
	}
      save_meta_data = elo_p->meta_data;
      elo_p->meta_data = new_meta_data;
      {
	HFID hfid;
	char lob_path_prefix[PATH_MAX];

	heap_hfid_cache_get (thread_p, &class_oid, &hfid, NULL, NULL);
	snprintf (lob_path_prefix, PATH_MAX, "%d%d%d%d", HFID_AS_ARGS (&hfid), value->attrid);
	rv = db_elo_copy_with_prefix (db_get_elo (dbvalue), lob_path_prefix, &dest_elo);
      }

      free_and_init (elo_p->meta_data);
      elo_p->meta_data = save_meta_data;

      /* The purpose of HEAP_WRITTEN_LOB_ATTRVALUE is to avoid reenter this branch. In the first pass,
       * this branch is entered and elo is copied. When BUFFER_OVERFLOW happens, we need avoid to copy
       * elo again. Otherwize it will generate 2 copies. */
      value->state = HEAP_WRITTEN_LOB_ATTRVALUE;

      if (rv < 0)
	{
	  return S_ERROR;
	}

      pr_clear_value (dbvalue);
      db_make_elo (dbvalue, pr_type->id, &dest_elo);
      dbvalue->need_clear = true;
    }

  length = pr_type->get_disk_size_of_value (dbvalue);
  if (length > recdes->area_size)
    {
      recdes->area_size = length;
      recdes->data = (char *) malloc (length);
      if (recdes->data == NULL)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, (size_t) length);
	  return S_ERROR;
	}
    }

  buf.ptr = buf.buffer = recdes->data;
  buf.endptr = recdes->data + length;
  pr_type->data_writeval (&buf, dbvalue);
  recdes->length = length;

  return S_SUCCESS;
}

static SCAN_CODE
heap_attrinfo_serialize_oos_value (THREAD_ENTRY * thread_p, HEAP_CACHE_ATTRINFO * attr_info, int index,
				   int lob_create_flag, RECDES * payload)
{
  assert (attr_info->values != NULL && !db_value_is_null (&attr_info->values[index].dbvalue));
  assert (!attr_info->values[index].last_attrepr->is_fixed);

  if (heap_attrinfo_dbvalue_to_recdes (thread_p, &attr_info->values[index], attr_info->class_oid, lob_create_flag,
				       payload) != S_SUCCESS)
    {
      return S_ERROR;
    }

  if (payload->data == NULL || payload->length <= 0)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_GENERIC_ERROR, 0);
      free_and_init (payload->data);
      return S_ERROR;
    }

  return S_SUCCESS;
}

static SCAN_CODE
heap_attrinfo_prepare_oos_insert_requests (THREAD_ENTRY * thread_p, HEAP_CACHE_ATTRINFO * attr_info,
					   int lob_create_flag,
					   std::vector < heap_oos_column_plan > *oos_plan,
					   std::vector < RECDES > *payloads,
					   std::vector < oos_insert_request > *requests)
{
  int i;

  for (i = 0; i < attr_info->num_values; i++)
    {
      heap_oos_column_plan & plan = (*oos_plan)[i];
      RECDES payload = { 0, 0, REC_HOME, NULL };

      if (!plan.selected)
	{
	  continue;
	}

      if (heap_attrinfo_serialize_oos_value (thread_p, attr_info, i, lob_create_flag, &payload) != S_SUCCESS)
	{
	  free_and_init (payload.data);
	  return S_ERROR;
	}

      plan.length = (DB_BIGINT) payload.length;
      oos_insert_request request = { oos_buffer (payload.data, (size_t) payload.length), &plan.oid };
      payloads->push_back (payload);
      requests->push_back (request);
    }

  return S_SUCCESS;
}

static void
heap_attrinfo_free_oos_payloads (std::vector < RECDES > *payloads)
{
  // *INDENT-OFF*
  for (RECDES &payload : *payloads)
    {
      free_and_init (payload.data);
    }
  // *INDENT-ON*
  payloads->clear ();
}

static SCAN_CODE
heap_attrinfo_insert_to_oos (THREAD_ENTRY * thread_p, HEAP_CACHE_ATTRINFO * attr_info, int lob_create_flag,
			     const OID * oos_class_oid, std::vector<heap_oos_column_plan> * oos_plan)
// *INDENT-ON*

{
  // *INDENT-OFF*
  std::vector < RECDES > payloads;
  std::vector < oos_insert_request > requests;
  SCAN_CODE scan_code = S_ERROR;

  if (heap_oos_begin_insert_publication (thread_p) != S_SUCCESS)
    {
      return S_ERROR;
    }

#if defined(CUBRID_UNIT_TEST_ENABLED)
  if (heap_Test_fail_after_oos_publication_reset.exchange (false, std::memory_order_relaxed))
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_GENERIC_ERROR, 0);
      return S_ERROR;
    }
#endif

  try
  {
    payloads.reserve (attr_info->num_values);
    requests.reserve (attr_info->num_values);
  }
  catch (const std::bad_alloc &)
  {
    er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1,
	    (size_t) attr_info->num_values * (sizeof (RECDES) + sizeof (oos_insert_request)));
    return S_ERROR;
  }

  if (heap_attrinfo_prepare_oos_insert_requests (thread_p, attr_info, lob_create_flag, oos_plan, &payloads,
						 &requests) != S_SUCCESS)
    {
      goto cleanup;
    }

  if (heap_oos_insert_serialized_values (thread_p, oos_class_oid != NULL ? oos_class_oid : &attr_info->class_oid,
					 cubbase::span < oos_insert_request > (requests.data (), requests.size ()))
      != S_SUCCESS)
    {
      goto cleanup;
    }

  scan_code = S_SUCCESS;

cleanup:
  heap_attrinfo_free_oos_payloads (&payloads);
  return scan_code;
  // *INDENT-ON*
}

